INSERT INTO easa_subjects (module_id, code, title, sort_order) VALUES
  (7, 'M07.9', 'Exam Question Bank', 9)
    INSERT INTO questions (subject_id, text, options, licence_types) VALUES
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using an analogue multimeter to measure the forward resistance of a diode the meter lead marked positive must be connected to:', '[{"id": "a", "text": "The anode connection of the diode", "correct": false}, {"id": "b", "text": "Either the anode or cathode connection since the meter includes a bridge rectifier", "correct": false}, {"id": "c", "text": "The cathode connection of the diode", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The tendency of tail wheel type aeroplanes to turn into wind is greater while taxiing with a:', '[{"id": "a", "text": "Quartering headwind", "correct": false}, {"id": "b", "text": "Direct cross wind", "correct": true}, {"id": "c", "text": "Tail wind", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When determining chain elongation the measurements should be taken:', '[{"id": "a", "text": "From end to end", "correct": true}, {"id": "b", "text": "From adjacent bearing pin centres", "correct": false}, {"id": "c", "text": "Between adjacent links", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should wire splices in an electrical wire bundle be arranged?', '[{"id": "a", "text": "Grouped together", "correct": false}, {"id": "b", "text": "Staggered along the length of the bundle", "correct": true}, {"id": "c", "text": "Enclosed in a conduit", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When installing a pipe, the clamps must be located:', '[{"id": "a", "text": "As close to bends as possible", "correct": true}, {"id": "b", "text": "Within 9 inches of each other", "correct": false}, {"id": "c", "text": "As far as possible away from bends", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The process of soldering causes:', '[{"id": "a", "text": "Welding", "correct": false}, {"id": "b", "text": "Fusion", "correct": false}, {"id": "c", "text": "Brazing", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The test equipment normally used to carry out a continuity test on an electrical cable is:', '[{"id": "a", "text": "A high reading ohmmeter", "correct": false}, {"id": "b", "text": "A low reading ohmmeter", "correct": true}, {"id": "c", "text": "A bonding meter", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following can provide the empty weight of an aircraft if the weight and balance records are lost or destroyed?', '[{"id": "a", "text": "Reweighing the aircraft", "correct": true}, {"id": "b", "text": "The applicable flight manual in combination with the type certificate data sheet", "correct": false}, {"id": "c", "text": "The aircraft operational manual (AOM)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What method is recommended to protect bearings against corrosion while in storage?', '[{"id": "a", "text": "Oil and wrap in grease proof paper and position horizontally", "correct": true}, {"id": "b", "text": "Cover in grease and position vertically on shelf", "correct": false}, {"id": "c", "text": "Cover in grease and wrap in grease proof paper", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In relation to aircraft materials what does the term ‘gauge’ mean?', '[{"id": "a", "text": "Thickness of material", "correct": true}, {"id": "b", "text": "Surface area of material", "correct": false}, {"id": "c", "text": "Length only of material", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An oscilloscope has graticule of 1 square centimetre and its TIME/CM is set to 1 millisecond. The measured waveform is 2 centimetres wide, what is a period of the waveform?', '[{"id": "a", "text": "1 millisecond", "correct": false}, {"id": "b", "text": "2 milliseconds", "correct": true}, {"id": "c", "text": "4 milliseconds", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What determines the minimum rivet spacing?', '[{"id": "a", "text": "Rivet diameter", "correct": true}, {"id": "b", "text": "Type of material being riveted", "correct": false}, {"id": "c", "text": "Rivet length", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Exposure to and/or storage near which of the following is considered harmful to aircraft tyres:', '[{"id": "a", "text": "Low humidity, fuel, oil, helium, hydraulic fluid, solvents", "correct": false}, {"id": "b", "text": "Fuel, oil, ozone, electrical equipment, hydraulic fluid, solvents", "correct": true}, {"id": "c", "text": "Fuel, oil, ozone, helium, electrical equipment, hydraulic fluid, solvents", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To support electrical cables along the run the use of non-metallic clamps is preferred. What could be used as a means of supplemental support between clamps?', '[{"id": "a", "text": "Adhesive tape", "correct": false}, {"id": "b", "text": "Lacing", "correct": true}, {"id": "c", "text": "Fine wire", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a pilot reported a heavy landing what areas of the aircraft are most likely to show visible signs of damage?', '[{"id": "a", "text": "Missing or pulled fasteners in the wing to body fairing", "correct": false}, {"id": "b", "text": "Flat spots on the aircraft tyres", "correct": true}, {"id": "c", "text": "Cracks in the cabin window", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On the screen of an oscilloscope the measured effective voltage is:', '[{"id": "a", "text": "V=15 volts", "correct": false}, {"id": "b", "text": "V= 10.6 volts", "correct": true}, {"id": "c", "text": "V= 21.2 volts", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'While an aircraft is being towed, a qualified person should be in the cockpit. What is the function of this person?', '[{"id": "a", "text": "To stop the aircraft during normal towing", "correct": false}, {"id": "b", "text": "To stop the aircraft using the brakes only in an emergency", "correct": true}, {"id": "c", "text": "To steer the aircraft as it is being towed", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is it important to keep electrical wiring separate from fluid lines?', '[{"id": "a", "text": "A fluid line cannot carry the load", "correct": false}, {"id": "b", "text": "To prevent a fire in case of an arcing fault", "correct": true}, {"id": "c", "text": "It looks nice", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'General-purpose solders are an alloy of?', '[{"id": "a", "text": "Tin, soft iron and lead", "correct": false}, {"id": "b", "text": "Copper and lead", "correct": false}, {"id": "c", "text": "Tin and lead", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In welding corrosion resistance steel (C.R.E.S). What gas is used in order to prevent deformation?', '[{"id": "a", "text": "Oxygen gas", "correct": false}, {"id": "b", "text": "Acetylene gas", "correct": false}, {"id": "c", "text": "Argon gas", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How is mercury spillage normally detected?', '[{"id": "a", "text": "Ultrasonic inspection", "correct": false}, {"id": "b", "text": "X-Ray inspection", "correct": true}, {"id": "c", "text": "Magnetic inspection", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How is the edge margin defined?', '[{"id": "a", "text": "It is the distance from the centre of the hole to the next hole", "correct": false}, {"id": "b", "text": "The edge margin is the same distance as the spacing", "correct": false}, {"id": "c", "text": "It is the distance from the centre of a hole to the nearest edge of the sheet", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In the ISO system of fits and clearances, the types of fits used are:', '[{"id": "a", "text": "Clearance fit, interference fit and transition fit", "correct": true}, {"id": "b", "text": "Loose fit, exact fit and clearance fit", "correct": false}, {"id": "c", "text": "Interference fit, limit fit and clearance fit", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aircraft structural units such as spars, engine supports etc., which have been built up from sheet metal are normally:', '[{"id": "a", "text": "Repairable, except when subjected to compressive loads", "correct": false}, {"id": "b", "text": "Repairable, using approved methods and data", "correct": true}, {"id": "c", "text": "Not repairable, but must be replaced when damaged or deteriorated", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Two resistors, 100 kilo Ohm and 200 kilo Ohm are connected in series to a 12V battery. You are measuring the voltage across the 200kiloOhm resistor. The voltmeter has an internal resistance of 20kiloOhm/V and is set to the 25V range. What will the voltmeter read?', '[{"id": "a", "text": "6.2 V", "correct": false}, {"id": "b", "text": "8 V", "correct": false}, {"id": "c", "text": "7 V", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A vernier is calibrated by using which of the following?', '[{"id": "a", "text": "A calibration meter", "correct": false}, {"id": "b", "text": "A vee block", "correct": false}, {"id": "c", "text": "A gauge block", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The correct method of installing a duct assembly is as follows:', '[{"id": "a", "text": "Clamp, check alignment then torque", "correct": true}, {"id": "b", "text": "Check alignment torque then clamp", "correct": false}, {"id": "c", "text": "Torque check alignment then clamp", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The dimension of a bore hole is 20H7/f7, where H7 = 0 to +21 µm and f7 = -20 to -41 µm. How great is the tolerance zone of the shaft?', '[{"id": "a", "text": "-41 to -20 = 0.021 mm", "correct": true}, {"id": "b", "text": "0 to +21 = 0.021 mm", "correct": false}, {"id": "c", "text": "41 to -21 = 0.021 mm", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inspecting an area from which a component has been removed a large area of corrosion is found, what steps should be taken in general?', '[{"id": "a", "text": "The corrosion should be removed and the area protected", "correct": false}, {"id": "b", "text": "The corrosion should be removed and the area protected and the cause of the corrosion", "correct": true}, {"id": "c", "text": "The part should be scrapped and a new part fitted", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A sheet metal repair is to be made using two pieces of 0.040-inch aluminium riveted together. All rivet holes are drilled for 3/32-inch rivets. The length of the rivets to be used will be:', '[{"id": "a", "text": "¼ inch", "correct": true}, {"id": "b", "text": "5/16 inch", "correct": false}, {"id": "c", "text": "1/8 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the colour of an acetylene cylinder?', '[{"id": "a", "text": "Maroon", "correct": true}, {"id": "b", "text": "Green", "correct": false}, {"id": "c", "text": "Blue", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The empty weight of an aeroplane is determined by:', '[{"id": "a", "text": "Multiplying the measured distance from each weighing point to the datum less the tare weight", "correct": false}, {"id": "b", "text": "Subtracting the tare weight from the scale reading and adding the weight of each weighing", "correct": true}, {"id": "c", "text": "Adding the net weight of each weighing point and multiplying the measured distance to the datum", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Excessive wear on both of the sides of a control cable pulley groove is evidence of:', '[{"id": "a", "text": "Pulley misalignment", "correct": true}, {"id": "b", "text": "Excessive cable tension", "correct": false}, {"id": "c", "text": "Cable misalignment", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is it not permissible to safety a B-nut with a check nut?', '[{"id": "a", "text": "Because B nuts and jamb nuts both lock in the same direction", "correct": true}, {"id": "b", "text": "Because the B nut and the jamb nut are of different materials", "correct": false}, {"id": "c", "text": "Because jamb nuts cannot be torqued", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Repairs or splices involving stringers on the lower surface of stressed skin metal wings are usually:', '[{"id": "a", "text": "Not permitted", "correct": false}, {"id": "b", "text": "Permitted only if the damage does not exceed 6 inches in any direction", "correct": false}, {"id": "c", "text": "Permitted but are normally more critical in reference to strength in tension than similar", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If bulging is evident between rivets in the lap joint what does this indicate?', '[{"id": "a", "text": "Loose rivets", "correct": false}, {"id": "b", "text": "An over pressurization", "correct": false}, {"id": "c", "text": "Corrosion in the lap joint", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A bolt with an X inside a triangle on the head is classified as an:', '[{"id": "a", "text": "AN corrosion resistance steel bolt", "correct": false}, {"id": "b", "text": "NAS close tolerance bolt", "correct": true}, {"id": "c", "text": "NAS standard aircraft bolt", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During the complete overhaul of a turbo-jet engine you inspect the compressor main bearings. Their general state is correct, but you notice that some of them are magnetised. You decide:', '[{"id": "a", "text": "To reinstalled them like this", "correct": false}, {"id": "b", "text": "To shift them at 180 when reinstalling them to cancel magnetic fields", "correct": false}, {"id": "c", "text": "To apply demagnetization or if not to replace them", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What determines the minimum bend radius?', '[{"id": "a", "text": "The hardness and thickness of the material", "correct": true}, {"id": "b", "text": "Usage of the part", "correct": false}, {"id": "c", "text": "The material thickness and bend length", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The recommended drill size for removing a rivet is:', '[{"id": "a", "text": "A slightly larger diameter than the rivet shank", "correct": false}, {"id": "b", "text": "A smaller diameter than the rivet shank", "correct": true}, {"id": "c", "text": "The same size of the rivet shank", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The oxyacetylene flame for silver soldering should be:', '[{"id": "a", "text": "Carburizing", "correct": false}, {"id": "b", "text": "Oxidizing", "correct": false}, {"id": "c", "text": "Neutral", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On an aircraft when the beacon light is on it means that:', '[{"id": "a", "text": "Aircraft refueling is taking place", "correct": false}, {"id": "b", "text": "One engine is running or is going to be started", "correct": true}, {"id": "c", "text": "Landing gears are under way", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Before weighing an aircraft, it is necessary to become familiar with the aircraft CG range given in the weight and balance information in:', '[{"id": "a", "text": "The applicable aircraft specification or type certificate data sheet", "correct": true}, {"id": "b", "text": "AC43.13-2A chapter 11", "correct": false}, {"id": "c", "text": "AC43.13 -1A, chapter 12", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the main reason that Meggers use a high voltage when measuring resistances?', '[{"id": "a", "text": "To ensure that good connections to the equipment under test are established", "correct": false}, {"id": "b", "text": "To push measurable currents through the very high test resistances", "correct": false}, {"id": "c", "text": "To stress the insulation of the test circuit to near its operating value so that any electrical", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Under what condition may a component be drawn from the quarantine store and fitted to an aircraft?', '[{"id": "a", "text": "Thickness of the material is less than the thickness of the rivet head", "correct": false}, {"id": "b", "text": "Thickness of the material and rivet diameter are the same", "correct": false}, {"id": "c", "text": "Thickness of the material is greater than the thickness of the rivet head", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When installing a new antenna the strength that has been lost in the airframe structure is replaced by:', '[{"id": "a", "text": "Riveting a doubler inside the skin", "correct": true}, {"id": "b", "text": "Doubler and epoxy glue", "correct": false}, {"id": "c", "text": "The antenna itself", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When rivets are to be removed:', '[{"id": "a", "text": "Chisel and rivet head off and drive out the shank", "correct": false}, {"id": "b", "text": "Weaken the rivet head by drilling break off the head and drive out the shank", "correct": true}, {"id": "c", "text": "File the rivet head off and drive out the shank", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Test equipment such as meters, torque wrenches, and static and transported test equipment should be checked at least:', '[{"id": "a", "text": "Quarantine part can only be used after overhaul", "correct": true}, {"id": "b", "text": "It can be fitted to an aircraft after rectification of the component", "correct": false}, {"id": "c", "text": "It can be used after in-situ functional test", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'For an effective dry-penetrant check the material being checked must:', '[{"id": "a", "text": "Have surface cracks", "correct": true}, {"id": "b", "text": "Be magnetic", "correct": false}, {"id": "c", "text": "Have subsurface crack", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When the brake parking lever is moved to the “PARKED” position the port and starboard brake pressure gauges:', '[{"id": "a", "text": "Should show brake specific pressure", "correct": true}, {"id": "b", "text": "Should give not indication", "correct": false}, {"id": "c", "text": "Will usually show half scale deflection", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Test equipment such as meters torque wrenches static and transported test equipment should be checked at least:', '[{"id": "a", "text": "Once every 3rd year", "correct": false}, {"id": "b", "text": "Once a year", "correct": true}, {"id": "c", "text": "Once a month", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Term used for defining the tendency of some liquids to penetrate inside small opening cracks is:', '[{"id": "a", "text": "Saturation", "correct": false}, {"id": "b", "text": "Capillary action", "correct": true}, {"id": "c", "text": "Plotting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A screw should be torqued to 3000 Ncm. If the available wrenches are calibrated in inch-pounds, the setting to be made should be:', '[{"id": "a", "text": "325.8 inlbs", "correct": false}, {"id": "b", "text": "265.4 inlbs", "correct": true}, {"id": "c", "text": "175.1 inlbs", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What effect does a mercury spillage have on aircraft skin?', '[{"id": "a", "text": "Extending and checking for corrosion", "correct": false}, {"id": "b", "text": "Placing a weight on it", "correct": true}, {"id": "c", "text": "Measuring spring diameter", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When performing a dye penetrant test, spherical indications on a surface would indicate:', '[{"id": "a", "text": "Weld laps", "correct": false}, {"id": "b", "text": "Fatigue cracks", "correct": false}, {"id": "c", "text": "Porosity", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When reading a blueprint, a dimension is given as 4.387 inches +.005 -.002. Which statement is true?', '[{"id": "a", "text": "The location of the centre of gravity in relation to the mean aerodynamic chord", "correct": false}, {"id": "b", "text": "The location of the weighing points", "correct": true}, {"id": "c", "text": "The required weight and distribution of uploaded minimum usable fuel", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What effect has a mercury spillage on aircraft skin?', '[{"id": "a", "text": "It effect in navigation systems", "correct": false}, {"id": "b", "text": "None, but it present a danger to passengers", "correct": false}, {"id": "c", "text": "It causes embrittlement of the material", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During a visual inspection of a cylindrical compression spring it is necessary to check:', '[{"id": "a", "text": "There are no cracks, there is no corrosion and the free length is correct", "correct": false}, {"id": "b", "text": "There are no cracks, there is no corrosion and there is no misalignment of loops", "correct": false}, {"id": "c", "text": "There is no corrosion, the free length is correct and the length under load is correct", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Objects shown in isometric projection have three sides visible. The angle used to indicate this would be:', '[{"id": "a", "text": "The minimum acceptable size is 4.385 inches", "correct": true}, {"id": "b", "text": "The minimum acceptable size is 4.382 inches", "correct": false}, {"id": "c", "text": "The maximum acceptable size is 4.390 inches", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Skydrol:', '[{"id": "a", "text": "Is relatively harmless to the skin", "correct": false}, {"id": "b", "text": "Is very flammable", "correct": false}, {"id": "c", "text": "Has got a harmful effect on paint and lacquer", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The cable-operated control system of an all-metal aircraft, not incorporating a temperature-compensating device, has been rigged to the correct tension in a heated hangar. If the aircraft is operated in very cold weather, the cable tension will:', '[{"id": "a", "text": "Increase when the aircraft structure and cables become cold", "correct": false}, {"id": "b", "text": "Be unaffected if stainless steel cable is installed", "correct": false}, {"id": "c", "text": "Decrease, when the aircraft structure and cables become cold", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Objects shown in isometric projection have three sides visible the angle used to indicate this would be:', '[{"id": "a", "text": "60 deg. For respective drawings", "correct": false}, {"id": "b", "text": "120 deg. For pictorial drawings", "correct": true}, {"id": "c", "text": "45 deg. For schematic drawings", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a dimension on a drawing was given as 100mm plus/minus 10% then the actual measurements can be between:', '[{"id": "a", "text": "100mm and 110mm", "correct": false}, {"id": "b", "text": "90mm and 100mm", "correct": false}, {"id": "c", "text": "90mm and 110mm", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following methods is recommended for inspecting the surface of a cable for broken wires:', '[{"id": "a", "text": "Run a small magnet over a cable. The broken wires are pulled out and easy to see", "correct": false}, {"id": "b", "text": "Bend the cable", "correct": false}, {"id": "c", "text": "Rub a piece of cloth back and forth over a length of the cable", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'From the safety precautions listed below, which provides the most important combination?', '[{"id": "a", "text": "If no fire hazard inside the fuel tank exists and personnel breathing air supply is provided", "correct": false}, {"id": "b", "text": "If the tank is appropriately ventilated (no toxic gas concentration)", "correct": true}, {"id": "c", "text": "The vapor tester shows 30% lower ignition limit and the appropriate work clothes are worn", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Following a lightning strike the inspection to be carried out will primarily consider the point(s) of:', '[{"id": "a", "text": "Entry", "correct": false}, {"id": "b", "text": "Entry and exit", "correct": true}, {"id": "c", "text": "Exit", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the reference datum line is placed at the nose of an aeroplane rather than at the firewall or some other location aft of the nose:', '[{"id": "a", "text": "All measurements arms will be in negative numbers", "correct": false}, {"id": "b", "text": "All measurements arms will be in positive numbers", "correct": true}, {"id": "c", "text": "Measurement arms will be in both positive and negative numbers", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'From the safety precaution listed below which provides the most important combination?', '[{"id": "a", "text": "A well ventilated area do not mix “skydrol” with a phosphate ester base fluid", "correct": false}, {"id": "b", "text": "Application of barrier cream use of suitable gloves do not mix MIL 5606 with a phosphate", "correct": true}, {"id": "c", "text": "Application of barrier cream use of eye protection and do not mix MIL 5606 with fluid 41", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following AMP crimped terminal lugs will have two dots after they have been crimped correctly?', '[{"id": "a", "text": "An AMP terminal lug with a red sleeve", "correct": false}, {"id": "b", "text": "An AMP terminal lug with a yellow sleeve", "correct": false}, {"id": "c", "text": "An AMP terminal lug with a blue sleeve", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the travel of an aeroplane’s flight controls is correct but the cables are rigged exceptionally tight, the probable effect when flying the aircraft will be that:', '[{"id": "a", "text": "The aeroplane will tend to drop one wing", "correct": false}, {"id": "b", "text": "The aeroplane controls will be heavy", "correct": true}, {"id": "c", "text": "The pilot will be unable to fly the aeroplane hands free", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The servicing and charging of nickel-cadmium and lead-acid batteries together in the same service area is likely to result in:', '[{"id": "a", "text": "Normal battery service life", "correct": false}, {"id": "b", "text": "Contamination of both types of batteries", "correct": true}, {"id": "c", "text": "Increase change of explosion", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum weight of a given aircraft can normally be found:', '[{"id": "a", "text": "By adding the weight of unusable fuel, pilots, passengers, and baggage to the empty weight", "correct": false}, {"id": "b", "text": "By adding the empty weight and the payload", "correct": false}, {"id": "c", "text": "In the type certificate data sheet", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The term H.I.R.F denotes:', '[{"id": "a", "text": "High intensity radiated fields", "correct": true}, {"id": "b", "text": "High interference radio frequency", "correct": false}, {"id": "c", "text": "High intensity radio fields", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the medium used to form a joint in brazing:', '[{"id": "a", "text": "Aluminium rod", "correct": false}, {"id": "b", "text": "Silver rod", "correct": true}, {"id": "c", "text": "Brass Spelter", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What determines whether the value of the moments is preceded by a plus (+) or a minus (-) sign in aircraft weight and balance?', '[{"id": "a", "text": "The location of the weight in reference to the datum", "correct": false}, {"id": "b", "text": "The additional or removal of weight", "correct": false}, {"id": "c", "text": "The result of the weight added or removed and its location relative to the datum", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Blueing in a bearing would indicate:', '[{"id": "a", "text": "The bearing running loose", "correct": false}, {"id": "b", "text": "Wrong lubricant", "correct": false}, {"id": "c", "text": "Overheating", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A single lightning strike will normally produce damage to how many areas of the aircraft?', '[{"id": "a", "text": "Three", "correct": false}, {"id": "b", "text": "Two", "correct": true}, {"id": "c", "text": "One", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When reaming light alloy:', '[{"id": "a", "text": "No lubrication is required", "correct": false}, {"id": "b", "text": "The lubricant specified for drilling operations should be used", "correct": true}, {"id": "c", "text": "Only lard oil should be used as a lubricant", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which statement concerning a welding process is true?', '[{"id": "a", "text": "In the metallic- arc welding process filler material if needed is provided by a separate metal rod of the", "correct": false}, {"id": "b", "text": "The inert-arc welding process uses an inert gas to protect the weld zone from the", "correct": true}, {"id": "c", "text": "In the oxyacetylene welding process the filler rod used for steel is covered with a thin coating of flux", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In aircraft electrical systems:', '[{"id": "a", "text": "Shielded cables do not always have to be earthed", "correct": false}, {"id": "b", "text": "Coaxial cables are earthed at both ends", "correct": true}, {"id": "c", "text": "Coaxial cables should be earthed at one end only", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the pressure in an oxygen cylinder used in welding?', '[{"id": "a", "text": "240 psi", "correct": false}, {"id": "b", "text": "2400 psi", "correct": true}, {"id": "c", "text": "2000 psi", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When an empty aircraft is weighed, the combined net weight at the main gears is 3,540 pounds with an arm of 195.5 inches. At the nose gear the net weight is 2,322 pounds with an arm of 83.5 inches. The datum line is forward of the nose of the aircraft. What is the empty CG of the aircraft?', '[{"id": "a", "text": "151.1", "correct": true}, {"id": "b", "text": "158.7", "correct": false}, {"id": "c", "text": "155.2", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'With reference to soft soldering, the term 40-60 indicates:', '[{"id": "a", "text": "Tin content", "correct": true}, {"id": "b", "text": "Temperature", "correct": false}, {"id": "c", "text": "Lead content", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During start-up of a turbine engine a fire extinguisher will be provided. Which of the following extinguishers may not be used?', '[{"id": "a", "text": "Halon 1211", "correct": false}, {"id": "b", "text": "Trifluorbrommethan", "correct": true}, {"id": "c", "text": "CO2 extinguisher", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When repairing a small hole on a metal stressed skin the major consideration in the design of the patch should be:', '[{"id": "a", "text": "That the bond between the patch and the skin is sufficient to prevent dissimilar metal corrosion", "correct": false}, {"id": "b", "text": "To use rivet spacing similar to a seam in the skin", "correct": false}, {"id": "c", "text": "The shear strength of the riveted joint", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The measurement tool used to check the resistor of a glass fibre static discharger is:', '[{"id": "a", "text": "A Wheatstone bridge on a «100 ohms» setting", "correct": false}, {"id": "b", "text": "An ohmmeter on a «1 ohm» setting", "correct": false}, {"id": "c", "text": "A megohmeter on a «100 megohms» setting", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'One purpose of a schematic diagram is to show the:', '[{"id": "a", "text": "Functional location of components within a system", "correct": true}, {"id": "b", "text": "Physical location of components within a system", "correct": false}, {"id": "c", "text": "Size and shape of components within a system", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should sheet aluminium be stored:', '[{"id": "a", "text": "Cool and dark store room", "correct": false}, {"id": "b", "text": "Upright on racks, different alloys separated and protected from scratching", "correct": true}, {"id": "c", "text": "Laid flat on top of each other (thinnest sheet on top)", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of extinguishing medium should not be used on a class C fire:', '[{"id": "a", "text": "Water", "correct": true}, {"id": "b", "text": "Foam", "correct": false}, {"id": "c", "text": "CO2", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following is acceptable following completion of a solder joint:', '[{"id": "a", "text": "Rough and grainy texture to the solder surface", "correct": false}, {"id": "b", "text": "Smooth and shiny texture to the solder surface", "correct": true}, {"id": "c", "text": "Solder wicking under insulation", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Magnetic particle test can be carried out on:', '[{"id": "a", "text": "Composite material only", "correct": false}, {"id": "b", "text": "All types of aircraft materials", "correct": false}, {"id": "c", "text": "Ferrous material only", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is aircraft riveting mostly performed in the “cold” condition?', '[{"id": "a", "text": "Rivets are always stressed with shear loads", "correct": false}, {"id": "b", "text": "Cold deformation increase the strength", "correct": true}, {"id": "c", "text": "Sheet metals are mostly heat treated", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of spring can have ground ends?', '[{"id": "a", "text": "Torque spring", "correct": false}, {"id": "b", "text": "Compression spring", "correct": true}, {"id": "c", "text": "Extension spring", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the thread pitch of a micrometer and how many increments have to be on the drum scale to achieve 0.01 mm accuracy?', '[{"id": "a", "text": "0.1 mm screw pitch and 100 increments", "correct": false}, {"id": "b", "text": "0.01 mm screw pitch, 100 increments", "correct": false}, {"id": "c", "text": "1mm screw pitch, 100 increments", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When "meggering" a wire in the system in order to perform an insulation test, one should:', '[{"id": "a", "text": "Disconnect the wire on both sides connect one side of the wire to one of the terminals of the megger", "correct": false}, {"id": "b", "text": "Disconnect the wire on both sides connect one side of the wire to ground and the other side of the wire", "correct": false}, {"id": "c", "text": "Disconnect the wire of one side and connect this side of the wire to one of the terminals of", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In aircraft structures it is sometimes necessary to fabricate parts. This may involve annealing the material. Repeated annealing will cause:', '[{"id": "a", "text": "Material to crack", "correct": false}, {"id": "b", "text": "Expansion of material", "correct": false}, {"id": "c", "text": "Mechanical hardening", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Placing a piece of cloth around a stainless steel control cable and running it back and forth over the length of the cable is generally a satisfactory method of:', '[{"id": "a", "text": "Inspecting for broken wires", "correct": true}, {"id": "b", "text": "Applying par-al-ketone", "correct": false}, {"id": "c", "text": "Inspecting for wear and corrosion", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A mechanic has completed a bonded honeycomb repair using the potted compound repair technique. What non-destructive testing method is used to determine the soundness of the repair after the repair has cured?', '[{"id": "a", "text": "Metallic ring test", "correct": true}, {"id": "b", "text": "Eddy current test", "correct": false}, {"id": "c", "text": "Ultrasonic test", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When receiving a Computer (LRU) that has newly arrived from the manufacturer it should be checked to ensure that it has the?', '[{"id": "a", "text": "Right serial number only", "correct": false}, {"id": "b", "text": "Correct part number, dash number and serial number", "correct": true}, {"id": "c", "text": "Back connector pin orientation", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The trunnion nut on an aircraft landing gear requires a torque of 320 inch-pounds. To reach the nut, a 2-inch straight adapter must be used on an 18-inch torque wrench. How many foot-pounds will be indicated on the torque wrench when the required torque of the nut is reached?', '[{"id": "a", "text": "22 foot-pounds", "correct": false}, {"id": "b", "text": "24 foot-pounds", "correct": true}, {"id": "c", "text": "16 foot-pounds", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the correct procedure for tightening a flareless tube end fitting?', '[{"id": "a", "text": "Hand tight and then 1/6 turn using a spanner", "correct": true}, {"id": "b", "text": "Hand tight and then 2 flats using a spanner", "correct": false}, {"id": "c", "text": "Hand tight and then one complete turn using spanner", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When installing a hydraulic line the tube flare should meet the fitting squarely and fully before starting the nut. The flare should never be drawn to the fitting with the nut because this may:', '[{"id": "a", "text": "Deform the line", "correct": false}, {"id": "b", "text": "Deform the flare", "correct": true}, {"id": "c", "text": "Strip the threads on the fitting", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Control cables swaged with NICO press sleeves must be checked with:', '[{"id": "a", "text": "Protractor for angles between 25° to 27°", "correct": false}, {"id": "b", "text": "Go-no-go gauge provided by the manufacturers", "correct": true}, {"id": "c", "text": "Rules graduated in thousandths of an inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When removing a component from an airframe:', '[{"id": "a", "text": "Both of the other statements are correct", "correct": true}, {"id": "b", "text": "The area that is uncovered when the components is removed should be inspected", "correct": false}, {"id": "c", "text": "The component should be inspected for damage", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During installation of a coaxial cable in an aircraft:', '[{"id": "a", "text": "No particular precautions are required because the signal line is shielded", "correct": false}, {"id": "b", "text": "The cable must be on the outside of a wire bundle", "correct": true}, {"id": "c", "text": "The cable should be included in a wire bundle with low voltage wires", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'For the same thickness material, the aluminium designation which can be bent to the tightest radius is:', '[{"id": "a", "text": "H2", "correct": true}, {"id": "b", "text": "T6", "correct": false}, {"id": "c", "text": "T3", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Equipment used for aircraft tie downs can be:', '[{"id": "a", "text": "Chains or rods", "correct": false}, {"id": "b", "text": "Ropes or cables", "correct": true}, {"id": "c", "text": "Cables or rods", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How can the applicability of a service bulletin to a specific aircraft be confirmed?', '[{"id": "a", "text": "The aircraft operators applicability statement in the tech log should be checked", "correct": false}, {"id": "b", "text": "The aircraft type and serial number will be listed in the service bulletins “Applicability", "correct": true}, {"id": "c", "text": "Service bulletins are always applicable of the specified type", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During severe wind conditions an aircraft should be parked:', '[{"id": "a", "text": "Nose into wind", "correct": true}, {"id": "b", "text": "On concrete", "correct": false}, {"id": "c", "text": "Tail into wind", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should you check a crimping tool prior to any crimping operation?', '[{"id": "a", "text": "Check by a GO/NO GO gauge", "correct": false}, {"id": "b", "text": "Check the calibration label to be within date", "correct": false}, {"id": "c", "text": "Check the full cycle ratchet mechanism for normal operation", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What has to be done every time you finish working with a toggle-type torque wrench?', '[{"id": "a", "text": "It must be calibrated", "correct": false}, {"id": "b", "text": "It must be released", "correct": true}, {"id": "c", "text": "It must be set to 100 inch-pounds", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To check the value of resistors with precision you must use a:', '[{"id": "a", "text": "Wheatstone bridge", "correct": true}, {"id": "b", "text": "Ohmmeter", "correct": false}, {"id": "c", "text": "Megohmeter", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When levelling an aeroplane prior to weight & balance calculation it is important to ensure that the aeroplane is:', '[{"id": "a", "text": "Laterally and longitudinally levelled", "correct": true}, {"id": "b", "text": "Emptied from drainable fuel and oil", "correct": false}, {"id": "c", "text": "Laterally levelled and the fuel tanks are emptied", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When mixing acid with water to form electrolyte for a lead acid battery:', '[{"id": "a", "text": "First put water in the container then add acid to the water", "correct": true}, {"id": "b", "text": "Pour the water and acid simultaneously into the container", "correct": false}, {"id": "c", "text": "First put acid in the container then add water to the acid", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What method is employed to ensure that small cover/blanks are easily seen?', '[{"id": "a", "text": "Their location is written into the technical log", "correct": false}, {"id": "b", "text": "They are painted yellow", "correct": false}, {"id": "c", "text": "A pennant is attached to the cover/blank", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the main precaution when handling oxygen?', '[{"id": "a", "text": "Ensure the area is well ventilated", "correct": false}, {"id": "b", "text": "Keep oil and grease away from any threads and pipelines", "correct": true}, {"id": "c", "text": "Wear eye protection goggles", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When forming a piece of aluminium into a complex shape, what type of material should be used?', '[{"id": "a", "text": "2024-T3", "correct": false}, {"id": "b", "text": "2024-O", "correct": true}, {"id": "c", "text": "2024-T4", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In an aircraft weight and balance, a negative weight and a negative arm will produce:', '[{"id": "a", "text": "A positive moment", "correct": true}, {"id": "b", "text": "A negative moment", "correct": false}, {"id": "c", "text": "A maximum lift", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To apply a tension to a mechanical control cable it is necessary to know:', '[{"id": "a", "text": "The ambient temperature and the diameter", "correct": true}, {"id": "b", "text": "It’s structure (for instance 7x7 or 7x19)", "correct": false}, {"id": "c", "text": "The air load supported by the control surface it actuates", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The minimum edge distance for rivets is:', '[{"id": "a", "text": "Two and a half times the diameter of the rivet shank", "correct": false}, {"id": "b", "text": "Three times the diameter of the rivet shank", "correct": false}, {"id": "c", "text": "Two times the diameter of the rivet shank", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the maximum number of views that can be used in orthographic projection?', '[{"id": "a", "text": "4 views", "correct": false}, {"id": "b", "text": "2 views", "correct": false}, {"id": "c", "text": "6 views", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A bonding connection is considered satisfactory when its resistance is less than:', '[{"id": "a", "text": "5 ohms", "correct": false}, {"id": "b", "text": "0.5 ohms", "correct": false}, {"id": "c", "text": "0.05 ohms", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The dimensions shown on an aircraft drawing are 2.175" +.005" / -.003". Which of the following is correct?', '[{"id": "a", "text": "The allowance is .008\"", "correct": false}, {"id": "b", "text": "The tolerance is .008\"", "correct": true}, {"id": "c", "text": "The maximum permissible size is 2.483\"", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When parking an aircraft on completion of a turn, the aircraft should be towed a few feet in a straight line to:', '[{"id": "a", "text": "Reduce side loads on the main undercarriage", "correct": true}, {"id": "b", "text": "Facilitate better holding powers of the chocks", "correct": false}, {"id": "c", "text": "Offload excessive pressures in the steering jack", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Holes drilled at the intersection of two bends to prevent the metal from cracking are referred to as:', '[{"id": "a", "text": "Relief holes", "correct": true}, {"id": "b", "text": "Pilot holes", "correct": false}, {"id": "c", "text": "Lightening holes", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which tool should be used to sketch/mark aluminium alloy sheets?', '[{"id": "a", "text": "Any marker is allowed", "correct": false}, {"id": "b", "text": "Graphite pencil", "correct": true}, {"id": "c", "text": "Brass drawing pin", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The area in which it is most likely that damage is found to a control cable is where it:', '[{"id": "a", "text": "Is attached to an end fitting", "correct": false}, {"id": "b", "text": "Has a long straight run", "correct": false}, {"id": "c", "text": "Passes around pulleys", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Information about the compatibility of fire resistant hydraulic fluid with aircraft materials can be found in:', '[{"id": "a", "text": "Manufacturer’s technical bulletins", "correct": false}, {"id": "b", "text": "AC 43.13-1A", "correct": false}, {"id": "c", "text": "Aircraft manufacturer’s specifications", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Who designates the location of the reference for levelling aircraft on the ground for weighing purposes?', '[{"id": "a", "text": "Aircraft manufacturer", "correct": true}, {"id": "b", "text": "FAA administration", "correct": false}, {"id": "c", "text": "Certified repair station", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following different kinds of fuel is considered to be part of the empty weight of an aircraft?', '[{"id": "a", "text": "Unusable fuel", "correct": true}, {"id": "b", "text": "Taxiing fuel", "correct": false}, {"id": "c", "text": "Trip fuel", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rivet pitch is the distance between the:', '[{"id": "a", "text": "Centres of adjacent rivets in the same row", "correct": true}, {"id": "b", "text": "Heads of rivets in the same row", "correct": false}, {"id": "c", "text": "Centres of rivets in adjacent rows", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Prolonged forming operation may cause:', '[{"id": "a", "text": "Corrosion", "correct": false}, {"id": "b", "text": "Work hardening", "correct": true}, {"id": "c", "text": "Softening of the metal", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An item is to be tightened with a torque wrench and the recommended torque is 21 Nm. The scale of the wrench is in IN LBS. How do you convert from Nm to IN LBS, and what other things do you have to observe?', '[{"id": "a", "text": "You use a conversion table. If none is at hand, you use the equation Nm × 8.851 = IN LBS.", "correct": true}, {"id": "b", "text": "You use a conversion table. If none is at hand, you use the equation Nm × 8.851 = IN LBS. The torque", "correct": false}, {"id": "c", "text": "You try to find another torque wrench, maybe in another dock, or you use the equation Nm × 8.851 = IN", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How is the presence of a part not visible to the viewer represented on a drawing?', '[{"id": "a", "text": "A series of short dashed lines", "correct": true}, {"id": "b", "text": "A series of one long and one short dashed line", "correct": false}, {"id": "c", "text": "A series of two short and one long dashed line", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is used in a gear train to allow for lubrication and heat expansion?', '[{"id": "a", "text": "Pitch error", "correct": false}, {"id": "b", "text": "Backlash", "correct": true}, {"id": "c", "text": "Run-out", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Inspection of propeller blades by dye-penetrant inspection is accomplished to detect:', '[{"id": "a", "text": "Torsional stress", "correct": false}, {"id": "b", "text": "Corrosion", "correct": false}, {"id": "c", "text": "Cracks", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What two types of indicating mediums are available for magnetic particle inspection?', '[{"id": "a", "text": "Iron and ferric oxides", "correct": true}, {"id": "b", "text": "Wet and dry process materials", "correct": false}, {"id": "c", "text": "Penetrate and fluorescent material", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following tools should be used to check that a hole is within tolerance?', '[{"id": "a", "text": "An internal caliper", "correct": false}, {"id": "b", "text": "A go/no-go plug gauge", "correct": true}, {"id": "c", "text": "A dial test indicator", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aircraft bolts with a cross or asterisk marked on the bolt head are:', '[{"id": "a", "text": "Standard steel bolts", "correct": true}, {"id": "b", "text": "Made of aluminium alloy", "correct": false}, {"id": "c", "text": "Close tolerance bolts", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The following fastener symbol code is found on a blueprint. The rivet code is in a box. This indicates (refer to figure):', '[{"id": "a", "text": "A fluid tight fastener", "correct": false}, {"id": "b", "text": "That the removed fastener is used", "correct": false}, {"id": "c", "text": "A reference fastener", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A dry powder extinguisher is coloured', '[{"id": "a", "text": "green.", "correct": false}, {"id": "b", "text": "red.", "correct": false}, {"id": "c", "text": "blue.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Acetylene gas forms an explosive compound with', '[{"id": "a", "text": "tin and silver.", "correct": false}, {"id": "b", "text": "tin and copper.", "correct": false}, {"id": "c", "text": "copper and silver.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When mixing acid and water', '[{"id": "a", "text": "the acid should always be added to the water.", "correct": true}, {"id": "b", "text": "it does not matter which way the two are mixed.", "correct": false}, {"id": "c", "text": "the water should always be added to the acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'You are involved with a fire caused by titanium swarf. What type of extinguishant should you use to deal with the fire?', '[{"id": "a", "text": "Dry asbestos wool and chalk powder.", "correct": true}, {"id": "b", "text": "CO2", "correct": false}, {"id": "c", "text": "Chemical foam.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft should not be refueled when', '[{"id": "a", "text": "the APU is running.", "correct": false}, {"id": "b", "text": "navigation and landing light in operation.", "correct": false}, {"id": "c", "text": "within 10 metres (30 feet) of radar operating.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A CO2 extinguisher is used on', '[{"id": "a", "text": "solid, liquid, hot metal and electrical fires.", "correct": false}, {"id": "b", "text": "solid, liquid and electrical fires.", "correct": true}, {"id": "c", "text": "solid and liquid fires.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In an oxygen system, if the pressure drops to 500 PSI, it', '[{"id": "a", "text": "causes anoxia.", "correct": false}, {"id": "b", "text": "begins to overheat.", "correct": false}, {"id": "c", "text": "blocks the oxygen system regulator.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After working with epoxy resins, how is natural oil returned to the skin?', '[{"id": "a", "text": "Epoxy removing cream.", "correct": false}, {"id": "b", "text": "Refatting cream.", "correct": true}, {"id": "c", "text": "Acetone/lanolin mixture.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Neither oil nor grease should be used as a lubricant on couplings or pipelines carrying', '[{"id": "a", "text": "Oxygen.", "correct": true}, {"id": "b", "text": "Kerosene.", "correct": false}, {"id": "c", "text": "Nitrogen.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of extinguisher can be used for an electric fire?', '[{"id": "a", "text": "Foam", "correct": false}, {"id": "b", "text": "Water", "correct": false}, {"id": "c", "text": "CO2", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The colour of CO2 type fire extinguisher is', '[{"id": "a", "text": "red.", "correct": false}, {"id": "b", "text": "black.", "correct": true}, {"id": "c", "text": "green.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of extinguisher can be used for engine fire?', '[{"id": "a", "text": "CO2", "correct": false}, {"id": "b", "text": "BCF", "correct": true}, {"id": "c", "text": "Water", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Fire on landing gear brake should be extinguished with', '[{"id": "a", "text": "dry powder extinguisher.", "correct": true}, {"id": "b", "text": "carbon dioxide extinguisher.", "correct": false}, {"id": "c", "text": "water extinguisher.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of fire extinguishers can be used in the cabin?', '[{"id": "a", "text": "C.T.C.", "correct": false}, {"id": "b", "text": "water or B.C.F.", "correct": true}, {"id": "c", "text": "M.B.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Risk assessments should only be carried out on', '[{"id": "a", "text": "all tasks and processes that are performed.", "correct": true}, {"id": "b", "text": "tasks using hazardous chemicals.", "correct": false}, {"id": "c", "text": "tasks carried out above the height of 6 foot.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The most appropriate fire extinguisher for an aircraft wheel and brake fire would be', '[{"id": "a", "text": "carbon dioxide.", "correct": false}, {"id": "b", "text": "dry powder.", "correct": true}, {"id": "c", "text": "water.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Once a person has been disconnected from the source of an electrical shock the next step should be', '[{"id": "a", "text": "seek assistance immediately.", "correct": false}, {"id": "b", "text": "check for breathing start AR if necessary.", "correct": true}, {"id": "c", "text": "check for pulse start cardiac massage if necessary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What can cause dermatitis?', '[{"id": "a", "text": "Washing hands in solvents.", "correct": true}, {"id": "b", "text": "Not wearing eye protection when using solvents.", "correct": false}, {"id": "c", "text": "Inhalation of paint fumes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an oxygen cylinder pressure falls below 500 PSI', '[{"id": "a", "text": "the diluter stick will stick.", "correct": false}, {"id": "b", "text": "the oxygen will degrade and cause anoxia.", "correct": false}, {"id": "c", "text": "condensation will cause corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a hollow tube where would a small indentation normally be unacceptable?', '[{"id": "a", "text": "Nowhere on the tube is an indentation acceptable.", "correct": false}, {"id": "b", "text": "In the mid 1/3 section.", "correct": true}, {"id": "c", "text": "In either of the outer 1/3 portion of the tube.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of grinding wheel would you sharpen an HSS drill bit on?', '[{"id": "a", "text": "A green wheel.", "correct": false}, {"id": "b", "text": "A course wheel.", "correct": false}, {"id": "c", "text": "A fine wheel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a reamer -', '[{"id": "a", "text": "use no lubricant.", "correct": false}, {"id": "b", "text": "use the same lubricant as was used on the drill bit.", "correct": true}, {"id": "c", "text": "use lard oil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many teeth per inch are used on a hacksaw blade for cutting hard metal?', '[{"id": "a", "text": "26", "correct": false}, {"id": "b", "text": "36", "correct": true}, {"id": "c", "text": "54", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many strokes per minute are used on a hacksaw when cutting thick metal?', '[{"id": "a", "text": "30", "correct": true}, {"id": "b", "text": "55", "correct": false}, {"id": "c", "text": "65", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When lifting a bulky component with a wire rope sling, the component can be protected from damage by the sling by', '[{"id": "a", "text": "fabricating alternative lifting points.", "correct": false}, {"id": "b", "text": "using a suitably shaped sling.", "correct": false}, {"id": "c", "text": "using spreader bars and packing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Gas bottles for CO2 air and acetylene are coloured', '[{"id": "a", "text": "grey, maroon, green.", "correct": false}, {"id": "b", "text": "black, grey, maroon.", "correct": true}, {"id": "c", "text": "green, grey, maroon.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To drill a 1/4 inch hole in titanium, the correct starting procedure would be', '[{"id": "a", "text": "to centre drill.", "correct": true}, {"id": "b", "text": "to centre punch.", "correct": false}, {"id": "c", "text": "to drill 1/4 inch hole direct.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a torque wrench of handle length, L = 12 in. and an extension E = 3 in, the desired torque value is 300 lbs.in. the dial should read', '[{"id": "a", "text": "240 lb.ins.", "correct": true}, {"id": "b", "text": "280 lb.ins.", "correct": false}, {"id": "c", "text": "375 lb.ins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a torque loading is specified for a castellated or slotted nut on an undrilled new bolt -', '[{"id": "a", "text": "the bolt should be pre-drilled, the torque applied and the nut eased back, if necessary, to allow the split pin to", "correct": true}, {"id": "b", "text": "the bolt should be pre-drilled and the torque increased if necessary to allow the split pin to be fitted.", "correct": false}, {"id": "c", "text": "the torque should be applied and the bolt suitably drilled for the split pin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A reamer with spiral flutes is removed', '[{"id": "a", "text": "clockwise.", "correct": true}, {"id": "b", "text": "anticlockwise.", "correct": false}, {"id": "c", "text": "straight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The difference between high and low limits of a size for a dimension is known as the', '[{"id": "a", "text": "deviation.", "correct": false}, {"id": "b", "text": "tolerance.", "correct": true}, {"id": "c", "text": "fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rubber components should be stored', '[{"id": "a", "text": "in warm and humid conditions.", "correct": false}, {"id": "b", "text": "in a well lit room.", "correct": false}, {"id": "c", "text": "in a cool dark area.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When comparing the machining techniques for stainless steel sheet material to those for aluminium alloy sheet, it is normally considered good practice to drill the stainless steel at a', '[{"id": "a", "text": "higher speed with less pressure applied to the drill.", "correct": false}, {"id": "b", "text": "lower speed with more pressure applied to the drill.", "correct": true}, {"id": "c", "text": "lower speed with less pressure applied to the drill.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When drilling stainless steel, the drill used should have an included angle of', '[{"id": "a", "text": "90° and turn at a low speed.", "correct": false}, {"id": "b", "text": "140° and turn at a low speed.", "correct": true}, {"id": "c", "text": "118° and turn at a high speed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When stop drilling a crack, what is the typical drill size used?', '[{"id": "a", "text": "0.025 inch", "correct": false}, {"id": "b", "text": "0.125 inch", "correct": true}, {"id": "c", "text": "0.250 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When degreasing aluminium alloys, and no trichloroethylene is available, a suitable alternative is', '[{"id": "a", "text": "dilute sulphuric acid.", "correct": false}, {"id": "b", "text": "M.E.K.", "correct": false}, {"id": "c", "text": "white spirit and naphtha.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A grinding wheel is normally refaced by', '[{"id": "a", "text": "dressing with a special tool.", "correct": true}, {"id": "b", "text": "grinding through using another grinding wheel.", "correct": false}, {"id": "c", "text": "holding a hard wood scraper against the rotating wheel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking a torque wrench 15 inches long, the load required to give torque of 120 lbs.in. is', '[{"id": "a", "text": "6 lbs.", "correct": false}, {"id": "b", "text": "8 lbs.", "correct": true}, {"id": "c", "text": "10 lbs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the specified lubricant for drilling brass?', '[{"id": "a", "text": "None", "correct": true}, {"id": "b", "text": "Paraffin", "correct": false}, {"id": "c", "text": "Lard oil", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which procedure is correct when using a reamer to finish a drilled hole to the correct size?', '[{"id": "a", "text": "Turn the reamer only in the cutting direction.", "correct": true}, {"id": "b", "text": "Turn the reamer in the cutting direction when enlarging the hole and in the opposite direction to remove from the hole.", "correct": false}, {"id": "c", "text": "Apply considerable pressure on the reamer when starting the cut and reduce the pressure when finishing the cut.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Of what tolerance is the following an example? 1 in. + 0.002-0.001.', '[{"id": "a", "text": "Bilateral", "correct": true}, {"id": "b", "text": "Multilateral", "correct": false}, {"id": "c", "text": "Unilateral", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should a scraper be finally sharpened?', '[{"id": "a", "text": "By draw filing.", "correct": false}, {"id": "b", "text": "On a grindstone.", "correct": false}, {"id": "c", "text": "On an oil-stone.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How is a D.T.I. initially set up?', '[{"id": "a", "text": "The gauge plunger should be fully extended and the needle zeroed.", "correct": false}, {"id": "b", "text": "The gauge plunger should be partly depressed and the needle zeroed.", "correct": true}, {"id": "c", "text": "The needle zeroed, then the plunger fully extended.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Nickel alloy chisels should be sharpened', '[{"id": "a", "text": "by filing.", "correct": false}, {"id": "b", "text": "on a grindstone.", "correct": true}, {"id": "c", "text": "on an oilstone.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of lubricant should be used when drilling aluminium?', '[{"id": "a", "text": "Vegetable oil", "correct": false}, {"id": "b", "text": "Paraffin", "correct": true}, {"id": "c", "text": "None", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How are spring dividers sharpened?', '[{"id": "a", "text": "By filing the outside of the points.", "correct": false}, {"id": "b", "text": "By stoning the outside of the points.", "correct": true}, {"id": "c", "text": "By grinding the inside of the points.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What would be the result of an insufficient clearance angle on a twist drill?', '[{"id": "a", "text": "It would cut slowly, if at all.", "correct": true}, {"id": "b", "text": "It would produce an oversize hole.", "correct": false}, {"id": "c", "text": "It would tend to pull through the hole.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A tolerance given on a dimension is indicated', '[{"id": "a", "text": "by a plus and minus sign preceding the permitted tolerance.", "correct": true}, {"id": "b", "text": "by the prefix TOL with the permitted tolerance.", "correct": false}, {"id": "c", "text": "by enclosing the permitted tolerance within a triangle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How much material should be allowed for reaming?', '[{"id": "a", "text": "0.001 in", "correct": false}, {"id": "b", "text": "0.003 in", "correct": true}, {"id": "c", "text": "0.010 in", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After cutting a 3/8 inch BSF internal thread and stud, it is found that the stud is too large. How is a fit achieved?', '[{"id": "a", "text": "Remove the male thread crests with a fine emery cloth.", "correct": false}, {"id": "b", "text": "Grind a taper on the end of the bolt.", "correct": false}, {"id": "c", "text": "Re-adjust the die and re-cut the male thread.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'You have reamed out a hole in a piece of titanium. How should you remove the reamer safely to prevent unnecessary damage?', '[{"id": "a", "text": "Allow the reamer to pass right through the hole.", "correct": false}, {"id": "b", "text": "Remove it, but in the same rotation as if cutting.", "correct": true}, {"id": "c", "text": "Anti-clockwise.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why are some components torque loaded?', '[{"id": "a", "text": "To ensure that their elastic limit is not exceeded.", "correct": true}, {"id": "b", "text": "To ensure they do not vibrate loose.", "correct": false}, {"id": "c", "text": "To ensure that they are tightened to their yield point.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a reamer, in which direction should it be turned?', '[{"id": "a", "text": "Clockwise when cutting and anti-clockwise when removing.", "correct": false}, {"id": "b", "text": "Anti-clockwise when cutting and removing.", "correct": false}, {"id": "c", "text": "Clockwise when cutting and removing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Draw filing produces', '[{"id": "a", "text": "a course finish.", "correct": false}, {"id": "b", "text": "a fine finish.", "correct": true}, {"id": "c", "text": "a mottled finish.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A safe edge of a file is used', '[{"id": "a", "text": "against a finished surface.", "correct": true}, {"id": "b", "text": "to give a fine polished finish to a smooth surface.", "correct": false}, {"id": "c", "text": "against a rough unfinished surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the minimum number of hacksaw blade teeth that should be in contact with the material being cut?', '[{"id": "a", "text": "2", "correct": false}, {"id": "b", "text": "3", "correct": true}, {"id": "c", "text": "4", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When reading a blueprint, a dimension is given as 4.387 inches + 0.005-0.002. Which statement is true?', '[{"id": "a", "text": "The maximum acceptable size is 4.385 inches.", "correct": false}, {"id": "b", "text": "The minimum acceptable size is 4.385 inches.", "correct": true}, {"id": "c", "text": "The maximum acceptable size is 4.389 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Chalk when used with a fine file produces', '[{"id": "a", "text": "a finer finish.", "correct": true}, {"id": "b", "text": "a milled type surface.", "correct": false}, {"id": "c", "text": "a ground type surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a hand file correctly, the downward pressure should be used only', '[{"id": "a", "text": "on a return stroke.", "correct": false}, {"id": "b", "text": "on the forward stroke.", "correct": true}, {"id": "c", "text": "on the forward and return stroke.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The size of the nibs of vernier calipers can be ascertained by', '[{"id": "a", "text": "using the standard of 0.693 inches.", "correct": false}, {"id": "b", "text": "measuring the steel rule.", "correct": false}, {"id": "c", "text": "noting the dimension engraved on the instrument.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), '2 microns is', '[{"id": "a", "text": "0.002 mm.", "correct": true}, {"id": "b", "text": "0.002 inch.", "correct": false}, {"id": "c", "text": "0.000 002 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The edge or surface of a part from which dimensions are measured from is called the', '[{"id": "a", "text": "water line.", "correct": false}, {"id": "b", "text": "reference plane.", "correct": false}, {"id": "c", "text": "datum.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Water Lines are', '[{"id": "a", "text": "front to rear measurements on the fuselage.", "correct": false}, {"id": "b", "text": "vertical measurements on the fuselage.", "correct": true}, {"id": "c", "text": "left and right measurements on the fuselage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When clamping cable looms containing co-axial cables', '[{"id": "a", "text": "distortion of the outer sheath is allowed providing the inner cable is not affected.", "correct": false}, {"id": "b", "text": "the clamps must be no more than 1 metre apart.", "correct": false}, {"id": "c", "text": "avoid distortion to the co-axial cable to maintain the dielectric constant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a test or inspection instrument has no calibration data supplied by the manufacturer, you would use the calibration data provided by', '[{"id": "a", "text": "the British Standards Quality Assurance documentation referring to calibration of instrumentation and test equipment.", "correct": false}, {"id": "b", "text": "CAAIP S.", "correct": true}, {"id": "c", "text": "the Maintenance Manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why are test or inspection instruments regularly calibrated and certified?', '[{"id": "a", "text": "To ensure they will perform within the required limits of operation.", "correct": true}, {"id": "b", "text": "To ensure they can handle the range of measurements required of them.", "correct": false}, {"id": "c", "text": "To ensure they are being used regularly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Who is responsible for ensuring that weight and balance instrumentation is serviceable before use?', '[{"id": "a", "text": "An engineer holding a license in the instrument category.", "correct": false}, {"id": "b", "text": "The manufacturer of the equipment.", "correct": false}, {"id": "c", "text": "The person responsible for carrying out the weight and balance procedure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'At which frequency is the calibration of frequently used crimping tools carried out?', '[{"id": "a", "text": "Bi-annually", "correct": false}, {"id": "b", "text": "Annually", "correct": true}, {"id": "c", "text": "Every 1000 crimps", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the trepanning tool, the hole to be drilled should be', '[{"id": "a", "text": "1/32 inch larger than the guide pin.", "correct": false}, {"id": "b", "text": "same diameter as the guide pin.", "correct": true}, {"id": "c", "text": "1/32 inch smaller than the guide pin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a strip-board, the tracks on a PCB are etched', '[{"id": "a", "text": "before component fitment.", "correct": true}, {"id": "b", "text": "after fitment but before soldering the components.", "correct": false}, {"id": "c", "text": "after fitment and soldering of components.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The intervals for calibration of test equipment', '[{"id": "a", "text": "are every year.", "correct": false}, {"id": "b", "text": "are different from one appliance to another.", "correct": true}, {"id": "c", "text": "are as specified in EASA Part-145.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What drill angle is used to drill titanium?', '[{"id": "a", "text": "90-100 degrees", "correct": false}, {"id": "b", "text": "105-120 degrees", "correct": false}, {"id": "c", "text": "130-140 degrees", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When tightening a nut on a bolt the torque loading applied is', '[{"id": "a", "text": "inversely proportional to the force applied to the spanner.", "correct": false}, {"id": "b", "text": "the tangential application of the force times the perpendicular distance from the point of application to the", "correct": true}, {"id": "c", "text": "independent of whether the threads are wet or dry.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The UK standard of limits and fits is', '[{"id": "a", "text": "BS4500.", "correct": true}, {"id": "b", "text": "BS8888.", "correct": false}, {"id": "c", "text": "BS308.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a Pacific tensiometer the correct tension is found by', '[{"id": "a", "text": "reading dial, provided the correct riser is used for the cable diameter.", "correct": true}, {"id": "b", "text": "comparing reading to chart provided.", "correct": false}, {"id": "c", "text": "adding reading to riser number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What temperature should the heat gun be set for shrinking heat shrink sleeve?', '[{"id": "a", "text": "At the rated temperature.", "correct": true}, {"id": "b", "text": "100°C below rated temperature.", "correct": false}, {"id": "c", "text": "100°C above rated temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Calibration of aircraft hydrostatic weighing equipment is', '[{"id": "a", "text": "done once a year.", "correct": true}, {"id": "b", "text": "carried out every time before an aircraft is weighed and adjusted by operator.", "correct": false}, {"id": "c", "text": "not required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When drilling light alloy', '[{"id": "a", "text": "lard oil should be used.", "correct": false}, {"id": "b", "text": "use the specified lubricant.", "correct": true}, {"id": "c", "text": "no lubricant is required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The picture shows a torque wrench with an extension. To apply a torque of 350 lb.in. the reading on the dial should be', '[{"id": "a", "text": "245 lb.in.", "correct": false}, {"id": "b", "text": "280 lb.in.", "correct": true}, {"id": "c", "text": "350 lb.in.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Reaming light alloy tube is done with', '[{"id": "a", "text": "no lubricant.", "correct": false}, {"id": "b", "text": "the same oil and lubrication as used for cutting.", "correct": true}, {"id": "c", "text": "hard base lubricant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Tolerance is the', '[{"id": "a", "text": "the difference between a hole and shaft size.", "correct": false}, {"id": "b", "text": "allowable error due to faulty workmanship and tools.", "correct": true}, {"id": "c", "text": "difference between worn and new tools.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What should be done if a tool is found not to be working to its calibrated requirements?', '[{"id": "a", "text": "It should be removed from service, marked as unserviceable and sent away for overhaul.", "correct": true}, {"id": "b", "text": "It should be placed back into stores and kept in service until the next calibration is due.", "correct": false}, {"id": "c", "text": "A mechanic should adjust it to restore it to the correct operation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out soldering to an end termination and a wire, you should tin', '[{"id": "a", "text": "only the end of the wire.", "correct": false}, {"id": "b", "text": "neither the wire or the termination as tinning is not required.", "correct": false}, {"id": "c", "text": "both the end of the wire and the termination.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Run-out of a rod is measured using', '[{"id": "a", "text": "DTI, surface plate and V-blocks.", "correct": true}, {"id": "b", "text": "micrometer and V-blocks.", "correct": false}, {"id": "c", "text": "vernier and V-blocks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How would you mark a defect on an exhaust system?', '[{"id": "a", "text": "Pencil", "correct": false}, {"id": "b", "text": "Chalk", "correct": true}, {"id": "c", "text": "Special zinc/copper tipped marking tool.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following is the most appropriate filing technique?', '[{"id": "a", "text": "Pressure backwards, relieve pressure forwards.", "correct": false}, {"id": "b", "text": "Even pressure forward and backwards.", "correct": false}, {"id": "c", "text": "Pressure forwards, relieve pressure backwards.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Stubborn pins in file teeth should be removed by', '[{"id": "a", "text": "tapping file gently on workbench.", "correct": false}, {"id": "b", "text": "using file card.", "correct": false}, {"id": "c", "text": "pricking out with sharp point.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using low tungsten hacksaw blades it is recommended to use', '[{"id": "a", "text": "40 strokes per minute.", "correct": false}, {"id": "b", "text": "50 strokes per minute.", "correct": true}, {"id": "c", "text": "60 strokes per minute.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Units of torque are', '[{"id": "a", "text": "lbs/ft^2 and lbs/in^2.", "correct": false}, {"id": "b", "text": "lbs and kg.", "correct": false}, {"id": "c", "text": "lbs.ft and lbs.in.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The calibration of a piece of test equipment is suspect. Your actions would be', '[{"id": "a", "text": "calibrate/rectify immediately.", "correct": false}, {"id": "b", "text": "note and rectify later.", "correct": false}, {"id": "c", "text": "remove from service and annotate accordingly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When turning the handle on a megger with the probes kept apart', '[{"id": "a", "text": "the needle stays at infinity.", "correct": true}, {"id": "b", "text": "the needle deflects to infinity.", "correct": false}, {"id": "c", "text": "the needle moves to zero.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many strokes per minute should generally be used with a hacksaw?', '[{"id": "a", "text": "30", "correct": false}, {"id": "b", "text": "55", "correct": true}, {"id": "c", "text": "60", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of drill would you use on carbon fibre?', '[{"id": "a", "text": "Diamond tipped", "correct": true}, {"id": "b", "text": "Carborundum", "correct": false}, {"id": "c", "text": "Tungsten carbide", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A micro-shaver is used to', '[{"id": "a", "text": "cut rivets to length prior to forming.", "correct": false}, {"id": "b", "text": "mill the rivet head after forming.", "correct": true}, {"id": "c", "text": "trim the shank diameter prior to forming.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many teeth per inch are there on a fine hacksaw blade?', '[{"id": "a", "text": "16", "correct": false}, {"id": "b", "text": "32", "correct": true}, {"id": "c", "text": "64", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the normal cutting angle of a drill?', '[{"id": "a", "text": "12°", "correct": false}, {"id": "b", "text": "59°", "correct": true}, {"id": "c", "text": "130°", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a moving coil as an ammeter the greatest amount of current flows through the', '[{"id": "a", "text": "bushes.", "correct": false}, {"id": "b", "text": "coil.", "correct": false}, {"id": "c", "text": "shunt.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the old style vernier caliper for taking internal measurements', '[{"id": "a", "text": "add the nib measurements.", "correct": true}, {"id": "b", "text": "subtract the nib measurements.", "correct": false}, {"id": "c", "text": "the nib size has no relevance and can be ignored.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To carry out an insulation test on a wire rated at 115 volts you would use', '[{"id": "a", "text": "a 250 volt megger.", "correct": false}, {"id": "b", "text": "a 115 volt megger.", "correct": false}, {"id": "c", "text": "a 500 volt megger.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The normal drill angles are', '[{"id": "a", "text": "cutting angle 59°, web angle 130° and clearance angle 12°.", "correct": true}, {"id": "b", "text": "cutting angle 130°, web angle 59° and clearance angle 12°.", "correct": false}, {"id": "c", "text": "cutting angle 12°, web angle 130° and clearance angle 130°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A rivet shaver is used to', '[{"id": "a", "text": "mill the head flush.", "correct": true}, {"id": "b", "text": "mill the tail after cutting.", "correct": false}, {"id": "c", "text": "mill the tail after setting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A drill and wire gauge has holes numbered', '[{"id": "a", "text": "10 to 60.", "correct": false}, {"id": "b", "text": "1 to 80.", "correct": true}, {"id": "c", "text": "1 to 50.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A 250 volt megger should not be used', '[{"id": "a", "text": "on electronic equipment.", "correct": true}, {"id": "b", "text": "in fuel tanks.", "correct": false}, {"id": "c", "text": "on radio aerials.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the leads of a megger are held apart', '[{"id": "a", "text": "the spring will return the needle to infinity.", "correct": false}, {"id": "b", "text": "the spring will return the needle to the zero stop.", "correct": false}, {"id": "c", "text": "if the handle was turned the meter would read infinity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'One megohm is equal to', '[{"id": "a", "text": "1,000 ohms.", "correct": false}, {"id": "b", "text": "100,000 ohms.", "correct": false}, {"id": "c", "text": "1,000,000 ohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Reamers are used to', '[{"id": "a", "text": "drill accurate holes.", "correct": false}, {"id": "b", "text": "to make holes oversize.", "correct": false}, {"id": "c", "text": "enlarge holes to accurate dimensions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pitch of a hacksaw blade is', '[{"id": "a", "text": "its length.", "correct": false}, {"id": "b", "text": "the number of teeth on the blade.", "correct": false}, {"id": "c", "text": "the number of teeth per inch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The web angle of a normal twist drill is', '[{"id": "a", "text": "12°.", "correct": false}, {"id": "b", "text": "59°.", "correct": false}, {"id": "c", "text": "130°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The leads of a bonding tester', '[{"id": "a", "text": "are interchangeable, one 60 foot long having two prongs and a 6 foot one with a single prong.", "correct": false}, {"id": "b", "text": "have critical lengths and the resistance of the leads is accounted for.", "correct": true}, {"id": "c", "text": "are supplied in 60 foot and 6 foot lengths but can be varied due to wear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Expanding reamers are used to', '[{"id": "a", "text": "ream holes of different diameters by adjusting the position of the blades.", "correct": true}, {"id": "b", "text": "ream tapered holes.", "correct": false}, {"id": "c", "text": "ream holes in metal that has been heated.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The main scale on a 24/25 vernier caliper is divided into', '[{"id": "a", "text": "inches, tenths and twentieths.", "correct": false}, {"id": "b", "text": "inches, tenths and fortieths.", "correct": true}, {"id": "c", "text": "inches, tenths and thousandths.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The vernier height gauge uses the same principle as the', '[{"id": "a", "text": "vernier caliper.", "correct": true}, {"id": "b", "text": "bevel protractor.", "correct": false}, {"id": "c", "text": "micrometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'One revolution of the thimble of the English micrometer produces a linear movement of the spindle of', '[{"id": "a", "text": "0.001 inch.", "correct": false}, {"id": "b", "text": "0.025 inch.", "correct": true}, {"id": "c", "text": "0.040 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pitch of a metric micrometer screw thread is', '[{"id": "a", "text": "0.02 mm.", "correct": false}, {"id": "b", "text": "0.5 mm.", "correct": true}, {"id": "c", "text": "1.0 mm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When torque loading, a wrench should be selected where the required value falls', '[{"id": "a", "text": "at the top end of the range.", "correct": false}, {"id": "b", "text": "in the middle of the range.", "correct": true}, {"id": "c", "text": "at the bottom end of the range.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The test equipment normally used to carry out a continuity test on an electrical cable is', '[{"id": "a", "text": "a high tension circuit tester.", "correct": false}, {"id": "b", "text": "an ammeter.", "correct": false}, {"id": "c", "text": "a low reading ohmmeter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If all three prongs on a bonding tester were shorted together, the metre would read', '[{"id": "a", "text": "FSD.", "correct": false}, {"id": "b", "text": "zero.", "correct": true}, {"id": "c", "text": "off-scale high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pitch of the screw thread on an English micrometer is', '[{"id": "a", "text": "0.0001 inches.", "correct": false}, {"id": "b", "text": "0.025 inches.", "correct": true}, {"id": "c", "text": "0.050 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The vernier scale on an English caliper is divided into', '[{"id": "a", "text": "25 equal divisions.", "correct": true}, {"id": "b", "text": "40 equal divisions.", "correct": false}, {"id": "c", "text": "50 equal divisions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The thimble of a metric micrometer is divided into', '[{"id": "a", "text": "25 equal divisions.", "correct": false}, {"id": "b", "text": "40 equal divisions.", "correct": false}, {"id": "c", "text": "50 equal divisions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The measuring capacity of a Vernier Caliper is', '[{"id": "a", "text": "the length of the graduated scale less the length of the vernier scale.", "correct": true}, {"id": "b", "text": "the length of the graduated scale.", "correct": false}, {"id": "c", "text": "the length of the graduated scale plus the width of the nibs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Vee-blocks are manufactured', '[{"id": "a", "text": "as single items and may be paired with any other vee-block.", "correct": false}, {"id": "b", "text": "in sets of two and identified for use as a set.", "correct": true}, {"id": "c", "text": "in sets of three and identified for use as a set.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A ketts saw is used because', '[{"id": "a", "text": "it can cut thicker metal than is required by most repair schemes.", "correct": false}, {"id": "b", "text": "it is available both pneumatic and electric.", "correct": false}, {"id": "c", "text": "its low torque allows single handed use.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The gears used in a pistol windy are', '[{"id": "a", "text": "gears in a gearbox.", "correct": false}, {"id": "b", "text": "gyrator type gears.", "correct": false}, {"id": "c", "text": "spur gears.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Cross cut files', '[{"id": "a", "text": "cut on the backward stroke only.", "correct": false}, {"id": "b", "text": "cut in both directions.", "correct": false}, {"id": "c", "text": "cut on the forward stroke only.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The correct size spanner for use on a unified 5/16 in. threaded hexagon headed bolt is', '[{"id": "a", "text": "5/16 in A/F.", "correct": false}, {"id": "b", "text": "1/2 in A/F.", "correct": true}, {"id": "c", "text": "1/4 in A/F.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The length of the Vernier Scale in a 24/25 Vernier Caliper is', '[{"id": "a", "text": "0.6 in.", "correct": true}, {"id": "b", "text": "1.2 in.", "correct": false}, {"id": "c", "text": "2.45 in.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is used to measure the depth of a blend after a corrosion repair?', '[{"id": "a", "text": "Dial Test Indicator.", "correct": false}, {"id": "b", "text": "Straight edge and slip gauges.", "correct": true}, {"id": "c", "text": "Vernier caliper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Vacu-blast beads re-used on a steel component, after being used on an aluminium component will', '[{"id": "a", "text": "cause clogging of the vacu-blast machine.", "correct": false}, {"id": "b", "text": "be ineffective in abrasion.", "correct": false}, {"id": "c", "text": "cause corrosion to the steel component.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The main scale on a 49/50 Vernier caliper is divided into', '[{"id": "a", "text": "inches, tenths and thousandths.", "correct": false}, {"id": "b", "text": "inches, tenths and twentieths.", "correct": true}, {"id": "c", "text": "inches, tenths and fortieths.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Centre punches are made of', '[{"id": "a", "text": "high carbon steel with the tip hardened and tempered.", "correct": true}, {"id": "b", "text": "case hardened mild steel.", "correct": false}, {"id": "c", "text": "high carbon steel hardened and tempered.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of flutes should be used in a reamer for cutting titanium?', '[{"id": "a", "text": "Spiral flutes.", "correct": true}, {"id": "b", "text": "Straight flutes.", "correct": false}, {"id": "c", "text": "Tapered flutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What should be the included angle of a twist drill for soft metals?', '[{"id": "a", "text": "65 degrees.", "correct": false}, {"id": "b", "text": "90 degrees.", "correct": true}, {"id": "c", "text": "118 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What should the point angle of a drill be if it is to be used for drilling titanium (drill size below 1/4 inch diameter)?', '[{"id": "a", "text": "90°", "correct": false}, {"id": "b", "text": "90° to 105°", "correct": false}, {"id": "c", "text": "105 to 120°", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How are pin punches classified?', '[{"id": "a", "text": "By length and diameter of the small end.", "correct": false}, {"id": "b", "text": "By overall length and type.", "correct": false}, {"id": "c", "text": "By type and diameter of the small end.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The purpose of a taper tap is to', '[{"id": "a", "text": "produce a fine thread.", "correct": false}, {"id": "b", "text": "start a thread.", "correct": true}, {"id": "c", "text": "form a tapered thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is the Vee cut in the base of a scribing block?', '[{"id": "a", "text": "To reduce the contact area with the marking off table and reduce friction.", "correct": true}, {"id": "b", "text": "To allow the scribing block to be used on the edge of the marking off table.", "correct": false}, {"id": "c", "text": "To trap any dirt that may be adhering to the surface of the marking off table.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An inside micrometers normal measurement range is', '[{"id": "a", "text": "1/2in. to 10in.", "correct": false}, {"id": "b", "text": "2in. to 10in.", "correct": false}, {"id": "c", "text": "2in. to 12in.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of Target Points on a Vernier caliper?', '[{"id": "a", "text": "To enable spring dividers to be accurately set.", "correct": true}, {"id": "b", "text": "To zero the caliper.", "correct": false}, {"id": "c", "text": "For scribing lines inside tubes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Die Nuts are used to', '[{"id": "a", "text": "form internal threads.", "correct": false}, {"id": "b", "text": "form external threads.", "correct": false}, {"id": "c", "text": "clean up damaged threads.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Dial Test Indicator may be used for', '[{"id": "a", "text": "checking a round bar for bow.", "correct": true}, {"id": "b", "text": "checking dimensions to within 0.125''.", "correct": false}, {"id": "c", "text": "checking any known depth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which cut of a file should be used on mild steel?', '[{"id": "a", "text": "Single cut.", "correct": false}, {"id": "b", "text": "Double cut.", "correct": true}, {"id": "c", "text": "Second cut.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following statements is correct?', '[{"id": "a", "text": "To cut thin mild steel plate use a coarse blade.", "correct": false}, {"id": "b", "text": "To cut an aluminium block use a fine hacksaw blade.", "correct": false}, {"id": "c", "text": "To cut thin sheet metal use a fine blade.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A power meter indicates that a circuit has a power of 4 kW. Separate readings of the voltage and current are 400 V and 20 A respectively. The Power factor is', '[{"id": "a", "text": "1/2.", "correct": true}, {"id": "b", "text": "2.", "correct": false}, {"id": "c", "text": "20.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is a key-seat rule used for?', '[{"id": "a", "text": "Marking lines which are parallel to a true edge.", "correct": false}, {"id": "b", "text": "Marking lines parallel to an axis of a round bar.", "correct": true}, {"id": "c", "text": "Providing a positive driving force.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When measuring current in a circuit, the ammeter is placed', '[{"id": "a", "text": "in series with the circuit.", "correct": true}, {"id": "b", "text": "in series with the shunt.", "correct": false}, {"id": "c", "text": "in parallel with the circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A 3 1/2 bit multimeter will indicate readings up-to', '[{"id": "a", "text": "999 1/2.", "correct": false}, {"id": "b", "text": "1999.", "correct": true}, {"id": "c", "text": "9999.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an English micrometer is showing 4 main divisions, 3 sub-divisions and the 25th thimble division was in line, what would the reading be?', '[{"id": "a", "text": "0.175 in.", "correct": false}, {"id": "b", "text": "0.475 in.", "correct": true}, {"id": "c", "text": "0.555 in.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An open circuit on an ohmmeter would be indicated by a reading of', '[{"id": "a", "text": "infinite resistance.", "correct": true}, {"id": "b", "text": "zero resistance.", "correct": false}, {"id": "c", "text": "a negative resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The leads of an ohmmeter should be replaced if their resistance is greater than', '[{"id": "a", "text": "0.05 ohms.", "correct": true}, {"id": "b", "text": "0.5 ohms.", "correct": false}, {"id": "c", "text": "1 ohm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Torque loading is determined by multiplying the tangent force applied at the free end of the spanner', '[{"id": "a", "text": "by the dia. of the bolt and the distance of its point of application.", "correct": false}, {"id": "b", "text": "by the distance moved by the point of application.", "correct": false}, {"id": "c", "text": "by its distance of application from the axis of the bolt.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which electrical measuring device needs a power source?', '[{"id": "a", "text": "A voltmeter.", "correct": false}, {"id": "b", "text": "An ohmmeter.", "correct": true}, {"id": "c", "text": "An ammeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When measuring voltage or current with a digital multimeter, the indication is', '[{"id": "a", "text": "average values.", "correct": false}, {"id": "b", "text": "peak values.", "correct": false}, {"id": "c", "text": "RMS values.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a multimeter, what colour lead is connected to the Common socket?', '[{"id": "a", "text": "Green", "correct": false}, {"id": "b", "text": "Red", "correct": false}, {"id": "c", "text": "Black", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Three point micrometers are for measuring', '[{"id": "a", "text": "internal dimensions.", "correct": true}, {"id": "b", "text": "external dimensions.", "correct": false}, {"id": "c", "text": "linear dimensions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When is a coarse hacksaw blade used?', '[{"id": "a", "text": "When cutting material of thick cross section.", "correct": true}, {"id": "b", "text": "When cutting ferrous metals only.", "correct": false}, {"id": "c", "text": "When cutting material of thin cross section.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A voltage drop across a component is measured by placing the meter in', '[{"id": "a", "text": "parallel with the component.", "correct": true}, {"id": "b", "text": "series with the component.", "correct": false}, {"id": "c", "text": "series with the power source.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following reamers would you use in a hole having a keyway?', '[{"id": "a", "text": "Expanding reamer.", "correct": false}, {"id": "b", "text": "Spiral fluted reamer.", "correct": true}, {"id": "c", "text": "Parallel reamer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of a Morse taper on large sizes of twist drills?', '[{"id": "a", "text": "To allow the drills to be fitted to a drilling machine.", "correct": true}, {"id": "b", "text": "To ensure that the drill is fitted correctly.", "correct": false}, {"id": "c", "text": "To give a positive drive when fitted into a tapered chuck.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What should be the included angle of a twist drill for hard metal?', '[{"id": "a", "text": "90 degrees", "correct": false}, {"id": "b", "text": "100 degrees", "correct": false}, {"id": "c", "text": "118 degrees", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The threads per inch on the spindle of an English micrometer are', '[{"id": "a", "text": "25 t.p.i.", "correct": false}, {"id": "b", "text": "40 t.p.i.", "correct": true}, {"id": "c", "text": "50 t.p.i.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The spring loaded ratchet attached to the spindle of a standard external micrometer produces', '[{"id": "a", "text": "a pre-set feel during use.", "correct": true}, {"id": "b", "text": "a means for controlling thread binding.", "correct": false}, {"id": "c", "text": "a smooth free run during use.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The purpose of the land on a twist drill is to', '[{"id": "a", "text": "allow clearance for swarf.", "correct": false}, {"id": "b", "text": "reduce friction.", "correct": true}, {"id": "c", "text": "present the cutting edge at the required angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The name given to the moving scale on the Vernier caliper is', '[{"id": "a", "text": "the main scale.", "correct": false}, {"id": "b", "text": "the vernier scale.", "correct": true}, {"id": "c", "text": "the cursor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What does the cut of a file refer to?', '[{"id": "a", "text": "Arrangement of the teeth.", "correct": true}, {"id": "b", "text": "Number of teeth per inch.", "correct": false}, {"id": "c", "text": "Grade", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why are teeth of hacksaw blades off-set?', '[{"id": "a", "text": "To allow a quick cutting positive action.", "correct": false}, {"id": "b", "text": "To provide greater strength.", "correct": false}, {"id": "c", "text": "To provide clearance for non-cutting part of the blade.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How are files classified?', '[{"id": "a", "text": "By length, grade and material.", "correct": false}, {"id": "b", "text": "By length, grade, cut and section.", "correct": true}, {"id": "c", "text": "By length, grade, cut, section and material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hammers are classified by', '[{"id": "a", "text": "shape of head and length of shaft.", "correct": false}, {"id": "b", "text": "weight and length of shaft.", "correct": false}, {"id": "c", "text": "weight and type of head.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What comprises a full set of BA taps?', '[{"id": "a", "text": "A taper, second and plug tap.", "correct": true}, {"id": "b", "text": "A taper and second tap.", "correct": false}, {"id": "c", "text": "A taper and plug tap.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The teeth on a hacksaw blade', '[{"id": "a", "text": "does not matter which way they point.", "correct": false}, {"id": "b", "text": "should point away from the handle.", "correct": true}, {"id": "c", "text": "should point towards the handle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the clearance angle on a normal twist drill?', '[{"id": "a", "text": "12 degrees", "correct": true}, {"id": "b", "text": "59 degrees", "correct": false}, {"id": "c", "text": "130 degrees", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When tapping blind holes', '[{"id": "a", "text": "a set of three taps is used.", "correct": true}, {"id": "b", "text": "a set of two taps is used.", "correct": false}, {"id": "c", "text": "a single tap is used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a torque wrench the torque loading is', '[{"id": "a", "text": "the tangential application of the force divided by the perpendicular distance to the centre of the bolt.", "correct": false}, {"id": "b", "text": "the tangential application of the force times the perpendicular distance to the centre of the bolt.", "correct": true}, {"id": "c", "text": "the tangential application of the force plus the perpendicular distance to the centre of the bolt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Surface Plates are used', '[{"id": "a", "text": "for marking out work and testing flat surfaces.", "correct": true}, {"id": "b", "text": "for filing flat surfaces.", "correct": false}, {"id": "c", "text": "only on surface tables.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The main scale of a Metric Vernier Caliper is calibrated in', '[{"id": "a", "text": "millimetres.", "correct": true}, {"id": "b", "text": "micro-meters.", "correct": false}, {"id": "c", "text": "millimetres and half millimetres.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'For a drill to cut properly it is essential that the point angle be the same on each side, for general use the angle is', '[{"id": "a", "text": "12°.", "correct": false}, {"id": "b", "text": "59°.", "correct": true}, {"id": "c", "text": "130°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pitch of a hacksaw blade is', '[{"id": "a", "text": "the number of teeth per inch.", "correct": true}, {"id": "b", "text": "its length.", "correct": false}, {"id": "c", "text": "the number of teeth on the blade.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a bench grinding machine the wheel rotates', '[{"id": "a", "text": "from the top down towards the work piece.", "correct": true}, {"id": "b", "text": "either direction as selected on starting the machine.", "correct": false}, {"id": "c", "text": "from the bottom upwards past the work piece.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The thimble of an English micrometer is divided into', '[{"id": "a", "text": "25 equal divisions.", "correct": true}, {"id": "b", "text": "40 equal divisions.", "correct": false}, {"id": "c", "text": "50 equal divisions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The vernier height gauge uses the same principle as', '[{"id": "a", "text": "the vernier caliper.", "correct": true}, {"id": "b", "text": "the micrometer.", "correct": false}, {"id": "c", "text": "the bevel protractor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An avometer can measure alternating current because it has a', '[{"id": "a", "text": "moving coil.", "correct": false}, {"id": "b", "text": "bridge rectifier circuit.", "correct": true}, {"id": "c", "text": "moving iron.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Taper reamers are classified by', '[{"id": "a", "text": "a type number (1 to 10).", "correct": true}, {"id": "b", "text": "the diameter of the small end.", "correct": false}, {"id": "c", "text": "the diameter of the large end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A crimped electrical connection is suspected to be high resistance. How would you verify this without disconnecting the circuit?', '[{"id": "a", "text": "Measure the millivolt drop across the connection with a millivolt meter.", "correct": true}, {"id": "b", "text": "Measure the resistance with an ohmmeter.", "correct": false}, {"id": "c", "text": "Measure the resistance with a 250 volt megger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How would you measure continuity of a coaxial cable?', '[{"id": "a", "text": "With a safety ohmmeter.", "correct": true}, {"id": "b", "text": "With a reflectometer.", "correct": false}, {"id": "c", "text": "With a 250 volt megger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a long coaxial cable how would you check for discontinuities and shorts in suit?', '[{"id": "a", "text": "Continuity tester.", "correct": false}, {"id": "b", "text": "Safety ohmmeter.", "correct": false}, {"id": "c", "text": "Time Domain Reflectometer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the leads of a bonding tester are damaged, what is the procedure?', '[{"id": "a", "text": "The damaged leads and the tester should be returned to the manufacturer for repair and calibration.", "correct": true}, {"id": "b", "text": "Provided that the damage is situated close to the end of the leads the cable may be shortened.", "correct": false}, {"id": "c", "text": "A new lead may be manufactured using the correct current rated cable.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a continuity test on a circuit when a known resistance exists, what instrument would you use?', '[{"id": "a", "text": "A lamp and battery.", "correct": false}, {"id": "b", "text": "A high resistance insulation tester.", "correct": false}, {"id": "c", "text": "A multimeter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Taper pins are classified by', '[{"id": "a", "text": "length and diameter of large end.", "correct": true}, {"id": "b", "text": "length and diameter of small end.", "correct": false}, {"id": "c", "text": "length and taper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Live AC circuits are to be checked for open circuits by the use of', '[{"id": "a", "text": "multimeter set to AC volts.", "correct": true}, {"id": "b", "text": "ammeter set to amps.", "correct": false}, {"id": "c", "text": "ohmmeter set to megohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A multiplier resistance is used to extend the working range of the', '[{"id": "a", "text": "ammeter.", "correct": false}, {"id": "b", "text": "voltmeter.", "correct": true}, {"id": "c", "text": "ohmmeter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On twist drill chart, small drills have', '[{"id": "a", "text": "smallest numbers.", "correct": false}, {"id": "b", "text": "largest numbers.", "correct": true}, {"id": "c", "text": "their sizes in fractions, in inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The Sine Bar is used to', '[{"id": "a", "text": "check accuracy of slip gauges.", "correct": false}, {"id": "b", "text": "produce angles using slip gauges.", "correct": true}, {"id": "c", "text": "by itself to calculate angles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a vernier micrometer, what will three turns of the barrel represent?', '[{"id": "a", "text": "0.050 inch", "correct": false}, {"id": "b", "text": "0.075 inch", "correct": true}, {"id": "c", "text": "0.100 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How does a windy drill get its power?', '[{"id": "a", "text": "Spur gears", "correct": false}, {"id": "b", "text": "Impeller", "correct": false}, {"id": "c", "text": "Bevel gears", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How are taper reamers classified?', '[{"id": "a", "text": "Length, diameter of large end, and diameter of small end.", "correct": true}, {"id": "b", "text": "Taper and diameter of small end.", "correct": false}, {"id": "c", "text": "Length and diameter of large end.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An AC voltmeter reads', '[{"id": "a", "text": "peak value.", "correct": false}, {"id": "b", "text": "peak to peak value.", "correct": false}, {"id": "c", "text": "average value.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hydrometer is used to', '[{"id": "a", "text": "check battery electrolyte specific gravity.", "correct": true}, {"id": "b", "text": "check battery electrolyte density.", "correct": false}, {"id": "c", "text": "take humidity reading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A pyrometer is a', '[{"id": "a", "text": "thermometer for use at high temperature.", "correct": true}, {"id": "b", "text": "pyramid shaped altimeter.", "correct": false}, {"id": "c", "text": "foam/granule fire extinguisher.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hygrometer is used to', '[{"id": "a", "text": "check battery electrolyte relative density.", "correct": false}, {"id": "b", "text": "take humidity reading.", "correct": true}, {"id": "c", "text": "check battery electrolyte specific gravity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To measure AC with a moving coil, it', '[{"id": "a", "text": "can be directly connected.", "correct": false}, {"id": "b", "text": "is rectified and measures peak value.", "correct": false}, {"id": "c", "text": "is rectified and measures average value.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is a countersink tool used for?', '[{"id": "a", "text": "To prevent damage to pipework in a blind hole.", "correct": false}, {"id": "b", "text": "To adjust the depth of a countersink.", "correct": true}, {"id": "c", "text": "To adjust the angle of a countersink.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'PIDG crimp tools are marked by', '[{"id": "a", "text": "wire crimp size on tool only.", "correct": false}, {"id": "b", "text": "coloured handles and wire crimp size on tool.", "correct": true}, {"id": "c", "text": "coloured handles only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When measuring a square waveform with a multimeter, what voltage does it display?', '[{"id": "a", "text": "Less than RMS value.", "correct": false}, {"id": "b", "text": "More than RMS value.", "correct": false}, {"id": "c", "text": "Equal to RMS value.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an ammeter reads 0 - 1mA FSD, what would you be required to do to enable it to read 10mA FSD?', '[{"id": "a", "text": "Place a 5.8 ohm resistor as a shunt in parallel with the meter.", "correct": false}, {"id": "b", "text": "Place a 9.9 ohm resistor across the coils.", "correct": true}, {"id": "c", "text": "Place a 9 ohm resistor in series with the meter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The internal resistance of a voltmeter is', '[{"id": "a", "text": "no more than 0.05 ohms.", "correct": false}, {"id": "b", "text": "low.", "correct": false}, {"id": "c", "text": "high.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The internal resistance of an ammeter is', '[{"id": "a", "text": "low.", "correct": true}, {"id": "b", "text": "1 ohm.", "correct": false}, {"id": "c", "text": "high.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A drill bit of 0.250 inch would be', '[{"id": "a", "text": "7/32 and letter G.", "correct": false}, {"id": "b", "text": "8/32 and letter E.", "correct": true}, {"id": "c", "text": "6/32 and letter F.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Needle grease points are used on', '[{"id": "a", "text": "items with gland seals.", "correct": false}, {"id": "b", "text": "small pivoted joints.", "correct": true}, {"id": "c", "text": "large pivoted joints.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A flat chisel being used for aluminium should have a point angle of', '[{"id": "a", "text": "30 degrees.", "correct": true}, {"id": "b", "text": "55 degrees.", "correct": false}, {"id": "c", "text": "65 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A mill file can be used for', '[{"id": "a", "text": "corners less than 60 degrees.", "correct": false}, {"id": "b", "text": "saw sharpening.", "correct": false}, {"id": "c", "text": "general purpose.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A rawhide mallet is', '[{"id": "a", "text": "available with copper inserts.", "correct": false}, {"id": "b", "text": "less expensive than bossing mallet.", "correct": false}, {"id": "c", "text": "used for giving softer blows than boxwood mallet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Tension files', '[{"id": "a", "text": "can be used to cut in one direction only.", "correct": true}, {"id": "b", "text": "clog easily.", "correct": false}, {"id": "c", "text": "can cut in either direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The scale on an ohmmeter is', '[{"id": "a", "text": "cramped at high resistance.", "correct": true}, {"id": "b", "text": "linear.", "correct": false}, {"id": "c", "text": "cramped at low resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Three revolutions of a 40 T.P.l. micrometer will show', '[{"id": "a", "text": "0.003 inch.", "correct": false}, {"id": "b", "text": "0.03 inch.", "correct": false}, {"id": "c", "text": "0.075 inch.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To carry out a continuity test you would use', '[{"id": "a", "text": "ammeter.", "correct": false}, {"id": "b", "text": "an HT circuit tester.", "correct": false}, {"id": "c", "text": "a low reading ohmmeter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the resolution of a standard DTI?', '[{"id": "a", "text": "0.010 mm.", "correct": true}, {"id": "b", "text": "0.020 mm.", "correct": false}, {"id": "c", "text": "0.050 mm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a moving coil meter the deflecting force is provided by', '[{"id": "a", "text": "a soft iron permanent magnet.", "correct": false}, {"id": "b", "text": "a current carrying coil pivoted in a permanent magnet field.", "correct": true}, {"id": "c", "text": "hairsprings which move the pointer towards full scale.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The force acting on a meter which returns the pointer to zero is called the', '[{"id": "a", "text": "turning force.", "correct": false}, {"id": "b", "text": "deflecting force.", "correct": false}, {"id": "c", "text": "controlling force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The forces acting on a meter which moves the pointer over the scale is called', '[{"id": "a", "text": "the controlling force.", "correct": false}, {"id": "b", "text": "the turning force.", "correct": false}, {"id": "c", "text": "the deflecting force.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The resistance of an ammeter must be', '[{"id": "a", "text": "high to create a large volts drop across it.", "correct": false}, {"id": "b", "text": "low to prevent volts drop across it.", "correct": true}, {"id": "c", "text": "low because the ammeter is in parallel with the circuit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The resistance of a voltmeter must be', '[{"id": "a", "text": "high so that little current passes through it.", "correct": true}, {"id": "b", "text": "low to prevent overloading the circuit.", "correct": false}, {"id": "c", "text": "low to provide a parallel path for the circuit current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When operating a grease gun, you', '[{"id": "a", "text": "verify grease fitting can accept grease by hand feel.", "correct": false}, {"id": "b", "text": "apply a pressure of 50 - 80 psi.", "correct": false}, {"id": "c", "text": "clean grease fitting with clean dry cloth beforehand.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A fuel quantity test set has an externally adjustable', '[{"id": "a", "text": "capacitor.", "correct": true}, {"id": "b", "text": "inductor.", "correct": false}, {"id": "c", "text": "resistor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How would you test a mach switch in-situ?', '[{"id": "a", "text": "Use built in test equipment.", "correct": true}, {"id": "b", "text": "Use an external test kit.", "correct": false}, {"id": "c", "text": "It is not possible to test a mach switch in situ.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum value of bonding of a secondary structure is', '[{"id": "a", "text": "1 ohm.", "correct": true}, {"id": "b", "text": "1 kilohm.", "correct": false}, {"id": "c", "text": "1 megohm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Circuit tests on aircraft should be carried out in the following order:', '[{"id": "a", "text": "bonding, continuity, insulation, functional.", "correct": true}, {"id": "b", "text": "continuity, bonding, functional, insulation.", "correct": false}, {"id": "c", "text": "functional, bonding, continuity, insulation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Before using a dead weight tester you would', '[{"id": "a", "text": "calibrate the tester using a standard weight.", "correct": true}, {"id": "b", "text": "pressurize the tester to the required pressure.", "correct": false}, {"id": "c", "text": "replace the oil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should a dead weight tester be used?', '[{"id": "a", "text": "The pressure increasing handle should be screwed in before the addition of fluid and screwed out when fluid", "correct": true}, {"id": "b", "text": "The outlet should not be connected to the instrument until the required weights are raised by the platform.", "correct": false}, {"id": "c", "text": "The platform should be removed and fluid poured into the hole.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When testing thermocouples using a test set the ambient temperature', '[{"id": "a", "text": "never needs to be considered.", "correct": false}, {"id": "b", "text": "is considered every time.", "correct": true}, {"id": "c", "text": "is only considered when temperatures of 20°C or above.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Electronic test equipment for fuel tank contents systems usually incorporate variable', '[{"id": "a", "text": "resistors.", "correct": false}, {"id": "b", "text": "inductors.", "correct": false}, {"id": "c", "text": "capacitors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Before using a bonding tester, the 6 foot lead has the two prongs shorted together with a piece of metal. What would the indicator read?', '[{"id": "a", "text": "Full scale left.", "correct": false}, {"id": "b", "text": "Full scale right.", "correct": true}, {"id": "c", "text": "Zero at the centre.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a megger to test insulation resistance, capacitive filters should be disconnected for what reason?', '[{"id": "a", "text": "Remove the risk of damage to the megger.", "correct": false}, {"id": "b", "text": "Remove the spurious readings caused by the capacitors charging and discharging.", "correct": true}, {"id": "c", "text": "Prevent damage to the filters.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a serviceability check on a bonding tester - short together the three prongs of both probes and ensure which of the following?', '[{"id": "a", "text": "The meter reads 0.1 ohm.", "correct": false}, {"id": "b", "text": "A zero reading.", "correct": true}, {"id": "c", "text": "A full scale reading is obtained.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an insulation resistance tester is operated and the leads are suspended in free air, what will the meter read?', '[{"id": "a", "text": "Zero.", "correct": false}, {"id": "b", "text": "Mid scale - it is a ratiometer movement and there is no current flowing in the external circuit.", "correct": false}, {"id": "c", "text": "Infinity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a digital meter to test a diode, a correct operation of the diode is indicated by a volt drop of', '[{"id": "a", "text": "0.3V to 0.7V.", "correct": true}, {"id": "b", "text": "1.5V to 2V.", "correct": false}, {"id": "c", "text": "2.5V to 2.8V.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To check that the ident pulse is being generated from an ATC transponder,', '[{"id": "a", "text": "select an ATC channel and check the morse code.", "correct": false}, {"id": "b", "text": "select ident and check the indication on the instrument panel.", "correct": false}, {"id": "c", "text": "press the ident and monitor the indication on the ramp test set.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A pressure gauge is fitted to a Dead Weight Tester. The piston area is 0.25 sq.in. and the total mass of the mass carrier and masses is 5lb. If the pressure gauge is accurate what pressure in pounds per square inch (PSI) will it read?', '[{"id": "a", "text": "1.25 psi.", "correct": false}, {"id": "b", "text": "20 psi.", "correct": true}, {"id": "c", "text": "200 psi.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When testing a fuel metering unit, how is it checked?', '[{"id": "a", "text": "With the meter in series with the unit.", "correct": true}, {"id": "b", "text": "With the unit disconnected.", "correct": false}, {"id": "c", "text": "With the meter in parallel with the unit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a bonding tester', '[{"id": "a", "text": "ensure prongs penetrate anodised layer.", "correct": true}, {"id": "b", "text": "ensure prongs do not penetrate anodising layer.", "correct": false}, {"id": "c", "text": "an anodised component cannot be tested.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a static leak tester, pressure is released by', '[{"id": "a", "text": "an internal balance valve in the tester.", "correct": false}, {"id": "b", "text": "slowly opening the release knob for 3 minutes.", "correct": false}, {"id": "c", "text": "a bleed valve in the tester.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A fuel calibration test set when used to check an aircraft with half a fuel load is connected', '[{"id": "a", "text": "to gauge with fuel level in parallel.", "correct": false}, {"id": "b", "text": "to gauge with fuel level capacitance.", "correct": true}, {"id": "c", "text": "to gauge with fuel level in series.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A capacitive fuel contents system should be tested with', '[{"id": "a", "text": "a ratiometer.", "correct": true}, {"id": "b", "text": "a Wheatstone bridge.", "correct": false}, {"id": "c", "text": "a decade box.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Continuity of a fibreoptic cable is tested with a', '[{"id": "a", "text": "light source and optometer.", "correct": false}, {"id": "b", "text": "multimeter.", "correct": false}, {"id": "c", "text": "calibrated light generator and opto-power meter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using transistorized test equipment, what should the output be?', '[{"id": "a", "text": "Not affected by impedance.", "correct": false}, {"id": "b", "text": "High impedance.", "correct": true}, {"id": "c", "text": "Low impedance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bonding lead testers are attached with', '[{"id": "a", "text": "a 60 feet lead is connected to the main earth and a 6 foot test lead is connected to check the resistance between", "correct": false}, {"id": "b", "text": "a 6 feet test lead is connected to the main earth and a 60 feet lead is connected to check the resistance", "correct": true}, {"id": "c", "text": "either of the leads can be connected anywhere.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a Bonding Tester the number of probes on the 60 ft and 6ft leads respectively are', '[{"id": "a", "text": "1 and 2.", "correct": false}, {"id": "b", "text": "2 and 2.", "correct": false}, {"id": "c", "text": "2 and 1.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The damping force in a meter', '[{"id": "a", "text": "prevents oscillation of the pointer.", "correct": true}, {"id": "b", "text": "returns a pointer to zero.", "correct": false}, {"id": "c", "text": "assists the pointer to move over the scale.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The width of a visible outline on a drawing is', '[{"id": "a", "text": "0.3 mm.", "correct": false}, {"id": "b", "text": "0.5 mm.", "correct": false}, {"id": "c", "text": "0.7 mm.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What does GA stand for on a drawing?', '[{"id": "a", "text": "General assembly.", "correct": false}, {"id": "b", "text": "General arrangement.", "correct": true}, {"id": "c", "text": "Gradient Axis.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Design drawings of aircraft components are produced by organizations approved by', '[{"id": "a", "text": "SBAC.", "correct": false}, {"id": "b", "text": "British Standards Institute.", "correct": false}, {"id": "c", "text": "CAA in accordance with the BCARs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol found on an engineering drawing would mean', '[{"id": "a", "text": "cylindricity.", "correct": false}, {"id": "b", "text": "angularity.", "correct": true}, {"id": "c", "text": "concentricity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which pictorial projection shows one face in true elevation and line of depth normally draw at 30° or 45° to the horizontal?', '[{"id": "a", "text": "Oblique.", "correct": true}, {"id": "b", "text": "Perspective.", "correct": false}, {"id": "c", "text": "Isometric.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a design amendment is made on a drawing', '[{"id": "a", "text": "a new issue number and date must be allocated to the drawing.", "correct": true}, {"id": "b", "text": "the old issue number is retained, with the amendment date added.", "correct": false}, {"id": "c", "text": "no change in issue number or date is necessary.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The British Standard for Engineering Drawings is', '[{"id": "a", "text": "BS 306.", "correct": false}, {"id": "b", "text": "BS 307.", "correct": false}, {"id": "c", "text": "BS 308.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'P.C.D. is an abbreviation for', '[{"id": "a", "text": "Pitch Circle Diameter.", "correct": true}, {"id": "b", "text": "Pitch Cord Diameter.", "correct": false}, {"id": "c", "text": "Precision Circle Dimension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This represents', '[{"id": "a", "text": "bearing on shaft.", "correct": false}, {"id": "b", "text": "squared shaft.", "correct": true}, {"id": "c", "text": "relief valve.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This represents', '[{"id": "a", "text": "an internal thread.", "correct": true}, {"id": "b", "text": "a counterbored hole.", "correct": false}, {"id": "c", "text": "an external thread.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Drawing numbers are', '[{"id": "a", "text": "the same as serial numbers.", "correct": false}, {"id": "b", "text": "changed after each drawing amended after May 28, 1999.", "correct": false}, {"id": "c", "text": "unique to each drawing.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hatching lines are usually drawn at:', '[{"id": "a", "text": "30°.", "correct": false}, {"id": "b", "text": "45°.", "correct": true}, {"id": "c", "text": "60°.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The scale of an engineering drawing is shown as 1 : 4. This indicates it is', '[{"id": "a", "text": "drawn to a quarter.", "correct": true}, {"id": "b", "text": "drawn to scale.", "correct": false}, {"id": "c", "text": "drawn four times larger.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Effective continuity is not possible unless which of the following conditions exists?', '[{"id": "a", "text": "The portion of the circuit under test must constitute a simple series circuit with no parallel paths.", "correct": true}, {"id": "b", "text": "All circuit earths are disconnected.", "correct": false}, {"id": "c", "text": "All manually operated switches must be off.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An orthographic projection usually shows', '[{"id": "a", "text": "one, three-dimensional view of an object.", "correct": false}, {"id": "b", "text": "a pictorial view of the object.", "correct": false}, {"id": "c", "text": "three, two-dimensional views of an object.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When dimensioning a drawing, the dimension lines should be', '[{"id": "a", "text": "the minimum number of dimensions necessary to enable the component to be manufactured.", "correct": true}, {"id": "b", "text": "as many dimensions as possible.", "correct": false}, {"id": "c", "text": "only size dimensions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'S.W.G. is an abbreviation for', '[{"id": "a", "text": "Standard Wire Gauge.", "correct": true}, {"id": "b", "text": "Screw Width Gauge.", "correct": false}, {"id": "c", "text": "Standard Water Gauge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What colour is used to indicate a tertiary structure on a diagram or drawing?', '[{"id": "a", "text": "Red", "correct": false}, {"id": "b", "text": "Green", "correct": true}, {"id": "c", "text": "Yellow", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which parts of the aircraft are classified secondary structures?', '[{"id": "a", "text": "Highly stressed parts but if damaged will not cause failure of the aircraft.", "correct": true}, {"id": "b", "text": "Highly stressed parts and if damaged may cause failure of the aircraft and loss of life.", "correct": false}, {"id": "c", "text": "Lightly stressed parts such as fairings, wheel shields and minor component brackets etc.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol found on an engineering drawing would mean', '[{"id": "a", "text": "angularity.", "correct": false}, {"id": "b", "text": "cylindricity.", "correct": false}, {"id": "c", "text": "concentricity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol means', '[{"id": "a", "text": "first angle projection.", "correct": true}, {"id": "b", "text": "third angle projection.", "correct": false}, {"id": "c", "text": "second angle projection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The abbreviation B.A. means', '[{"id": "a", "text": "British Assembly.", "correct": false}, {"id": "b", "text": "British Association.", "correct": true}, {"id": "c", "text": "British Arrangement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This tolerance symbol means', '[{"id": "a", "text": "position.", "correct": true}, {"id": "b", "text": "angularity.", "correct": false}, {"id": "c", "text": "diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Where are correct layout, dimensioning, numbering and reference procedures for engineering drawing are to be found?', '[{"id": "a", "text": "BS 31", "correct": false}, {"id": "b", "text": "BS 1916", "correct": false}, {"id": "c", "text": "BS 308", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), '10 : 1 on an engineering drawing indicates', '[{"id": "a", "text": "the drawing is full size.", "correct": false}, {"id": "b", "text": "the drawing is one tenth full size.", "correct": false}, {"id": "c", "text": "the drawing is ten times full size.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When reading an engineering drawing, this symbol means', '[{"id": "a", "text": "profile of a line.", "correct": false}, {"id": "b", "text": "profile of a surface.", "correct": true}, {"id": "c", "text": "profile of a position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Lines known as short dashes (thin) are used on drawings to indicate', '[{"id": "a", "text": "hidden detail.", "correct": true}, {"id": "b", "text": "visible outlines.", "correct": false}, {"id": "c", "text": "cutting revolved.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol means', '[{"id": "a", "text": "flatness.", "correct": true}, {"id": "b", "text": "perpendicularity.", "correct": false}, {"id": "c", "text": "position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Any change to a drawing', '[{"id": "a", "text": "must be notified to the S.B.A.C.", "correct": false}, {"id": "b", "text": "must be accompanied by the new issue number and date.", "correct": true}, {"id": "c", "text": "requires a new drawing number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol on a drawing means', '[{"id": "a", "text": "washed and packed.", "correct": false}, {"id": "b", "text": "solution treated and precipitated.", "correct": true}, {"id": "c", "text": "solution treated and requiring precipitation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol means', '[{"id": "a", "text": "dimensionality.", "correct": false}, {"id": "b", "text": "diameter.", "correct": false}, {"id": "c", "text": "concentricity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Break lines are used', '[{"id": "a", "text": "to show where components are expected to break.", "correct": false}, {"id": "b", "text": "in sectional drawing.", "correct": false}, {"id": "c", "text": "where it would be inconvenient (because of limited space) to draw long lengths of the same section.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An oblique projection', '[{"id": "a", "text": "is the same as an isometric projection.", "correct": false}, {"id": "b", "text": "has one view looking directly at one face with the lines representing depth drawn at 90°.", "correct": true}, {"id": "c", "text": "has one view looking directly at one face with the lines representing depth drawn at a constant angle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A drawing in which the sub-assemblies or parts are shown as brought together on the aircraft is called', '[{"id": "a", "text": "an installation drawing.", "correct": true}, {"id": "b", "text": "a detail drawing.", "correct": false}, {"id": "c", "text": "a sectional drawing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A thread on a drawing is labeled 1/2-20 UNF – 1B. The thread is', '[{"id": "a", "text": "either external or internal, depending on the application.", "correct": false}, {"id": "b", "text": "external.", "correct": false}, {"id": "c", "text": "internal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'NTS on a drawing stands for', '[{"id": "a", "text": "Not True Scale.", "correct": false}, {"id": "b", "text": "No Tolerance System.", "correct": false}, {"id": "c", "text": "Not To Scale.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hydraulic system schematic drawing would indicate the', '[{"id": "a", "text": "type and quantity of the hydraulic fluid.", "correct": false}, {"id": "b", "text": "specific location of the individual components within the aircraft.", "correct": false}, {"id": "c", "text": "direction of fluid flow through the system.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which statement is true regarding an orthographic projection?', '[{"id": "a", "text": "There are always at least two views.", "correct": false}, {"id": "b", "text": "It could have as many as eight views.", "correct": false}, {"id": "c", "text": "One-view, two-view, and three-view drawings are the most common.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A line used to show an edge which is not visible is a', '[{"id": "a", "text": "break line.", "correct": false}, {"id": "b", "text": "phantom line.", "correct": false}, {"id": "c", "text": "hidden line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'One purpose for schematic diagrams is to show the', '[{"id": "a", "text": "size and shape of components within a system.", "correct": false}, {"id": "b", "text": "functional location of components within a system.", "correct": true}, {"id": "c", "text": "physical location of components within a system.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This type of break line represents', '[{"id": "a", "text": "round bar.", "correct": true}, {"id": "b", "text": "round tube.", "correct": false}, {"id": "c", "text": "square tube.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of line is normally used in a mechanical drawing or blueprint to represent an edge or object not visible to the viewer?', '[{"id": "a", "text": "Alternate short and long light dashes.", "correct": true}, {"id": "b", "text": "Medium-weight dashed line.", "correct": false}, {"id": "c", "text": "Light solid line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A specific measured distance from the datum or some other point identified by the manufacturer, to a point in or on the aircraft is called a', '[{"id": "a", "text": "zone number.", "correct": false}, {"id": "b", "text": "station number.", "correct": true}, {"id": "c", "text": "specification number.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This electrical symbol represents a', '[{"id": "a", "text": "double pole – double throw switch.", "correct": true}, {"id": "b", "text": "double pole – single throw switch.", "correct": false}, {"id": "c", "text": "single pole – double throw switch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This electrical symbol represents a', '[{"id": "a", "text": "variable inductor.", "correct": false}, {"id": "b", "text": "air core inductor.", "correct": false}, {"id": "c", "text": "iron core inductor.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This electrical symbol represents a', '[{"id": "a", "text": "Zener diode.", "correct": false}, {"id": "b", "text": "PNP transistor.", "correct": true}, {"id": "c", "text": "NPN transistor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a first angle orthographic projection the plan view is placed', '[{"id": "a", "text": "above the front elevation.", "correct": false}, {"id": "b", "text": "below the side elevation.", "correct": false}, {"id": "c", "text": "below the front elevation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a cutting plane on a drawing cuts a web longitudinally, the web is', '[{"id": "a", "text": "sectioned the same as the rest of the view.", "correct": false}, {"id": "b", "text": "not sectioned.", "correct": true}, {"id": "c", "text": "sectioned with different direction of hatch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This electrical symbol represents a', '[{"id": "a", "text": "push to reset circuit breaker.", "correct": false}, {"id": "b", "text": "push-pull circuit breaker.", "correct": true}, {"id": "c", "text": "toggle switch circuit breaker.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This electrical symbol represents a', '[{"id": "a", "text": "fuse.", "correct": true}, {"id": "b", "text": "flexible coupling.", "correct": false}, {"id": "c", "text": "light bulb.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a cutting plane goes through a bush and bolt assembly, on the sectioned view', '[{"id": "a", "text": "both the bush and the bolt will be hatched.", "correct": false}, {"id": "b", "text": "the bush will be hatched but the bolt will not.", "correct": true}, {"id": "c", "text": "neither the bush nor the bolt will be hatched.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This symbol indicates that', '[{"id": "a", "text": "chisels must not be used.", "correct": false}, {"id": "b", "text": "machining is required on a particular surface.", "correct": true}, {"id": "c", "text": "machining is required on all surfaces.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This is a diagram of', '[{"id": "a", "text": "a voltage regulator.", "correct": false}, {"id": "b", "text": "a potentiometer.", "correct": true}, {"id": "c", "text": "a voltage divider.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following lines indicate hidden detail on a drawing?', '[{"id": "a", "text": "A broken line as shown in 2.", "correct": true}, {"id": "b", "text": "A broken line as shown in 3.", "correct": false}, {"id": "c", "text": "A continuous line as shown in 1.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The letter A.F.D. in a circle stamped on a material indicates that it has', '[{"id": "a", "text": "been anodic flaw detected.", "correct": true}, {"id": "b", "text": "been annealed fired and doped.", "correct": false}, {"id": "c", "text": "an across flats diameter bolt.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Where would Zone 324 be found in ATA 100?', '[{"id": "a", "text": "Between rear spar of wing and trailing edge of wing.", "correct": false}, {"id": "b", "text": "Tip of horizontal stabilizer.", "correct": true}, {"id": "c", "text": "Fwd of the wing rear spar.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'This is a diagram of a', '[{"id": "a", "text": "potentiometer.", "correct": true}, {"id": "b", "text": "variable resistor.", "correct": false}, {"id": "c", "text": "rheostat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The latest drawing is identified by the', '[{"id": "a", "text": "issue number.", "correct": true}, {"id": "b", "text": "amendment number.", "correct": false}, {"id": "c", "text": "date.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A geometric tolerance symbol indicating that one edge must be parallel to a datum edge would be shown in which of the following conventions?', '[{"id": "a", "text": "Convention A", "correct": false}, {"id": "b", "text": "Convention B", "correct": false}, {"id": "c", "text": "Convention C", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Tolerances are classified in two ways, these are', '[{"id": "a", "text": "Dimensional and isometric.", "correct": false}, {"id": "b", "text": "Upper and lower.", "correct": false}, {"id": "c", "text": "Dimensional and geometric.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum permissible bow in a steel tube is', '[{"id": "a", "text": "1 : 600", "correct": true}, {"id": "b", "text": "1 : 400", "correct": false}, {"id": "c", "text": "1 : 200", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the maximum bow allowed in a strut?', '[{"id": "a", "text": "1 in 200", "correct": false}, {"id": "b", "text": "1 in 500", "correct": false}, {"id": "c", "text": "1 in 600", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following shafts would you use to obtain a clearance fit in a bush 0.750 inch diameter?', '[{"id": "a", "text": "0.752 inch.", "correct": false}, {"id": "b", "text": "0.748 inch", "correct": true}, {"id": "c", "text": "750 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A tolerance is', '[{"id": "a", "text": "a permitted difference between new and worn dimensions.", "correct": false}, {"id": "b", "text": "a permitted variation on a dimension to allow for inaccuracy of equipment.", "correct": true}, {"id": "c", "text": "a required difference in dimension between mating parts to obtain a certain class of fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A transition fit is one in which the shaft is', '[{"id": "a", "text": "larger than the hole.", "correct": false}, {"id": "b", "text": "smaller than the hole.", "correct": false}, {"id": "c", "text": "the same size as the hole.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The length of a blended repair of corrosion should be no less than', '[{"id": "a", "text": "5 times its depth.", "correct": false}, {"id": "b", "text": "10 times its depth.", "correct": false}, {"id": "c", "text": "20 times its depth.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If there is a positive allowance between the smallest possible hole and the largest possible shaft, the fit is known as', '[{"id": "a", "text": "a transition fit.", "correct": false}, {"id": "b", "text": "a clearance fit.", "correct": true}, {"id": "c", "text": "an interference fit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After mechanical removal of corrosion on an aluminium alloy casting, the length of the blended recess should be', '[{"id": "a", "text": "no less than ten times the depth.", "correct": false}, {"id": "b", "text": "no less than twenty times the depth.", "correct": true}, {"id": "c", "text": "no more than twenty times the depth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A press fit requires', '[{"id": "a", "text": "some sort of driving force.", "correct": true}, {"id": "b", "text": "the shaft to be shrunk by cooling.", "correct": false}, {"id": "c", "text": "the hole to be expanded by heat.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the typical acceptable limit of a dent on a frame member?', '[{"id": "a", "text": "One and a half times the skin thickness.", "correct": false}, {"id": "b", "text": "Twice the skin gauge and 0.75 inch diameter.", "correct": false}, {"id": "c", "text": "One gauge depth and 0.75 inch diameter.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A light drive clearance between 3/4 inch diameter bolt and hole, on a drawing would be shown as', '[{"id": "a", "text": "0.005 Inches.", "correct": false}, {"id": "b", "text": "0.0015 Inches.", "correct": true}, {"id": "c", "text": "0.0025 Inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a front release connector the pin will be', '[{"id": "a", "text": "released from rear and extracted from the front.", "correct": false}, {"id": "b", "text": "released from the front and extracted from the front.", "correct": false}, {"id": "c", "text": "released from the front and extracted from the rear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A wire clamped vertically at one end and horizontally at the other end should have a bend radius of no less than', '[{"id": "a", "text": "3 times the diameter of the wire.", "correct": false}, {"id": "b", "text": "5 times the diameter of the wire.", "correct": true}, {"id": "c", "text": "10 times the diameter of the wire.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Glycol deicer fluid in contact with a silver cable can cause', '[{"id": "a", "text": "a fire.", "correct": true}, {"id": "b", "text": "disintegration of the cable insulation.", "correct": false}, {"id": "c", "text": "corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'With a rear release connector, the pin will be', '[{"id": "a", "text": "released from the front and extracted from the rear.", "correct": false}, {"id": "b", "text": "released from the rear and extracted from the front.", "correct": false}, {"id": "c", "text": "released from the rear and extracted from the rear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum operating temperature for a nickel plated copper or aluminium connector is', '[{"id": "a", "text": "135°C.", "correct": false}, {"id": "b", "text": "200°C.", "correct": false}, {"id": "c", "text": "260°C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What gauge of pin would a yellow plastic insert/extract tool be used on?', '[{"id": "a", "text": "16 - 14", "correct": false}, {"id": "b", "text": "12 - 10", "correct": true}, {"id": "c", "text": "22 - 18", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Can the insulation grip be adjusted on a PIDG crimp tool?', '[{"id": "a", "text": "No.", "correct": true}, {"id": "b", "text": "Yes by turning a knob.", "correct": false}, {"id": "c", "text": "Yes by adjusting the pins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What gauge of pin would a red plastic insert/extract tool be used on?', '[{"id": "a", "text": "12 - 10", "correct": false}, {"id": "b", "text": "22 - 18", "correct": true}, {"id": "c", "text": "16 - 14", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What cable would you use where temperatures are going to exceed 200°C?', '[{"id": "a", "text": "Tinned copper or aluminium.", "correct": false}, {"id": "b", "text": "Silver plated copper or aluminium.", "correct": false}, {"id": "c", "text": "Nickel plated copper or aluminium.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How long should a fireproof cable last in a fire?', '[{"id": "a", "text": "5 minutes", "correct": true}, {"id": "b", "text": "15 minutes", "correct": false}, {"id": "c", "text": "50 minutes", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What gauge of pin would a blue plastic insert / extract tool be used on?', '[{"id": "a", "text": "12 - 10", "correct": false}, {"id": "b", "text": "16 - 14", "correct": true}, {"id": "c", "text": "22 - 18", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The insulation resistance for wiring in undercarriage wheel-wells should normally be not less than', '[{"id": "a", "text": "2 megohms.", "correct": false}, {"id": "b", "text": "5 megohms.", "correct": true}, {"id": "c", "text": "10 megohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What causes knuckling on older type electrical cables?', '[{"id": "a", "text": "Over-temperature soldering.", "correct": false}, {"id": "b", "text": "Applying cable ties too tightly.", "correct": false}, {"id": "c", "text": "Excessive pull through forces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To find a high resistance or open circuit, carry out', '[{"id": "a", "text": "a milli-volt drop test.", "correct": true}, {"id": "b", "text": "a continuity check.", "correct": false}, {"id": "c", "text": "a bonding check.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum bonding resistance on an aircraft primary structure should be', '[{"id": "a", "text": "0.01 ohms.", "correct": false}, {"id": "b", "text": "0.001 ohms.", "correct": false}, {"id": "c", "text": "0.05 ohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Before effecting a crimp, the bare ends of a cable should be', '[{"id": "a", "text": "tightly twisted.", "correct": false}, {"id": "b", "text": "twisted lightly in the direction of the lay.", "correct": true}, {"id": "c", "text": "straightened out.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The number of the dots impressed on the insulation of the pre-insulated connectors during crimping indicates that', '[{"id": "a", "text": "the correct connector has been used.", "correct": false}, {"id": "b", "text": "the correct tool was used to effect the connection.", "correct": false}, {"id": "c", "text": "the crimp is properly formed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pressure of the insulation crimp jaws on the PIDG crimping tool can be changed by', '[{"id": "a", "text": "varying the torque applied to the handles.", "correct": false}, {"id": "b", "text": "using different coloured crimping pliers and terminations.", "correct": false}, {"id": "c", "text": "changing the position of the pins.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When referring to fuses, HRC means', '[{"id": "a", "text": "high rupture capacity.", "correct": true}, {"id": "b", "text": "hot running capacity.", "correct": false}, {"id": "c", "text": "high running current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When wiring an electrical component to a plug, the live wire is coloured', '[{"id": "a", "text": "blue.", "correct": false}, {"id": "b", "text": "green and yellow.", "correct": false}, {"id": "c", "text": "brown.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hole is placed in the lowest point of electrical cable conduit', '[{"id": "a", "text": "to allow for pull-through of the cables.", "correct": false}, {"id": "b", "text": "to secure the conduit to a piece of aircraft structure.", "correct": false}, {"id": "c", "text": "to allow for drainage of moisture.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The minimum distance between electrical cable splices is', '[{"id": "a", "text": "3 feet.", "correct": false}, {"id": "b", "text": "12 inches.", "correct": true}, {"id": "c", "text": "500 mm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A fire resistant cable is proof tested by exposure to a standard fire for', '[{"id": "a", "text": "5 minutes.", "correct": true}, {"id": "b", "text": "15 minutes.", "correct": false}, {"id": "c", "text": "30 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting coaxial cable connectors it is important to', '[{"id": "a", "text": "fit the correct lock nuts.", "correct": false}, {"id": "b", "text": "make sure the outer cup is fitted the correct way round.", "correct": false}, {"id": "c", "text": "not damage any seals fitted.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inserting pins into a front release connector the inserting tool should be used with the gap facing which direction?', '[{"id": "a", "text": "The centre of the connector.", "correct": true}, {"id": "b", "text": "Either direction.", "correct": false}, {"id": "c", "text": "The outside of the connector.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a hydraulic crimping tool, after completing the crimping operation, the crimp is formed when when', '[{"id": "a", "text": "the bypass valve opens and the ram returns to neutral.", "correct": false}, {"id": "b", "text": "the foot pedal force is at maximum.", "correct": false}, {"id": "c", "text": "the bypass valve closes and the ram returns to neutral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The type of binding tape used for cables in temperatures above 260°C is which of the following?', '[{"id": "a", "text": "Nomex", "correct": false}, {"id": "b", "text": "Teflon", "correct": true}, {"id": "c", "text": "Nylon", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the minimum bend radius of a loom adequately supported at a terminal block?', '[{"id": "a", "text": "10 * diameter", "correct": false}, {"id": "b", "text": "8 * diameter", "correct": false}, {"id": "c", "text": "3 * diameter", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How are front release pins removed?', '[{"id": "a", "text": "The tool is inserted from the front and the pin is removed from the front.", "correct": false}, {"id": "b", "text": "The tool is inserted from the rear and the pin Is removed from the front.", "correct": false}, {"id": "c", "text": "The tool is inserted from the front and the pin is removed from the rear.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a co-axial cable clamp is over tightened so as to compress the dielectric, how will the capacitance change?', '[{"id": "a", "text": "Stay the same.", "correct": false}, {"id": "b", "text": "Increase.", "correct": true}, {"id": "c", "text": "Decrease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the minimum bend radius of a single co-axial cable?', '[{"id": "a", "text": "6 * diameter.", "correct": false}, {"id": "b", "text": "8 * diameter.", "correct": true}, {"id": "c", "text": "10 * diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out millivolt drop checks on a circuit, what is an approximate guide for a correct reading?', '[{"id": "a", "text": "5 millivolts for every 10 amps flowing.", "correct": true}, {"id": "b", "text": "10 millivolts for every 5 amps flowing.", "correct": false}, {"id": "c", "text": "10 millivolts for every 15 amps flowing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a heat shrink gun, what should the temperature of the gun be set to?', '[{"id": "a", "text": "100° below the heat shrink temperature.", "correct": false}, {"id": "b", "text": "15° below the heat shrink temperature.", "correct": false}, {"id": "c", "text": "100° above the heat shrink temperature.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In an electrical cable 1EF6B22NMS, what does the letter E represent?', '[{"id": "a", "text": "Circuit function.", "correct": true}, {"id": "b", "text": "Cable size.", "correct": false}, {"id": "c", "text": "Segment letter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a coaxial cable, cable impedance is', '[{"id": "a", "text": "proportional to length.", "correct": false}, {"id": "b", "text": "not effected by length.", "correct": true}, {"id": "c", "text": "inversely proportional to length.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A secondary earth is', '[{"id": "a", "text": "not less than 0.5mm cross sectional area.", "correct": true}, {"id": "b", "text": "18 AWG.", "correct": false}, {"id": "c", "text": "22 AWG.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To prevent wet arc tracking', '[{"id": "a", "text": "cable grips should be tight.", "correct": false}, {"id": "b", "text": "ensure hot stamp printing is controlled.", "correct": true}, {"id": "c", "text": "cables should not be stretched.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When splicing a cable with a soldered joint, the operation is finished when', '[{"id": "a", "text": "the solder has melted.", "correct": false}, {"id": "b", "text": "the solder sleeve disappears.", "correct": false}, {"id": "c", "text": "the solder and insulation have formed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When manufacturing an electrical connector the unused holes are', '[{"id": "a", "text": "filled with connectors.", "correct": false}, {"id": "b", "text": "filled with connectors and blanked.", "correct": false}, {"id": "c", "text": "covered with blanks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Co-axial cable is preferred to airframe cable in which application?', '[{"id": "a", "text": "Where the diameter of cable is not important.", "correct": false}, {"id": "b", "text": "High frequency interference.", "correct": true}, {"id": "c", "text": "Low frequency interference.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Forward release electrical connectors are removed by the wire being', '[{"id": "a", "text": "pushed forwards.", "correct": false}, {"id": "b", "text": "twisted to the right.", "correct": false}, {"id": "c", "text": "pulled backwards.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When crimping wires, the wires should be', '[{"id": "a", "text": "straight.", "correct": false}, {"id": "b", "text": "lightly twisted.", "correct": true}, {"id": "c", "text": "twisted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why are copper wires used in electrical systems?', '[{"id": "a", "text": "They have high permeability.", "correct": false}, {"id": "b", "text": "They do not give off a magnetic field.", "correct": false}, {"id": "c", "text": "They have a low resistance to current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When crimping wires, the wire should', '[{"id": "a", "text": "be flush with the crimp.", "correct": true}, {"id": "b", "text": "extend 0.8 mm beyond the crimp.", "correct": false}, {"id": "c", "text": "be beneath the crimp.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), '1EF6B22 NMSV. What does the B mean?', '[{"id": "a", "text": "Segment letter.", "correct": true}, {"id": "b", "text": "Cable number.", "correct": false}, {"id": "c", "text": "Circuit function.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A white/blue insertion-extraction tool would be used on a cable of what size?', '[{"id": "a", "text": "10", "correct": false}, {"id": "b", "text": "16", "correct": false}, {"id": "c", "text": "22", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The value of the insulation resistance of an electric motor compared to its supply leads is', '[{"id": "a", "text": "greater.", "correct": false}, {"id": "b", "text": "same.", "correct": true}, {"id": "c", "text": "smaller.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When securing wire after it leaves an LRU, cable bundle bends should be not less than', '[{"id": "a", "text": "minimum radius of five times the outside diameter of the cable, or cable bundle.", "correct": true}, {"id": "b", "text": "minimum radius of three times the outside diameter of the cable, or cable bundle.", "correct": false}, {"id": "c", "text": "minimum radius of eight times the outside diameter of the cable, or cable bundle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When terminating an aluminium cable, what preparations would be carried out before crimping?', '[{"id": "a", "text": "Degrease stripped cable.", "correct": false}, {"id": "b", "text": "Just terminate.", "correct": false}, {"id": "c", "text": "Apply a mixture of 50% petroleum jelly and zinc oxide.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An in-line splice should be positioned on the', '[{"id": "a", "text": "terminal of the loom.", "correct": false}, {"id": "b", "text": "outside of the loom.", "correct": false}, {"id": "c", "text": "outer surface of the loom for easy inspection.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A conductor after being crimped. The maximum amount of conductor which protrudes from the terminal end should be', '[{"id": "a", "text": "1/32 inch", "correct": true}, {"id": "b", "text": "1/8 inch", "correct": false}, {"id": "c", "text": "1/16 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Two or more operations should be performed to strip wire with hand operated wire stripper if the total stripping length exceeds', '[{"id": "a", "text": "0.25 inch.", "correct": false}, {"id": "b", "text": "0.50 inch.", "correct": true}, {"id": "c", "text": "0.75 inch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A cable loom should be protected by conduit when fed through the', '[{"id": "a", "text": "main equipment centre.", "correct": false}, {"id": "b", "text": "wheelwell door.", "correct": true}, {"id": "c", "text": "cargo compartment ceiling.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The size of proper conduit for electrical wires must be', '[{"id": "a", "text": "25% larger than the maximum diameter of wires.", "correct": true}, {"id": "b", "text": "75% larger than the maximum diameter of wires.", "correct": false}, {"id": "c", "text": "100% larger than the average diameter of wires.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Blue metal extract tool would be used with contacts sized', '[{"id": "a", "text": "12.", "correct": false}, {"id": "b", "text": "16.", "correct": true}, {"id": "c", "text": "22.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Silver coated conductor in an unpresurised area is subject to moisture and has a damaged coating would be likely to cause', '[{"id": "a", "text": "Wet Arc Tracking.", "correct": false}, {"id": "b", "text": "Knuckling Through.", "correct": false}, {"id": "c", "text": "Red Plague.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When riveting, the distance from the edge to the rivet (land) should not be less than', '[{"id": "a", "text": "1D.", "correct": false}, {"id": "b", "text": "2D.", "correct": true}, {"id": "c", "text": "4D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The strength of a riveted joint compared to that of the original metal is', '[{"id": "a", "text": "75%.", "correct": true}, {"id": "b", "text": "100%.", "correct": false}, {"id": "c", "text": "125%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A repair has a double riveted joint. The shear strength would be', '[{"id": "a", "text": "75%.", "correct": false}, {"id": "b", "text": "100%.", "correct": true}, {"id": "c", "text": "125%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The standard minimum rivet row spacing is', '[{"id": "a", "text": "2 1/4 D.", "correct": true}, {"id": "b", "text": "3 D.", "correct": false}, {"id": "c", "text": "4 D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the normal spacing between rivets?', '[{"id": "a", "text": "2 D.", "correct": false}, {"id": "b", "text": "3 D.", "correct": true}, {"id": "c", "text": "4 D.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In British rivets (solid) what is the length grading unit?', '[{"id": "a", "text": "1/16", "correct": true}, {"id": "b", "text": "1/10", "correct": false}, {"id": "c", "text": "1/32", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the thickness of a single sheet of material, about to be joined by riveting was 1/16 of an inch thick what would be the approximate diameter of the rivets to be used?', '[{"id": "a", "text": "1/16 inch", "correct": false}, {"id": "b", "text": "3/16 inch", "correct": true}, {"id": "c", "text": "1/8 inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Regarding riveting, which of the following is correct?', '[{"id": "a", "text": "Both of the above are correct.", "correct": true}, {"id": "b", "text": "The length of a countersunk rivet (flush head) is measured from the end of the rivet to the top of the countersunk head.", "correct": false}, {"id": "c", "text": "The length of a round head or flat head is measured from the end of the rivet to underside of rivet head.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When riveting, a certain clearance must exist between the rivet and the hole in which it is fitted, to allow for shank expansion. If the clearance is too large, what could be the result?', '[{"id": "a", "text": "Indentations by rivet head on the material.", "correct": false}, {"id": "b", "text": "Separation of the sheets may occur.", "correct": false}, {"id": "c", "text": "Sheet may tend to buckle.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To replace one 1/8 inch rivet', '[{"id": "a", "text": "three 1/16 inch rivets would be required.", "correct": false}, {"id": "b", "text": "two 1/16 inch rivets would be required.", "correct": false}, {"id": "c", "text": "four 1/16 inch rivets would be required.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If treated rivets have not been used within the prescribed time they can be re-treated. What is the maximum number of times that they can be heat-treated?', '[{"id": "a", "text": "If no more in Stores, as many times as required.", "correct": false}, {"id": "b", "text": "Twice only.", "correct": true}, {"id": "c", "text": "Three times.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rivets kept at a temperature of between –15°C and –20°C are usable for', '[{"id": "a", "text": "150 days.", "correct": false}, {"id": "b", "text": "150 minutes.", "correct": false}, {"id": "c", "text": "150 hours.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Avdel rivets are closed by', '[{"id": "a", "text": "a broaching process.", "correct": false}, {"id": "b", "text": "a tapered mandrel.", "correct": true}, {"id": "c", "text": "a squeezing process.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of the Avdel pin tester?', '[{"id": "a", "text": "To test the tightness of the pin in the rivet.", "correct": true}, {"id": "b", "text": "To test the tightness of the rivet in the hole.", "correct": false}, {"id": "c", "text": "To test the shear strength of the pin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The stems of an Avdel rivet are', '[{"id": "a", "text": "removed with the riveting tool.", "correct": false}, {"id": "b", "text": "nipped off and milled flush with the head.", "correct": true}, {"id": "c", "text": "removed with a taper punch.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the pressure range for the Avdel Riveter Type F?', '[{"id": "a", "text": "40 to 60 lbs per sq. inch", "correct": false}, {"id": "b", "text": "60 to 80 lbs per sq. inch", "correct": true}, {"id": "c", "text": "20 to 60 lbs per sq. inch", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When countersinking rivet holes in a material', '[{"id": "a", "text": "a special countersinking bit with a pad to prevent drilling too deep should be used.", "correct": true}, {"id": "b", "text": "a plain countersinking bit should be used.", "correct": false}, {"id": "c", "text": "the rivet head should stand 1/32 of an inch above the surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The riveting defect in the figure shown is', '[{"id": "a", "text": "too much hammering.", "correct": false}, {"id": "b", "text": "the dolly was not square.", "correct": false}, {"id": "c", "text": "the snap was not square.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rivet allowance is', '[{"id": "a", "text": "the distance the rivet is positioned from the edge of the repair plate.", "correct": false}, {"id": "b", "text": "the amount of material required to form the rivet on installation.", "correct": true}, {"id": "c", "text": "the distance between rivets in the same row.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the approximate distance of the sphere of influence of a rivet?', '[{"id": "a", "text": "2D", "correct": false}, {"id": "b", "text": "4D", "correct": false}, {"id": "c", "text": "5D", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rivet clearance is', '[{"id": "a", "text": "the distance between rivets in the same row.", "correct": false}, {"id": "b", "text": "the amount that the rivet hole diameter exceeds the rivet diameter.", "correct": true}, {"id": "c", "text": "the distance between rows of rivets.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The minimum rivet pitch is', '[{"id": "a", "text": "2 1/2 * the rivet diameter.", "correct": false}, {"id": "b", "text": "3 * the rivet diameter.", "correct": true}, {"id": "c", "text": "2 * the rivet diameter.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The riveting defect in the figure shown is', '[{"id": "a", "text": "the snap was not square.", "correct": false}, {"id": "b", "text": "the hole was too small.", "correct": true}, {"id": "c", "text": "an incorrect snap has been used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The ‘grip’ of a rivet is', '[{"id": "a", "text": "the length of rivet left to form the head.", "correct": false}, {"id": "b", "text": "the thickness of plates which can be fastened.", "correct": true}, {"id": "c", "text": "the area of the plates held firmly together.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The strength of a riveted joint is determined by', '[{"id": "a", "text": "shear strength and pitch of rivet.", "correct": true}, {"id": "b", "text": "pitch and tensile strength of rivet.", "correct": false}, {"id": "c", "text": "shear strength of rivet and material it is made of.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the bearing strength of a metal is greater than the shear strength of the rivet, what will occur?', '[{"id": "a", "text": "Rivet will joggle.", "correct": false}, {"id": "b", "text": "Rivet will show incorrectly installed.", "correct": false}, {"id": "c", "text": "Rivet will pull through the metal.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a pressure test on a pipe it should be', '[{"id": "a", "text": "twice the working pressure for two minutes.", "correct": false}, {"id": "b", "text": "1.5 times the working pressure.", "correct": true}, {"id": "c", "text": "three times the working pressure for five minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking a hose after installation it should be checked for freedom of movement', '[{"id": "a", "text": "by flexing through the normal operating range plus 15°.", "correct": true}, {"id": "b", "text": "by flexing through the normal operating range only.", "correct": false}, {"id": "c", "text": "by flexing +/-15° either side of the neutral position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The three electrical checks carried out on aircraft are (1) continuity (2) bonding (3) insulation. What is the order in which they are executed?', '[{"id": "a", "text": "2-1-3", "correct": false}, {"id": "b", "text": "1-2-3", "correct": true}, {"id": "c", "text": "2-3-1", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the outer cover of a flexible hose is found to be cracked.', '[{"id": "a", "text": "It is unserviceable since it may have a restricted flow.", "correct": false}, {"id": "b", "text": "It may still be serviceable.", "correct": true}, {"id": "c", "text": "It is unserviceable since it may leak.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A rigid hydraulic pipe requires shaping. It should be carried out', '[{"id": "a", "text": "after annealing.", "correct": true}, {"id": "b", "text": "after age hardening.", "correct": false}, {"id": "c", "text": "as supplied.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Fretting corrosion on a braided pipe would mean it was', '[{"id": "a", "text": "unserviceable and should be replaced.", "correct": false}, {"id": "b", "text": "not necessarily unserviceable.", "correct": true}, {"id": "c", "text": "only unserviceable if the corrosion penetrates the braids.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Pipe flaring is carried out', '[{"id": "a", "text": "as supplied.", "correct": false}, {"id": "b", "text": "in the annealed state.", "correct": true}, {"id": "c", "text": "after normalizing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To allow for shrinkage, vibration and whip all straight hoses must be', '[{"id": "a", "text": "2% longer than the distance between the fittings.", "correct": false}, {"id": "b", "text": "3% longer than the distance between the fittings.", "correct": true}, {"id": "c", "text": "5% longer than the distance between the fittings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A flexible hose that cannot be internally inspected by eye or introscope can be ball tested by suspending from one end at a time to check', '[{"id": "a", "text": "a ball of 95% of bore of hose can be pushed through with a metal rod.", "correct": false}, {"id": "b", "text": "a ball of 98% of bore of end fittings passes freely under own weight.", "correct": true}, {"id": "c", "text": "a ball of 90% of bore of end fittings passes freely under own weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hoses are normally pressure tested to', '[{"id": "a", "text": "maximum working pressure.", "correct": false}, {"id": "b", "text": "2 times maximum working pressure.", "correct": true}, {"id": "c", "text": "1.5 times maximum working pressure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A fluid line marker with a skull & crossbones is', '[{"id": "a", "text": "fluid line carries toilet waste.", "correct": false}, {"id": "b", "text": "warning symbol.", "correct": true}, {"id": "c", "text": "radioactive symbol.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The international marking for a water injection pipeline is a series of', '[{"id": "a", "text": "chevrons.", "correct": true}, {"id": "b", "text": "squares.", "correct": false}, {"id": "c", "text": "dots.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The international marking for a fire protection pipe line is a series of', '[{"id": "a", "text": "circles.", "correct": true}, {"id": "b", "text": "squares.", "correct": false}, {"id": "c", "text": "diamonds.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To prevent corrosion where aluminium alloy pipelines are supported by rubber cleats, the pipe should be treated over the area of contact with', '[{"id": "a", "text": "french chalk.", "correct": false}, {"id": "b", "text": "varnish.", "correct": false}, {"id": "c", "text": "petroleum jelly.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The international marking for an instrument air pipe line is a', '[{"id": "a", "text": "series of dots.", "correct": false}, {"id": "b", "text": "zig zag line.", "correct": true}, {"id": "c", "text": "wavy band.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum distance between end fittings to which a straight hose assembly is to be connected is 50 inches. The minimum hose length should be', '[{"id": "a", "text": "51 inches.", "correct": true}, {"id": "b", "text": "51.5 inches.", "correct": false}, {"id": "c", "text": "3 inches.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The length of a hose assembly with elbowed end fittings is taken from', '[{"id": "a", "text": "the maximum length of the straight portion of hose.", "correct": false}, {"id": "b", "text": "the extreme overall length.", "correct": false}, {"id": "c", "text": "the centre of the bore at the nipple extremity.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The international marking for a breathing oxygen pipe line is a series of', '[{"id": "a", "text": "dots.", "correct": true}, {"id": "b", "text": "diamonds.", "correct": false}, {"id": "c", "text": "rectangles.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The resistance between a flexible hose and a component should not exceed', '[{"id": "a", "text": "0.05 ohm.", "correct": true}, {"id": "b", "text": "0.5 ohm.", "correct": false}, {"id": "c", "text": "1 ohm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bore tests of flexible hoses are carried out using a suitable ball or bobbin of', '[{"id": "a", "text": "25% of the diameter of the end fittings.", "correct": false}, {"id": "b", "text": "85% of the diameter of the end fittings.", "correct": true}, {"id": "c", "text": "90% of the diameter of the end fittings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aluminium alloy pipe used for hydraulics systems is flared', '[{"id": "a", "text": "normalized.", "correct": false}, {"id": "b", "text": "as supplied.", "correct": false}, {"id": "c", "text": "annealed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Identify the parts required to make up a flared-tube fitting?', '[{"id": "a", "text": "Sleeve and nut.", "correct": false}, {"id": "b", "text": "Ferrule and nut.", "correct": false}, {"id": "c", "text": "Body, sleeve and nut.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The flare angle on an AGS pipe is', '[{"id": "a", "text": "32 degrees.", "correct": true}, {"id": "b", "text": "45 degrees.", "correct": false}, {"id": "c", "text": "90 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Repair to aluminium pipe can be done using burnishing', '[{"id": "a", "text": "if damage is surface only.", "correct": true}, {"id": "b", "text": "if damage is no more than 5%.", "correct": false}, {"id": "c", "text": "if damage is no more than 10%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rigid pipes are designed with bends to', '[{"id": "a", "text": "allow for expansion and contraction due to heat and absorb vibration.", "correct": true}, {"id": "b", "text": "absorb vibration.", "correct": false}, {"id": "c", "text": "fit to the aircraft structure.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'You find a pipe with a flare end fitting of 74°. What specification has it been manufactured to?', '[{"id": "a", "text": "A.G.S.", "correct": false}, {"id": "b", "text": "S.A.E.", "correct": true}, {"id": "c", "text": "A.N.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bonding connections between flexible and rigid pipes are achieved by', '[{"id": "a", "text": "ti-wrapping the bonding lead to the pipes.", "correct": false}, {"id": "b", "text": "using a corrugated strip.", "correct": true}, {"id": "c", "text": "tucking the bonding leads between the flexible and rigid pipes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Springs are manufactured from', '[{"id": "a", "text": "high carbon alloy steel with high strength requirements.", "correct": true}, {"id": "b", "text": "low carbon alloy steel with high strength requirements.", "correct": false}, {"id": "c", "text": "high carbon alloy steel with low strength requirements.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A wear check on a cylinder head valve spring should include', '[{"id": "a", "text": "length under load.", "correct": false}, {"id": "b", "text": "diameter and length.", "correct": true}, {"id": "c", "text": "length off-load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Material used for springs is', '[{"id": "a", "text": "high carbon or alloy steel with low working stresses.", "correct": false}, {"id": "b", "text": "low carbon steel or alloy steel with high working stresses.", "correct": true}, {"id": "c", "text": "low carbon steel or alloy steel with low working stresses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Needle roller bearings', '[{"id": "a", "text": "are susceptible to brinelling.", "correct": false}, {"id": "b", "text": "can accept a small amount of misalignment.", "correct": true}, {"id": "c", "text": "are designed to carry axial loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When rotating a ball bearing by hand, a regular click indicates', '[{"id": "a", "text": "damage to the balls.", "correct": true}, {"id": "b", "text": "intergranular corrosion in the outer ring.", "correct": false}, {"id": "c", "text": "a cracked ring.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Brinelling of a wheel bearing could be caused by', '[{"id": "a", "text": "rotation of the outer race in the wheel housing.", "correct": false}, {"id": "b", "text": "heavy landing.", "correct": true}, {"id": "c", "text": "overheating of the brakes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Brinelling of a bearing is', '[{"id": "a", "text": "bluing of the bearing due to overheating.", "correct": false}, {"id": "b", "text": "shallow smooth depressions caused by the rollers being forced against the cup, due to overtorquing.", "correct": true}, {"id": "c", "text": "indentations in the race surface caused by continual static vibration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A tapered roller bearing is designed to take', '[{"id": "a", "text": "radial loads only.", "correct": false}, {"id": "b", "text": "both radial and axial loads.", "correct": true}, {"id": "c", "text": "axial loads only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Small indentations in the race of a ball bearing indicate', '[{"id": "a", "text": "overtorquing.", "correct": false}, {"id": "b", "text": "corrosion.", "correct": false}, {"id": "c", "text": "brinelling.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting a ball bearing to a shaft it should be carefully positioned using', '[{"id": "a", "text": "a steel drift with light blows.", "correct": false}, {"id": "b", "text": "a copper or aluminium tube drift.", "correct": false}, {"id": "c", "text": "a soft steel or brass tube drift.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Graphite prevents seizure and conducts heat. It is normally used in', '[{"id": "a", "text": "lithium based greases.", "correct": true}, {"id": "b", "text": "sodium based greases.", "correct": false}, {"id": "c", "text": "copper based greases.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'False Brinelling of a bearing is', '[{"id": "a", "text": "movement of the outer ring relative to its housing.", "correct": false}, {"id": "b", "text": "indentations on the race-way due to load transferred through the bearing when static.", "correct": true}, {"id": "c", "text": "a scoring of the race-way surfaces due to ball or roller skidding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On completion of assembly the bearing housing', '[{"id": "a", "text": "should be examined for end float.", "correct": false}, {"id": "b", "text": "packed fully with grease.", "correct": false}, {"id": "c", "text": "lightly packed with grease.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking a ball bearing for corrosion and foreign matter', '[{"id": "a", "text": "rotate at operational speed and check for roughness.", "correct": false}, {"id": "b", "text": "make a strip down inspection.", "correct": false}, {"id": "c", "text": "oscillate and rotate slowly to listen for roughness.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of load is a journal load?', '[{"id": "a", "text": "Radial", "correct": true}, {"id": "b", "text": "Axial", "correct": false}, {"id": "c", "text": "Centrifugal", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bearings to be cleaned for further examination should be wiped free of all grease on outer surfaces with the aid of dry compressed air for cages and rolling parts. The bearings should then be soaked in', '[{"id": "a", "text": "M.E.K.", "correct": false}, {"id": "b", "text": "lead free gasoline.", "correct": true}, {"id": "c", "text": "white spirit.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After cleaning a bearing should be dried with', '[{"id": "a", "text": "left in free air to dry naturally.", "correct": false}, {"id": "b", "text": "clean, warm, dry compressed air.", "correct": true}, {"id": "c", "text": "lint free rags.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Thrust bearings transmit', '[{"id": "a", "text": "thrust loads, thus limiting axial movement.", "correct": true}, {"id": "b", "text": "radial loads, thus limiting axial movement.", "correct": false}, {"id": "c", "text": "thrust loads, thus limiting radial movement.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Chipping of a ball bearing indicates', '[{"id": "a", "text": "brinelling.", "correct": false}, {"id": "b", "text": "chattering.", "correct": false}, {"id": "c", "text": "spalling.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Hardy Spicer coupling has what type of bearings?', '[{"id": "a", "text": "Ball Bearings.", "correct": false}, {"id": "b", "text": "Needle bearings.", "correct": true}, {"id": "c", "text": "Plain bearings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Graphite greases are used for', '[{"id": "a", "text": "medium temperature applications.", "correct": false}, {"id": "b", "text": "high temperature applications.", "correct": true}, {"id": "c", "text": "low temperature applications.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If during an engine overhaul, ball or roller bearings are found to have magnetised but otherwise have no defects, they', '[{"id": "a", "text": "are in an acceptable service condition.", "correct": false}, {"id": "b", "text": "must be degaussed before use.", "correct": true}, {"id": "c", "text": "cannot be used again.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Ball and roller bearings are made from a combination of low carbon steel and a percentage of', '[{"id": "a", "text": "chromium.", "correct": false}, {"id": "b", "text": "nickel.", "correct": false}, {"id": "c", "text": "nickel chrome.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On inspection a bearing is found to have distortion, what action should be taken?', '[{"id": "a", "text": "Reject bearing.", "correct": true}, {"id": "b", "text": "No action required. Some distortion is normal.", "correct": false}, {"id": "c", "text": "Blend out distortion and re-grease bearing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On inspection a bearing is found to show signs of overheating, what action should be taken?', '[{"id": "a", "text": "Reject bearing.", "correct": true}, {"id": "b", "text": "No action required. Some overheating is normal.", "correct": false}, {"id": "c", "text": "clean up bearing and repack with grease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a bearing has 2 parts and the inner ring and outer ring is installed', '[{"id": "a", "text": "neither of the practices are allowed.", "correct": false}, {"id": "b", "text": "the inner ring can be removed from its inner shaft for cleaning.", "correct": true}, {"id": "c", "text": "the outer ring can be removed from its housing for inspection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A chain removed for routine inspection, it', '[{"id": "a", "text": "does not need proof loading.", "correct": true}, {"id": "b", "text": "must be proof loaded to 50%.", "correct": false}, {"id": "c", "text": "must be proof loaded to 150%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft control chain is connected using', '[{"id": "a", "text": "nuts and bolts.", "correct": false}, {"id": "b", "text": "quick release pins.", "correct": false}, {"id": "c", "text": "a split link and spring clip.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a control chain can be lifted clear of a tooth, it should be', '[{"id": "a", "text": "rejected as unserviceable.", "correct": false}, {"id": "b", "text": "removed and an elongation check carried out.", "correct": true}, {"id": "c", "text": "cleaned, re-tensioned and inspected after a period of time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To check a chain for articulation', '[{"id": "a", "text": "it should be run over the finger through 180° and checked for smoothness and kinks.", "correct": true}, {"id": "b", "text": "move each link individually and check for tightness.", "correct": false}, {"id": "c", "text": "lay on a flat surface and check for kinks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you remove a tight link from a chain which is to be used on an aircraft control system?', '[{"id": "a", "text": "Dismantle, inspect, rectify and re-assemble the chain.", "correct": false}, {"id": "b", "text": "If the chain has a tight link, the chain has to be removed from service.", "correct": true}, {"id": "c", "text": "You may be able to remove the tight link by applying a light tap with a hammer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The initial lubricant on a new chain', '[{"id": "a", "text": "must be replaced with grade altitude grease.", "correct": false}, {"id": "b", "text": "should be removed and replaced with the approved oil.", "correct": false}, {"id": "c", "text": "should not be removed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Control chains should be fitted in an aircraft', '[{"id": "a", "text": "with the minimum of slack in the chain.", "correct": true}, {"id": "b", "text": "so that the chain can be removed easily.", "correct": false}, {"id": "c", "text": "with as much slack as possible to allow for contraction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Backlash is a type of wear associated with', '[{"id": "a", "text": "gears.", "correct": true}, {"id": "b", "text": "rivets.", "correct": false}, {"id": "c", "text": "bearings.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a chain has been cleaned in paraffin it should be', '[{"id": "a", "text": "hung up to drip dry.", "correct": false}, {"id": "b", "text": "dried in hot air.", "correct": true}, {"id": "c", "text": "washed in soapy water then hung to drip dry.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What fraction of the minimum breaking load should be the proof load for a chain?', '[{"id": "a", "text": "0.1", "correct": false}, {"id": "b", "text": "1/3", "correct": true}, {"id": "c", "text": "0.1%", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If corrosion is found on a chain', '[{"id": "a", "text": "replace the chain.", "correct": true}, {"id": "b", "text": "clean off the corrosion and if acceptable re-fit the chain.", "correct": false}, {"id": "c", "text": "lubricate the chain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The three principle dimensions specified for a chain is the diameter of the rollers and', '[{"id": "a", "text": "pitch and chain length.", "correct": false}, {"id": "b", "text": "the pitch and width between the inner plates.", "correct": true}, {"id": "c", "text": "the pitch and width across the outside of the plates.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The distance between the centres of the rollers of a chain is called', '[{"id": "a", "text": "pitch.", "correct": true}, {"id": "b", "text": "crest.", "correct": false}, {"id": "c", "text": "length.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following formulas should be used to calculate the percentage extension of an aircraft control chain? Note: M = Measured length under load in inches X = Number of pitches measured P = Pitch of chain in inches.', '[{"id": "a", "text": "M + (X * X) * 100 / P * M", "correct": false}, {"id": "b", "text": "X-(M * P) * 100 / M * P", "correct": false}, {"id": "c", "text": "M-(X * P) * 100 / X * P", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum allowable extension of a chain assembly over a nominal length is', '[{"id": "a", "text": "2%", "correct": true}, {"id": "b", "text": "3%", "correct": false}, {"id": "c", "text": "5%", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A feather key locates a gear on a shaft and permits', '[{"id": "a", "text": "a positive drive with the gear firmly locked.", "correct": false}, {"id": "b", "text": "a positive and strong drive transmission.", "correct": false}, {"id": "c", "text": "a positive drive and axial movement.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A chain is removed by', '[{"id": "a", "text": "nuts and bolts.", "correct": false}, {"id": "b", "text": "spring clips.", "correct": false}, {"id": "c", "text": "removing chain links on an endless chain.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The box unit in a Teleflex control run which is not suitable for heavily loaded controls is called', '[{"id": "a", "text": "Double entry.", "correct": false}, {"id": "b", "text": "Single entry.", "correct": true}, {"id": "c", "text": "Straight lead.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you check a chain for elongation?', '[{"id": "a", "text": "Hang chain up, check sight line and measure.", "correct": false}, {"id": "b", "text": "Adjust the end fittings.", "correct": false}, {"id": "c", "text": "Lay flat on a table, apply tensile load and measure.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Proof testing after cable installation is', '[{"id": "a", "text": "sometimes required.", "correct": true}, {"id": "b", "text": "not required.", "correct": false}, {"id": "c", "text": "always required.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A control cable that has been contaminated with acid should be', '[{"id": "a", "text": "cleaned.", "correct": false}, {"id": "b", "text": "rejected.", "correct": true}, {"id": "c", "text": "cleaned, inspected, and reinspected after a period of time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How would you use a Pacific T5 tensiometer?', '[{"id": "a", "text": "Use correct chart and correct riser.", "correct": true}, {"id": "b", "text": "Use a standard riser and use the chart to correct for different sized cables.", "correct": false}, {"id": "c", "text": "Use a load meter to apply the correct load.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of an aileron balance cable?', '[{"id": "a", "text": "Allows for hands off flying.", "correct": false}, {"id": "b", "text": "Equalizes control cable tension.", "correct": true}, {"id": "c", "text": "Relieves pilot loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How would you inspect a cable for fraying?', '[{"id": "a", "text": "Run your fingers the full length of the cable.", "correct": false}, {"id": "b", "text": "Operate the controls and feel for stiffness.", "correct": false}, {"id": "c", "text": "Run a rag the full length of the cable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When manufacturing aircraft control cables, the cable can be cut by', '[{"id": "a", "text": "using a hacksaw with the cable under tension.", "correct": false}, {"id": "b", "text": "using an oxy-acetylene torch.", "correct": false}, {"id": "c", "text": "using a chisel on a flat metal surface.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The check for a cable pulling out of a swaged fitting is by', '[{"id": "a", "text": "seeing that the cable is still past the safety holes in the swage.", "correct": true}, {"id": "b", "text": "looking for a shiny surface on the cable near the fitting.", "correct": false}, {"id": "c", "text": "seeing that there are no broken wires near the fitting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Large control cables (45 to 120 cwt) may have tension loads that can break the locking wire or lease lock nuts. How is this overcome?', '[{"id": "a", "text": "The cable is kept slightly slack.", "correct": false}, {"id": "b", "text": "Duplicating the number of cables to cut down on individual tensile loads.", "correct": false}, {"id": "c", "text": "A tube is fitted over the turnbuckle assembly and drilled to take up to 3 bolts, to prevent independent rotation", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To correctly tension cables it can help', '[{"id": "a", "text": "to use a cable with turnbuckles at least every eight feet.", "correct": false}, {"id": "b", "text": "to take up initial slack by additional pulleys.", "correct": false}, {"id": "c", "text": "to have control surface locks in to support weight and adjust turnbuckles equally.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A cable is replaced', '[{"id": "a", "text": "when a shiny portion is found.", "correct": false}, {"id": "b", "text": "when each strand is worn to limits.", "correct": false}, {"id": "c", "text": "if a chemical spillage is suspected.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the proof loading for cables after swaging?', '[{"id": "a", "text": "1/3 minimum breaking strain", "correct": false}, {"id": "b", "text": "2/3 minimum breaking strain", "correct": true}, {"id": "c", "text": "50% minimum breaking strain", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The best way to check control cables for broken wires is to', '[{"id": "a", "text": "run a rag along the cable in both directions.", "correct": true}, {"id": "b", "text": "examine them visually.", "correct": false}, {"id": "c", "text": "increase the tension and check with a magnifying glass.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the turnbuckles in a control system are tightened excessively the result will be', '[{"id": "a", "text": "the cable will break.", "correct": false}, {"id": "b", "text": "the cables will vibrate excessively and cause failure of controls.", "correct": false}, {"id": "c", "text": "the aircraft will be heavy on controls.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A control cable is proof loaded to ensure that', '[{"id": "a", "text": "the end fittings on the cable are secure.", "correct": false}, {"id": "b", "text": "it will not stretch after fitting in an aircraft.", "correct": true}, {"id": "c", "text": "it will not break after fitting in an aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'British turnbuckles are checked for safety by', '[{"id": "a", "text": "looking through the hole and checking for threads showing.", "correct": false}, {"id": "b", "text": "attempting to pass a hardened pin probe through the inspection hole.", "correct": true}, {"id": "c", "text": "attempting to push locking wire through the hole.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A suspected chemical spillage on a cable, you should', '[{"id": "a", "text": "clean, inspect and refit immediately.", "correct": false}, {"id": "b", "text": "replace the cable.", "correct": true}, {"id": "c", "text": "clean the cable and inspect 24 hours later.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'HTS aircraft control cables are protected from corrosion by', '[{"id": "a", "text": "Galvanising.", "correct": false}, {"id": "b", "text": "cadmium coating.", "correct": true}, {"id": "c", "text": "zinc plating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of the hole in the swaged end fitting on a swaged cable?', '[{"id": "a", "text": "To ensure the cable end passes the inspection hole on drilled through type fittings but leaves the locking wire", "correct": true}, {"id": "b", "text": "To allow trapped air to escape.", "correct": false}, {"id": "c", "text": "To allow a split pin to be inserted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The inspection hole in a turnbuckle is', '[{"id": "a", "text": "to allow the locking wire to pass through for the purpose of locking.", "correct": false}, {"id": "b", "text": "to ensure that the locknuts are adequately tightened.", "correct": true}, {"id": "c", "text": "to ensure that the turnbuckle is in safety.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Swaging of a cable end fitting is checked by', '[{"id": "a", "text": "measuring the length of the barrel before and after swaging.", "correct": false}, {"id": "b", "text": "using a go / no-go gauge on the barrel.", "correct": true}, {"id": "c", "text": "looking for cracks on the swage indicating poor swaging.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A flight control cable is replaced if', '[{"id": "a", "text": "single wires are blended together.", "correct": false}, {"id": "b", "text": "the protective fluid coating is missing.", "correct": false}, {"id": "c", "text": "a wire is 20% worn.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In aircraft control cables, when a lock is fitted to the control surface', '[{"id": "a", "text": "it will prevent the control surface movement but not the control column movement.", "correct": true}, {"id": "b", "text": "it will prevent the control surface and the control column movement.", "correct": false}, {"id": "c", "text": "it will not prevent the control surface movement but will lock the control column.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking cable tensions you are looking for', '[{"id": "a", "text": "free movement only.", "correct": false}, {"id": "b", "text": "full and free movement.", "correct": true}, {"id": "c", "text": "artificial feel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A cable should be replaced when individual wires are worn greater than', '[{"id": "a", "text": "40%.", "correct": false}, {"id": "b", "text": "60%.", "correct": true}, {"id": "c", "text": "20%.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The purpose of a joggle is', '[{"id": "a", "text": "to act as a tear stopper.", "correct": false}, {"id": "b", "text": "to make the holes for a rivet line up.", "correct": false}, {"id": "c", "text": "to produce a flush fit at a metal joint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Caustic soda applied to a metal turns black. This would indicate the metal is', '[{"id": "a", "text": "magnesium alloy.", "correct": true}, {"id": "b", "text": "duralumin.", "correct": false}, {"id": "c", "text": "aluminium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Removal of a scratch from a sheet of metal requires', '[{"id": "a", "text": "polishing.", "correct": false}, {"id": "b", "text": "blending.", "correct": true}, {"id": "c", "text": "burnishing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When dimpling a sheet of metal you would require', '[{"id": "a", "text": "an oversized rivet and special reaction block.", "correct": false}, {"id": "b", "text": "a male and female die.", "correct": true}, {"id": "c", "text": "a male die only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The skin on an aircraft is normally manufactured from', '[{"id": "a", "text": "2024 aluminium alloy.", "correct": true}, {"id": "b", "text": "7075 aluminium alloy.", "correct": false}, {"id": "c", "text": "2117 aluminium alloy.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The mold point is', '[{"id": "a", "text": "the mid point in the thickness of a sheet of metal to which the radius dimension is calculated.", "correct": true}, {"id": "b", "text": "the centre of curvature of a radiused corner in a metal fabricated component.", "correct": false}, {"id": "c", "text": "an imaginary point from which real base measurements are provided.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Relief holes are', '[{"id": "a", "text": "holes drilled in a battery container to provide drainage.", "correct": false}, {"id": "b", "text": "holes drilled in the corner of a metal box to prevent cracking.", "correct": true}, {"id": "c", "text": "holes drilled to stop a crack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Faying surfaces are', '[{"id": "a", "text": "surfaces that are in contact with each other.", "correct": true}, {"id": "b", "text": "surfaces that are stressed.", "correct": false}, {"id": "c", "text": "surfaces that have been treated with anti-corrosion compound.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In sheet metal bending, how would you measure the bend radius to calculate the bend allowance?', '[{"id": "a", "text": "Measure to the inside of the bend radius.", "correct": true}, {"id": "b", "text": "Measure to the outside of the bend radius.", "correct": false}, {"id": "c", "text": "Measure to the inside of the bend radius plus half the metal thickness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When dimpling sheet with a squeeze dimpling tool', '[{"id": "a", "text": "the jaws are not adjustable.", "correct": false}, {"id": "b", "text": "adjust the jaws to accommodate different material gauges.", "correct": true}, {"id": "c", "text": "use a lubricant.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bend radius on sheet metal is', '[{"id": "a", "text": "inside radius + 1/2 thickness.", "correct": false}, {"id": "b", "text": "inside radius.", "correct": true}, {"id": "c", "text": "outside radius.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Zinc Chromate applied between faying surfaces will', '[{"id": "a", "text": "improve adhesion thus relieving the amount of riveting necessary.", "correct": false}, {"id": "b", "text": "improve bonding between them.", "correct": false}, {"id": "c", "text": "inhibit dissimilar metal (electrolytic) corrosion.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a non-ferrous metal being examined by chemical test turns black when caustic soda is applied to the surface, the metal is', '[{"id": "a", "text": "duralumin.", "correct": false}, {"id": "b", "text": "alclad.", "correct": false}, {"id": "c", "text": "aluminium.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the maximum resistance between the main earth system and a metal plate on which the earthing device (tyre) is resting?', '[{"id": "a", "text": "10 megohms", "correct": false}, {"id": "b", "text": "1 megohm", "correct": true}, {"id": "c", "text": "100 megohms", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The sight line on a sheet metal flat layout to be bent in a cornice or box brake is measured and marked', '[{"id": "a", "text": "one-half radius from either bend tangent line.", "correct": false}, {"id": "b", "text": "one radius from the bend tangent line that is placed under the brake.", "correct": true}, {"id": "c", "text": "one radius from either bend tangent line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If copper sulphate is used on magnesium alloy it will', '[{"id": "a", "text": "effervesce to a copper colour.", "correct": false}, {"id": "b", "text": "have no effect.", "correct": true}, {"id": "c", "text": "effervesce to a black colour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If it is necessary to compute a bend allowance problem and bend allowance tables are not available, the neutral axis of the bend can be', '[{"id": "a", "text": "found by adding approximately one-half of the stock thickness to the bend radius.", "correct": true}, {"id": "b", "text": "found by subtracting the stock thickness from the bend radius.", "correct": false}, {"id": "c", "text": "represented by the actual length of the required material for the bend.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The formula for setback for a 90° bend is', '[{"id": "a", "text": "(1/2R + T).", "correct": false}, {"id": "b", "text": "(R + T).", "correct": true}, {"id": "c", "text": "(R + 1/2T).", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Caustic soda placed on the edge of alclad will turn', '[{"id": "a", "text": "white – black – white.", "correct": false}, {"id": "b", "text": "all white.", "correct": false}, {"id": "c", "text": "black – white – black.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In marking a light alloy', '[{"id": "a", "text": "the scriber must be held at an angle to give a smooth line where bending is required.", "correct": false}, {"id": "b", "text": "caustic soda is used.", "correct": false}, {"id": "c", "text": "a pencil is used to mark the material and all marks removed after bending.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When assembling metals of different potential, corrosion may be inhibited by application of', '[{"id": "a", "text": "zinc or chromic acid & assemble while wet.", "correct": false}, {"id": "b", "text": "zinc or barium chromate & assemble while wet.", "correct": true}, {"id": "c", "text": "nothing - assemble bare.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Steel wire brushes or steel wool should', '[{"id": "a", "text": "be used to clean magnesium alloys.", "correct": false}, {"id": "b", "text": "be used to clean aluminium sheet.", "correct": false}, {"id": "c", "text": "never be used on light alloys.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a piece of metal is bent, the surface of the metal on the outside of the bend is', '[{"id": "a", "text": "in compression.", "correct": false}, {"id": "b", "text": "neither in tension or in compression.", "correct": false}, {"id": "c", "text": "in tension.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The sight line of a bend is', '[{"id": "a", "text": "at the tangent line.", "correct": false}, {"id": "b", "text": "half a radius from the tangent line.", "correct": false}, {"id": "c", "text": "one radius from the tangent line.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The sharpest bend that can be placed in a piece of metal without critically weakening the part is called the', '[{"id": "a", "text": "maximum radius of bend.", "correct": false}, {"id": "b", "text": "minimum radius of bend.", "correct": true}, {"id": "c", "text": "bend allowance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Scribers are used to', '[{"id": "a", "text": "produce an accurate finish.", "correct": false}, {"id": "b", "text": "make centre pop marks for drilling.", "correct": false}, {"id": "c", "text": "mark guide lines on material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hole drilled at the intersection of two bends in a fabricated sheet metal component is called', '[{"id": "a", "text": "a drain hole.", "correct": false}, {"id": "b", "text": "a crack stopper.", "correct": false}, {"id": "c", "text": "a relief hole.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Dissimilar metal diffusion bonding gives', '[{"id": "a", "text": "high strength and ductility.", "correct": true}, {"id": "b", "text": "high strength and stiffness.", "correct": false}, {"id": "c", "text": "high strength and brittleness.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Marking out on stainless steel can be clarified by application of', '[{"id": "a", "text": "ammonia.", "correct": false}, {"id": "b", "text": "copper sulphate.", "correct": false}, {"id": "c", "text": "sal ammoniac.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When drawing lines on aluminium alloy sheet prior to bending', '[{"id": "a", "text": "a thin coat of zinc chromate primer should be used, ready for pencil lines.", "correct": false}, {"id": "b", "text": "a scriber should be used.", "correct": false}, {"id": "c", "text": "a wax pencil should be used.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After solution treatment of aluminium alloy, the effect of immediate refrigeration at a temperature with the range -15°C to -20°C is', '[{"id": "a", "text": "to suspend natural ageing for a limited period.", "correct": true}, {"id": "b", "text": "to permanently soften the metal to retard the onset of fatigue.", "correct": false}, {"id": "c", "text": "to increase the rate of artificial ageing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Diffusion bonding and superplastic forming provides', '[{"id": "a", "text": "high strength and high ductility.", "correct": true}, {"id": "b", "text": "high strength and high stiffness.", "correct": false}, {"id": "c", "text": "high stiffness and high ductility.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a composite repair lay-up, how much should each layer extend beyond the layer below it?', '[{"id": "a", "text": "2 - 3 inches", "correct": false}, {"id": "b", "text": "1 - 2 inches", "correct": true}, {"id": "c", "text": "3 - 4 inches", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To enable a composite panel to dissipate static charge it would be sprayed with', '[{"id": "a", "text": "polyurethane paint.", "correct": false}, {"id": "b", "text": "ferrous paint.", "correct": false}, {"id": "c", "text": "aluminium paint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A mechanic has completed a bonded honeycomb repair using the potted compound repair technique. What non-destructive testing method is used to determine the soundness of the repair after the repair has cured?', '[{"id": "a", "text": "Eddy current test.", "correct": false}, {"id": "b", "text": "Metallic ring test.", "correct": true}, {"id": "c", "text": "Ultrasonic test.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A non-destructive testing technique which is suitable for inspecting for delamination in Redux bonded structure of light aluminium alloys is', '[{"id": "a", "text": "ultrasonic.", "correct": true}, {"id": "b", "text": "eddy-current.", "correct": false}, {"id": "c", "text": "magnetic flow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is an extra layer of fibreglass added to a composite repair?', '[{"id": "a", "text": "To provide additional flexibility.", "correct": false}, {"id": "b", "text": "For sacrificial sanding.", "correct": true}, {"id": "c", "text": "To increase the strength of the repair.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you reduce or remove electrostatic charges which may build up on fibreglass surfaces?', '[{"id": "a", "text": "No special treatment is necessary because fibre glass is an insulator.", "correct": false}, {"id": "b", "text": "The surface is treated with a special conductive paint.", "correct": true}, {"id": "c", "text": "The surface is impregnated with copper strips.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Prior to aluminium alloy bonding we use', '[{"id": "a", "text": "alkaline etch.", "correct": false}, {"id": "b", "text": "acid etch.", "correct": true}, {"id": "c", "text": "solvent wipe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Glass reinforced panels are bonded by', '[{"id": "a", "text": "special conductive paint.", "correct": false}, {"id": "b", "text": "wire mesh.", "correct": false}, {"id": "c", "text": "bonding strips to conductors.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What solvents could you use to clean tools used for fibreglass repairs?', '[{"id": "a", "text": "Trichloroethylene or acetone.", "correct": false}, {"id": "b", "text": "Lead free petrol/kerosene.", "correct": false}, {"id": "c", "text": "acetone or MEK.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Chopped strand mat is a good general purpose mat because', '[{"id": "a", "text": "it has short fibres.", "correct": false}, {"id": "b", "text": "it gives equal properties in all directions.", "correct": true}, {"id": "c", "text": "it is a stiffer than woven cloth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Before soldering stainless steel it must be', '[{"id": "a", "text": "pickled.", "correct": true}, {"id": "b", "text": "cleaned with emery cloth.", "correct": false}, {"id": "c", "text": "sand papered.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Insufficient heat used in soldering will cause', '[{"id": "a", "text": "the joint to oxidize.", "correct": false}, {"id": "b", "text": "a high resistance joint potential.", "correct": true}, {"id": "c", "text": "contamination of the joint.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A dry joint when soldering is caused by', '[{"id": "a", "text": "too much flux.", "correct": false}, {"id": "b", "text": "too large an iron.", "correct": false}, {"id": "c", "text": "too little heat.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The oxyacetylene flame for silver soldering should be', '[{"id": "a", "text": "oxidizing.", "correct": false}, {"id": "b", "text": "carbonising.", "correct": false}, {"id": "c", "text": "neutral.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A flux is used in soldering to', '[{"id": "a", "text": "to dissolve oxides.", "correct": true}, {"id": "b", "text": "etch the metals surface for more adhesion.", "correct": false}, {"id": "c", "text": "to prevent solder spikes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Plumbers solder is grade', '[{"id": "a", "text": "B.", "correct": false}, {"id": "b", "text": "C.", "correct": false}, {"id": "c", "text": "D.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is it necessary to use flux in all silver soldering operations?', '[{"id": "a", "text": "To increase heat conductivity.", "correct": false}, {"id": "b", "text": "To prevent overheating of the base metal.", "correct": false}, {"id": "c", "text": "To chemically clean the base metal of oxide film.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When making a small soldered electrical connection, using flux-cored solder', '[{"id": "a", "text": "the connection should be heated first and then solder applied.", "correct": false}, {"id": "b", "text": "the soldering iron and solder should be applied simultaneously to the connection.", "correct": true}, {"id": "c", "text": "the soldering iron should be loaded with solder and then applied to the connection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The type of flux to be used when soft soldering on aircraft is', '[{"id": "a", "text": "active.", "correct": false}, {"id": "b", "text": "non-active.", "correct": true}, {"id": "c", "text": "either active or non-active.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The operational temperature of soldering irons is', '[{"id": "a", "text": "fjust above the melting point of solder.", "correct": false}, {"id": "b", "text": "below the melting point of the base metal.", "correct": false}, {"id": "c", "text": "60°C above the melting point of solder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What elements is solder made from?', '[{"id": "a", "text": "Tin, lead and copper.", "correct": false}, {"id": "b", "text": "Tin and lead only.", "correct": true}, {"id": "c", "text": "Tin, lead and silver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'General purpose solders are graded by', '[{"id": "a", "text": "a colour coding.", "correct": false}, {"id": "b", "text": "a letter coding.", "correct": true}, {"id": "c", "text": "a numerical coding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What solder should be used to solder aluminium?', '[{"id": "a", "text": "D.T.D. 685 lead-silver-tin solder.", "correct": true}, {"id": "b", "text": "90% tin and 10% zinc.", "correct": false}, {"id": "c", "text": "wire flux cored solder.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Solder can be used to join', '[{"id": "a", "text": "some dissimilar metals.", "correct": true}, {"id": "b", "text": "only copper based metals.", "correct": false}, {"id": "c", "text": "similar metals only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A flux is used in soldering to', '[{"id": "a", "text": "dissolve oxides.", "correct": true}, {"id": "b", "text": "prevent solder spikes.", "correct": false}, {"id": "c", "text": "etch the metal surface for more adhesion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On completion of soldering a non-activated flux', '[{"id": "a", "text": "must be cleaned off with an acid solution.", "correct": false}, {"id": "b", "text": "need not be cleaned off.", "correct": true}, {"id": "c", "text": "must be cleaned off with a selected solvent.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A dry joint in soldering is most likely to be caused by', '[{"id": "a", "text": "flux not used.", "correct": false}, {"id": "b", "text": "components not hot enough.", "correct": true}, {"id": "c", "text": "wrong solder used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What action is taken when soldering flux residue may have lodged in deep crevices of an assembly?', '[{"id": "a", "text": "It must be immersed in a weak solution of hydrochloric acid and rinsed thoroughly in running water.", "correct": false}, {"id": "b", "text": "It must be immersed in a weak solution of phosphoric acid and rinsed in water.", "correct": true}, {"id": "c", "text": "It must be thoroughly rinsed with a weak solution of sulphuric acid and washed in cold water.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A phosphate based flux paste is for soldering', '[{"id": "a", "text": "aluminium.", "correct": true}, {"id": "b", "text": "brass.", "correct": false}, {"id": "c", "text": "stainless steel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The soldering method where molten solder is pumped from the bottom of a bath through a slot so that a stationary wave of solder appears on the surface is known as the', '[{"id": "a", "text": "rotary bath method.", "correct": false}, {"id": "b", "text": "stationary wave method.", "correct": false}, {"id": "c", "text": "standing wave bath method.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Solders are available in two forms:', '[{"id": "a", "text": "stick solder with a rosin core and solder in a wire form having a rosin core.", "correct": false}, {"id": "b", "text": "solder in a wire form needing a separate flux and stick solder needing no flux at all.", "correct": false}, {"id": "c", "text": "stick solder needing a separate flux and solder in wire form having a rosin core.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A resurfaced soldering iron cannot be used effectively until after the working face has been', '[{"id": "a", "text": "fluxed.", "correct": false}, {"id": "b", "text": "polished.", "correct": false}, {"id": "c", "text": "tinned.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'High temperature solder is used where the operating temperature is high. It is an alloy of', '[{"id": "a", "text": "lead / copper / antimony.", "correct": false}, {"id": "b", "text": "tin / zinc / antimony / silver.", "correct": false}, {"id": "c", "text": "tin / lead / antimony / silver.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Soft solder is suited for joints, which are', '[{"id": "a", "text": "subjected to fatigue.", "correct": false}, {"id": "b", "text": "subjected to strong forces.", "correct": false}, {"id": "c", "text": "subjected to small forces.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Silver solder melts within the range', '[{"id": "a", "text": "400°C - 550°C.", "correct": false}, {"id": "b", "text": "200°C - 400°C.", "correct": false}, {"id": "c", "text": "600°C - 850°C.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Silver soldering is suited for', '[{"id": "a", "text": "electronic component soldering.", "correct": false}, {"id": "b", "text": "high temperature applications.", "correct": true}, {"id": "c", "text": "general soldering work.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Silver solder is made from', '[{"id": "a", "text": "tin, copper and zinc.", "correct": false}, {"id": "b", "text": "copper, tin and silver.", "correct": true}, {"id": "c", "text": "copper, zinc and silver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The materials most commonly soldered in soft soldering are', '[{"id": "a", "text": "brass and mild steel.", "correct": true}, {"id": "b", "text": "stainless steel and titanium.", "correct": false}, {"id": "c", "text": "aluminium and magnesium.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What purpose does flux serve in welding aluminium?', '[{"id": "a", "text": "Ensures proper distribution of the filler rod.", "correct": false}, {"id": "b", "text": "Removes dirt, grease, and oil.", "correct": false}, {"id": "c", "text": "Minimises or prevents oxidation.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The shielding gases generally used in the Tungsten Inert Gas (TIG) welding of aluminium consist of', '[{"id": "a", "text": "nitrogen or hydrogen, or a mixture of nitrogen and hydrogen.", "correct": false}, {"id": "b", "text": "a mixture of nitrogen and carbon dioxide.", "correct": false}, {"id": "c", "text": "helium or argon, or a mixture of helium and argon.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which items listed below is the most important consideration when selecting a welding rod?', '[{"id": "a", "text": "Thickness of the metal to be welded only.", "correct": false}, {"id": "b", "text": "Type of torch.", "correct": false}, {"id": "c", "text": "Type and thickness of the metal to be welded.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is a good weld?', '[{"id": "a", "text": "Build up by 1/8 inch in the middle of the weld.", "correct": false}, {"id": "b", "text": "An oxide coating on the base metals.", "correct": false}, {"id": "c", "text": "Sides sloping to the base metals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Brazing material is made from', '[{"id": "a", "text": "copper zinc and silver.", "correct": true}, {"id": "b", "text": "copper and tin and lead.", "correct": false}, {"id": "c", "text": "copper, silver and tin.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Filing or grinding a weld bead', '[{"id": "a", "text": "may be necessary to avoid adding excess weight or to achieve uniform material thickness.", "correct": true}, {"id": "b", "text": "may be performed to achieve a smoother surface.", "correct": false}, {"id": "c", "text": "reduces the strength of the joint.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The primary reason for using flux when welding aluminium is to', '[{"id": "a", "text": "prevent oxides from forming ahead of the weld.", "correct": true}, {"id": "b", "text": "prevent molten metal from flowing too widely.", "correct": false}, {"id": "c", "text": "promote better fusion of the base metal at a lower temperature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In Gas Tungsten Arc (GTA) welding, a stream of inert gas is used to', '[{"id": "a", "text": "lower the temperature required to properly fuse the metal.", "correct": false}, {"id": "b", "text": "prevent the formation of oxides in the puddle.", "correct": true}, {"id": "c", "text": "concentrate the heat of the arc and prevent its dissipation.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After welding you would normalise to', '[{"id": "a", "text": "remove oxidation from the welded joint.", "correct": false}, {"id": "b", "text": "remove carbon build up from the welded joint.", "correct": false}, {"id": "c", "text": "release the stresses from the material.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The flux used during brazing is a mixture of water and', '[{"id": "a", "text": "zinc chloride.", "correct": false}, {"id": "b", "text": "hydrochloric acid.", "correct": false}, {"id": "c", "text": "borax powder.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Oxides form very rapidly when alloys or metals are hot. It is important, therefore, when welding aluminium to use a', '[{"id": "a", "text": "solvent.", "correct": false}, {"id": "b", "text": "filler.", "correct": false}, {"id": "c", "text": "flux.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which statement concerning a welding process is true?', '[{"id": "a", "text": "In the oxyacetylene welding process, the filler rod used for steel is covered with a thin coating of flux.", "correct": false}, {"id": "b", "text": "In the metallic-arc welding process, filler material, if needed, is provided by a separate metal rod of the proper material", "correct": false}, {"id": "c", "text": "The inert-arc welding process uses an inert gas to protect the weld zone from the atmosphere.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inspecting a butt-welded joint by visual means', '[{"id": "a", "text": "the penetration should be 100 percent of the thickness of the base metal.", "correct": true}, {"id": "b", "text": "the penetration should be 25 to 50 percent of the thickness of the base metal.", "correct": false}, {"id": "c", "text": "look for evidence of excessive heat in the form of a very high bead.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is undesirable in a good weld?', '[{"id": "a", "text": "Oxides mixed in with the filler material.", "correct": true}, {"id": "b", "text": "Fusing the edges of materials to be joined.", "correct": false}, {"id": "c", "text": "100% penetration by filler material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In selecting a torch tip size to use in welding, the size of the tip opening determines the', '[{"id": "a", "text": "temperature of the flame.", "correct": false}, {"id": "b", "text": "melting point of the filler metal.", "correct": false}, {"id": "c", "text": "amount of heat applied to the work.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The most important consideration(s) when selecting welding rod is/are', '[{"id": "a", "text": "material compatibility.", "correct": true}, {"id": "b", "text": "current setting or flame temperature.", "correct": false}, {"id": "c", "text": "ambient conditions.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inspecting a weld, you should make sure that', '[{"id": "a", "text": "the parent (or basis) materials are fully fused together.", "correct": true}, {"id": "b", "text": "the weld has inclusions inside the bead.", "correct": false}, {"id": "c", "text": "there are voids either side of the weld.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Fore and aft limits of the CG', '[{"id": "a", "text": "are determined by the pilot when calculating the loading data.", "correct": false}, {"id": "b", "text": "are specified by the manufacturer.", "correct": true}, {"id": "c", "text": "are determined by the licensed engineer after a major check and weighing.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What angle of turn will double the weight of the aircraft?', '[{"id": "a", "text": "30°", "correct": false}, {"id": "b", "text": "45°", "correct": false}, {"id": "c", "text": "60°", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The basic equipment of an aircraft is', '[{"id": "a", "text": "that equipment which is required for every role of the aircraft for which the aircraft is operated plus unusable", "correct": true}, {"id": "b", "text": "all equipment including fuel and oil necessary for a particular flight.", "correct": false}, {"id": "c", "text": "the crew equipment, and other equipment including fuel and oil necessary for a particular flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aircraft measurements aft of the datum are', '[{"id": "a", "text": "either positive or negative.", "correct": false}, {"id": "b", "text": "positive.", "correct": false}, {"id": "c", "text": "negative.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Weight and Centre of Gravity Schedule is required by', '[{"id": "a", "text": "all aircraft above 2730 kg MTWA.", "correct": true}, {"id": "b", "text": "all aircraft not exceeding 2730 kg MTWA.", "correct": false}, {"id": "c", "text": "all aircraft regardless of weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aircraft below 5700kg not used for commercial air transport purposes are required to be reweighed', '[{"id": "a", "text": "every 2 years.", "correct": false}, {"id": "b", "text": "every 5 years.", "correct": false}, {"id": "c", "text": "as required by the CAA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Variable load is weight of', '[{"id": "a", "text": "crew, their baggage and equipment relevant to role.", "correct": true}, {"id": "b", "text": "fuel, oil and non-expendable equipment relevant to role.", "correct": false}, {"id": "c", "text": "basic weight plus operating weight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aircraft must be reweighed', '[{"id": "a", "text": "after two years from manufacture only.", "correct": false}, {"id": "b", "text": "after two years from manufacture then at periods not exceeding five years.", "correct": true}, {"id": "c", "text": "at periods not exceeding five years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'For purposes of calculating weight and C of G position, an adult male (with baggage) is considered to have a mass of', '[{"id": "a", "text": "85 kg.", "correct": false}, {"id": "b", "text": "65 kg.", "correct": false}, {"id": "c", "text": "75 kg.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Points forward of the datum point are', '[{"id": "a", "text": "negative.", "correct": true}, {"id": "b", "text": "neutral.", "correct": false}, {"id": "c", "text": "positive.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Where would you find documented, the fore and aft limits of the C of G position?', '[{"id": "a", "text": "In the aircraft Maintenance Manual.", "correct": false}, {"id": "b", "text": "In the Flight Manual (or the documentation associated with the C of A).", "correct": true}, {"id": "c", "text": "In the technical log.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Previous weighing records are', '[{"id": "a", "text": "retained for 2 yrs only.", "correct": false}, {"id": "b", "text": "are kept with aircraft records.", "correct": true}, {"id": "c", "text": "destroyed after 5 yrs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Load Sheet is compiled in the order of', '[{"id": "a", "text": "Variable Load, Fuel Load, Disposable Load, Basic Weight.", "correct": false}, {"id": "b", "text": "Basic Weight, Variable Load, Disposable Load, Fuel Load.", "correct": false}, {"id": "c", "text": "Basic Weight, Variable Load, Fuel Load, Disposable Load.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Weight and Centre of Gravity Schedule must be signed by', '[{"id": "a", "text": "the CAA.", "correct": false}, {"id": "b", "text": "the pilot.", "correct": false}, {"id": "c", "text": "a Licensed aircraft engineer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft which has its C of G forward of the Forward Limit', '[{"id": "a", "text": "the take-off run will not be affected.", "correct": false}, {"id": "b", "text": "will have a longer take-off run.", "correct": true}, {"id": "c", "text": "will have a shorter take-off run.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The basic weight of an aircraft is', '[{"id": "a", "text": "the pilot, flight crew and their luggage.", "correct": false}, {"id": "b", "text": "the passengers, baggage and fuel.", "correct": false}, {"id": "c", "text": "the aircraft, minimum equipment, unusable fuel and oil.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When an aircraft has been reweighed under EU OPS, what should be done to the old Weight and Balance Report?', '[{"id": "a", "text": "Kept in the aircraft logbook.", "correct": false}, {"id": "b", "text": "Destroyed after 3 months.", "correct": false}, {"id": "c", "text": "Kept in the weight and balance schedule.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the C of G of an aircraft with a full complement of fuel is calculated. Then', '[{"id": "a", "text": "the C of G will always be within limits if it was within limits with full fuel tanks.", "correct": false}, {"id": "b", "text": "the C of G must be recalculated with zero fuel to ensure it will still be within limits.", "correct": true}, {"id": "c", "text": "the C of G will only need to be recalculated if the fuel weight is behind the aircraft C of G position.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Cargo placed aft of the datum will produce a', '[{"id": "a", "text": "neutral moment.", "correct": false}, {"id": "b", "text": "negative moment.", "correct": false}, {"id": "c", "text": "positive moment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A load sheet', '[{"id": "a", "text": "need not be carried on the aircraft if one remains at base.", "correct": false}, {"id": "b", "text": "is always carried on the aircraft.", "correct": true}, {"id": "c", "text": "is never carried on the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The Datum point on an aircraft, for measuring C of G position could be', '[{"id": "a", "text": "the front bulkhead.", "correct": false}, {"id": "b", "text": "anywhere on the aircraft.", "correct": true}, {"id": "c", "text": "the nose of the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Increasing the weight of an aircraft', '[{"id": "a", "text": "increases the glide range.", "correct": false}, {"id": "b", "text": "has no affect on the glide range.", "correct": false}, {"id": "c", "text": "decreases the glide range.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A load Sheet must be signed by', '[{"id": "a", "text": "a licensed aircraft engineer.", "correct": false}, {"id": "b", "text": "the Commander of the aircraft.", "correct": true}, {"id": "c", "text": "the Loading Officer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is meant by empty weight?', '[{"id": "a", "text": "Basic weight only.", "correct": true}, {"id": "b", "text": "Basic weight minus unusable fuel plus oil.", "correct": false}, {"id": "c", "text": "Basic weight plus unusable fuel plus oil.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Weight and Centre of Gravity Schedule is to be raised', '[{"id": "a", "text": "in triplicate, for the CAA, the operator and the maintenance organisation.", "correct": true}, {"id": "b", "text": "in duplicate, for the CAA and the operator.", "correct": false}, {"id": "c", "text": "once only, for the CAA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Where would you find the information on the conditions for weighing the aircraft?', '[{"id": "a", "text": "Maintenance Manual.", "correct": false}, {"id": "b", "text": "Technical Log.", "correct": false}, {"id": "c", "text": "Flight Manual in conjunction with the documents associated with the CofA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In aeronautical weighing terms', '[{"id": "a", "text": "all arms for forward of the reference datum are positive (+) and all arms aft of the reference datum are negative (-).", "correct": false}, {"id": "b", "text": "all reference datum are as per company procedures.", "correct": false}, {"id": "c", "text": "all arms for forward of the reference datum are negative (-) and all arms aft of the reference datum are positive", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Details on recording of weight and C of G position can be found in', '[{"id": "a", "text": "BCAR section A.", "correct": true}, {"id": "b", "text": "Air Navigation Order.", "correct": false}, {"id": "c", "text": "Airworthiness Notices.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If a new Weight and Centre of Gravity Schedule is issued, the old one must be retained for', '[{"id": "a", "text": "one year.", "correct": false}, {"id": "b", "text": "two years.", "correct": true}, {"id": "c", "text": "six months.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A weighing cell is based on the variation of', '[{"id": "a", "text": "induced voltage with displacement.", "correct": false}, {"id": "b", "text": "resistance with strain.", "correct": true}, {"id": "c", "text": "differential currents with stress.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When weighing an aircraft using elastic load cells, the load cells go', '[{"id": "a", "text": "as a single unit or combination of units under the aircraft wheels.", "correct": true}, {"id": "b", "text": "between undercarriage and aircraft.", "correct": false}, {"id": "c", "text": "between top of jack and the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When weighing an aircraft with load cells', '[{"id": "a", "text": "only the main wheels are weighed.", "correct": false}, {"id": "b", "text": "the aircraft is jacked.", "correct": true}, {"id": "c", "text": "a load cell should be placed under each set of wheels.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When weighing an aircraft, the hydrostatic weighing units are positioned', '[{"id": "a", "text": "either under or on top of each jack.", "correct": true}, {"id": "b", "text": "one under each jack.", "correct": false}, {"id": "c", "text": "one on top of each jack.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When weighing an aircraft by the weighbridge method, the aircraft is', '[{"id": "a", "text": "only levelled laterally.", "correct": false}, {"id": "b", "text": "jacked and levelled.", "correct": false}, {"id": "c", "text": "resting on the wheels.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When mooring an aircraft what type of rope should be used?', '[{"id": "a", "text": "Nylon.", "correct": false}, {"id": "b", "text": "Fibre, tied tight due to stretch when wet.", "correct": false}, {"id": "c", "text": "Fibre, with some slack due to shrinkage when wet.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Removal of ice by the use of deicing fluid on the aircraft, before flight', '[{"id": "a", "text": "must be 1 hour before flight to enable fluid to be cleaned from aircraft.", "correct": false}, {"id": "b", "text": "will provide sufficient prevention of ice formation until take off.", "correct": false}, {"id": "c", "text": "may remove ice for a period of time depending on the airfield conditions.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When deicing an aircraft with pressure deicing fluid, the sensors on the outside of the aircraft should', '[{"id": "a", "text": "have their heating switched on.", "correct": false}, {"id": "b", "text": "be fitted with blanks or bungs.", "correct": true}, {"id": "c", "text": "not be blanked.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When Ground Power is connected to aircraft, the generators are', '[{"id": "a", "text": "paralleled to supply.", "correct": false}, {"id": "b", "text": "paralleled to supply for ground starting only.", "correct": false}, {"id": "c", "text": "never paralleled.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If ice and snow is found on the wings of an aircraft. Before flight the', '[{"id": "a", "text": "snow should be removed but ice can remain because it has no appreciable affect on the airflow.", "correct": false}, {"id": "b", "text": "all snow and ice must be removed.", "correct": true}, {"id": "c", "text": "ice should be removed but snow can remain because the airflow will remove it.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'There is ice and snow on a helicopter blade. You', '[{"id": "a", "text": "wipe off excess snow and leave ice.", "correct": false}, {"id": "b", "text": "leave a layer of ice.", "correct": false}, {"id": "c", "text": "remove all traces of ice and snow.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is the last part of towing an aircraft, done in a straight line?', '[{"id": "a", "text": "To relieve side pressure from the main wheels.", "correct": true}, {"id": "b", "text": "To relieve hydraulic pressure from the steering mechanism.", "correct": false}, {"id": "c", "text": "To allow nose wheel chocks to be placed at 90 degrees to the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Aluminium clad alloy sheet should not be polished with mechanical buffing wheels as this', '[{"id": "a", "text": "will cause large static charges to build up.", "correct": false}, {"id": "b", "text": "may remove the aluminium coating.", "correct": true}, {"id": "c", "text": "may remove the alloy coating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft should be cleared of snow', '[{"id": "a", "text": "using air blast.", "correct": false}, {"id": "b", "text": "using cold fluid.", "correct": false}, {"id": "c", "text": "using hot fluid.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When refueling an aircraft from a tanker, why are the aircraft and tanker bonded together?', '[{"id": "a", "text": "To discharge static electricity from the aircraft to the tanker.", "correct": false}, {"id": "b", "text": "To maintain the aircraft and tanker at the same electrical potential.", "correct": true}, {"id": "c", "text": "To enable the aircraft re-fuel pumps to be operated from the tanker electrical supply.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When turning and towing an aircraft, why should sharp radiuses be avoided?', '[{"id": "a", "text": "Power steering leaks could occur.", "correct": false}, {"id": "b", "text": "Scrubbing of main-wheel tyres could occur.", "correct": true}, {"id": "c", "text": "Scrubbing of nose-wheel tyres could occur.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When an aircraft is pulled out of soft ground, the equipment should be attached to', '[{"id": "a", "text": "the tail cone.", "correct": false}, {"id": "b", "text": "the main gear.", "correct": true}, {"id": "c", "text": "the nose gear.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When a helicopter lands, how does the pilot signal to ground staff when it is safe to approach the aircraft?', '[{"id": "a", "text": "Turn the anti collision lights off.", "correct": false}, {"id": "b", "text": "Flash the landing lights.", "correct": true}, {"id": "c", "text": "Flash the Nav lights.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When the park brake has been applied on an aircraft which has a pressurized hydraulic system and is reading maximum system pressure, the brake gauges to the left and right main wheels will read', '[{"id": "a", "text": "no indication.", "correct": false}, {"id": "b", "text": "full system pressure.", "correct": true}, {"id": "c", "text": "full scale deflection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'De-icing fluid Type 1 is used', '[{"id": "a", "text": "for short holdover times.", "correct": true}, {"id": "b", "text": "where the ambient temperature is below -10degrees Centigrade.", "correct": false}, {"id": "c", "text": "where holdover times are long.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When picketing a helicopter you', '[{"id": "a", "text": "tie down one blade.", "correct": false}, {"id": "b", "text": "fit sleeves to the blades to protect them if they strike the ground.", "correct": false}, {"id": "c", "text": "fit sleeves and tie off all blades.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which is bad practice for removing the ice and snow in the cold weather?', '[{"id": "a", "text": "Dry snow by hot air.", "correct": true}, {"id": "b", "text": "Deep ice by de-icing fluid.", "correct": false}, {"id": "c", "text": "Use brush for deep wet snow.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Taper pins resist what loads', '[{"id": "a", "text": "compression.", "correct": false}, {"id": "b", "text": "shear.", "correct": true}, {"id": "c", "text": "tension.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What test do you do on a bonded join?', '[{"id": "a", "text": "Shear", "correct": false}, {"id": "b", "text": "Peel", "correct": true}, {"id": "c", "text": "Tension", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What would you use to check the run-out on a control rod?', '[{"id": "a", "text": "Micrometer + ball bearing.", "correct": false}, {"id": "b", "text": "DTI + V blocks.", "correct": true}, {"id": "c", "text": "3 leg trammel + feeler gauge.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Taper pins are used in which of the following applications?', '[{"id": "a", "text": "To take compression loads.", "correct": false}, {"id": "b", "text": "To take shear loads.", "correct": true}, {"id": "c", "text": "To take compression and shear loads.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a D.T.I. to check the run-out of a shaft, readings of -15 to +25 would indicate a run-out of', '[{"id": "a", "text": "0.025 inches.", "correct": false}, {"id": "b", "text": "0.020 inches.", "correct": false}, {"id": "c", "text": "0.040 inches.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A dent is measured in a tubular push-pull rod by', '[{"id": "a", "text": "passing a ball down its bore.", "correct": true}, {"id": "b", "text": "callipers and feeler gauges.", "correct": false}, {"id": "c", "text": "a steel ball and micrometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is used on Magnesium to re-protect it?', '[{"id": "a", "text": "Selenious Acid", "correct": true}, {"id": "b", "text": "Deoxidine", "correct": false}, {"id": "c", "text": "Chromic Acid", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In the procedure to be followed after spillage of battery acid, neutralizing is carried out', '[{"id": "a", "text": "by washing with distilled water.", "correct": false}, {"id": "b", "text": "by applying a coating of Vaseline.", "correct": false}, {"id": "c", "text": "with a dilute solution of sodium bicarbonate.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After carrying out an identification test of aluminium alloy with caustic soda, the caustic soda should be neutralized with', '[{"id": "a", "text": "Chromic anhydride solution.", "correct": true}, {"id": "b", "text": "Copper sulphate solution.", "correct": false}, {"id": "c", "text": "Phosphoric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To neutralize spilled battery acid on aluminium alloy, use', '[{"id": "a", "text": "sulphuric acid.", "correct": false}, {"id": "b", "text": "bicarbonate of soda.", "correct": true}, {"id": "c", "text": "caustic soda.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hydrogen embrittlement of high tensile steel is caused if it is treated with', '[{"id": "a", "text": "Zinc Chromate.", "correct": false}, {"id": "b", "text": "Phosphoric acid.", "correct": true}, {"id": "c", "text": "Nitric acid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Dents in a tubular push-pull rod are not allowed', '[{"id": "a", "text": "anywhere on the rod.", "correct": false}, {"id": "b", "text": "in the middle third of the rod.", "correct": true}, {"id": "c", "text": "in the end thirds of the rod.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking a diode forward bias function, the positive lead of the ohmmeter should be placed on the', '[{"id": "a", "text": "cathode and the negative lead to the anode.", "correct": false}, {"id": "b", "text": "anode and the negative lead to the cathode.", "correct": true}, {"id": "c", "text": "cathode and the negative lead the earth.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The bonding resistance of primary structure must not exceed', '[{"id": "a", "text": "0.05 ohms.", "correct": true}, {"id": "b", "text": "0.005 ohms.", "correct": false}, {"id": "c", "text": "0.5 ohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When replacing a bonding connection and the original conductor cannot be matched exactly, which of the following replacements would you use?', '[{"id": "a", "text": "One manufactured from the same type of material, but of greater cross sectional area should be selected.", "correct": true}, {"id": "b", "text": "One manufactured from any piece of Nyvin cable having the correct current capacity may be used.", "correct": false}, {"id": "c", "text": "One manufactured from any conducting material of the same cross sectional area be used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is a typical minimum insulation resistance value for an aircraft undercarriage bay?', '[{"id": "a", "text": "10 megohms", "correct": false}, {"id": "b", "text": "5 megohms", "correct": false}, {"id": "c", "text": "2 megohms", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The recommended insulation resistance of a DC motor is', '[{"id": "a", "text": "2 megohms.", "correct": true}, {"id": "b", "text": "0.5 megohms.", "correct": false}, {"id": "c", "text": "5 megohms.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Bonding value for secondary structure is a maximum of', '[{"id": "a", "text": "1 ohm.", "correct": false}, {"id": "b", "text": "0.05 ohms.", "correct": false}, {"id": "c", "text": "0.5 ohms.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Wrinkling of an aircraft skin will', '[{"id": "a", "text": "cause rivets to pull.", "correct": true}, {"id": "b", "text": "weaken the skin.", "correct": false}, {"id": "c", "text": "increase drag on the aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'You have removed a bolt from a critical bolted joint for inspection and rectification. What action should you take prior to inspection?', '[{"id": "a", "text": "Before any inspection is carried out, the nut/bolt and hole must be cleaned with a solvent such as trichloroethylene.", "correct": false}, {"id": "b", "text": "Clean the bolt shank and thread and re-grease and replace bolt and check for side-play.", "correct": false}, {"id": "c", "text": "A preliminary inspection should be made before the hole is cleaned.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On inspection of a critical bolted joint you witness black or grey dust or paste. What type of corrosion has taken place and what type of material is involved?', '[{"id": "a", "text": "Exfoliation corrosion in magnesium alloys.", "correct": false}, {"id": "b", "text": "Galvanic corrosion in magnesium alloys.", "correct": true}, {"id": "c", "text": "Fretting corrosion in aluminium alloys.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is indicated by the wrinkling of the underside of an aircraft skin?', '[{"id": "a", "text": "Hogging", "correct": false}, {"id": "b", "text": "Fretting", "correct": false}, {"id": "c", "text": "Sagging", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is used to re-protect magnesium?', '[{"id": "a", "text": "Selenious acid", "correct": true}, {"id": "b", "text": "Deoxidine", "correct": false}, {"id": "c", "text": "Chromic acid", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is used on magnesium to remove corrosion?', '[{"id": "a", "text": "Strontium chromate", "correct": false}, {"id": "b", "text": "Chromic acid / sulphuric acid solution", "correct": true}, {"id": "c", "text": "Selenious acid", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Galvanic corrosion refers to a type of', '[{"id": "a", "text": "corrosion between two pieces of material.", "correct": true}, {"id": "b", "text": "plating process.", "correct": false}, {"id": "c", "text": "surface corrosion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Chromating used on magnesium alloys produces', '[{"id": "a", "text": "chromium surface electrochemically.", "correct": false}, {"id": "b", "text": "a chromate film surface.", "correct": true}, {"id": "c", "text": "metal chromates on the electrochemically.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Chromating used on magnesium alloys', '[{"id": "a", "text": "uses chromium and converts the surface electrochemically.", "correct": false}, {"id": "b", "text": "uses chromates and converts the surface chemically.", "correct": true}, {"id": "c", "text": "uses chromium, which is deposited on the surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a bonding test in the presence of an anodic coating, what should you do?', '[{"id": "a", "text": "Take account of the resistance of the coating.", "correct": false}, {"id": "b", "text": "Disregard the resistance of the coating.", "correct": false}, {"id": "c", "text": "Penetrate the coating so a good electrical contact is made.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Maximum value of resistance between all isolated parts which may be subjected to appreciable electrostatic charging and the main earth.', '[{"id": "a", "text": "0.5 Megohm or 100 kilohm per sq.ft. of surface area whichever is less.", "correct": true}, {"id": "b", "text": "1 ohm", "correct": false}, {"id": "c", "text": "0.05 ohm", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Removal of corrosion from aluminium clad alloy is best done', '[{"id": "a", "text": "mechanically by buffing.", "correct": true}, {"id": "b", "text": "chemically by trichloroethylene.", "correct": false}, {"id": "c", "text": "chemically by sulphuric acid solution.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Control methods for galvanic corrosion include', '[{"id": "a", "text": "reducing cyclic stressing and increasing cross sectional area.", "correct": false}, {"id": "b", "text": "joining similar metals and using jointing compounds.", "correct": true}, {"id": "c", "text": "ensuring correct heat treatments and correct alloying.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The treatment for stress corrosion is', '[{"id": "a", "text": "not the same as fatigue corrosion.", "correct": false}, {"id": "b", "text": "the same as for surface corrosion or surface cracks in sheet metal.", "correct": true}, {"id": "c", "text": "always the replacement of the part.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Very light corrosion on aluminium alloy can be removed by', '[{"id": "a", "text": "using a solvent.", "correct": false}, {"id": "b", "text": "rubbing with wire wool.", "correct": false}, {"id": "c", "text": "using Alocrom 1200.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To remove corrosion on Fe metals use', '[{"id": "a", "text": "selenious acid rust remover.", "correct": false}, {"id": "b", "text": "sulphuric acid rust remover.", "correct": false}, {"id": "c", "text": "phosphoric acid rust remover.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An intervention defect is one where', '[{"id": "a", "text": "the engineer has the discretion on whether to intervene.", "correct": false}, {"id": "b", "text": "there is a requirement for the maintenance engineer to intervene.", "correct": false}, {"id": "c", "text": "the defect occurred because of some previous maintenance action.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Vapour phase inhibitor should be used', '[{"id": "a", "text": "when re-protecting after corrosion.", "correct": true}, {"id": "b", "text": "when degreasing a component.", "correct": false}, {"id": "c", "text": "when painting an aircraft.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out insulation resistance checks', '[{"id": "a", "text": "the measurement is always infinity if the cable is installed correctly.", "correct": false}, {"id": "b", "text": "the measurement will also show cable continuity.", "correct": false}, {"id": "c", "text": "the measurement varies depending upon the ambient conditions of the aircraft under test.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How is damage classified on an aircraft skin?', '[{"id": "a", "text": "Negligible, repairable, replacement.", "correct": false}, {"id": "b", "text": "Negligible, allowable, replacement.", "correct": false}, {"id": "c", "text": "Negligible, allowable, repairable.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a millivolt drop test on a terminal, the maximum value should be', '[{"id": "a", "text": "50mV/10A.", "correct": false}, {"id": "b", "text": "10mV/10A.", "correct": false}, {"id": "c", "text": "5mV/10A.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A jury strut is used', '[{"id": "a", "text": "as a reference when checking the C of G position.", "correct": false}, {"id": "b", "text": "as a datum when placing the aircraft in a rigging position.", "correct": false}, {"id": "c", "text": "to support the structure during repairs.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you check the resistance of a fire bottle cartridge?', '[{"id": "a", "text": "Use an insulation tester.", "correct": false}, {"id": "b", "text": "Use a multimeter.", "correct": false}, {"id": "c", "text": "Use a light and bulb.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If after forming a crimp in an electrical condutor a high resistance is suspected, how would you carry out a check without disturbing the connection?', '[{"id": "a", "text": "Use a multimeter set to millivolts and carry out a millivolts drop test.", "correct": true}, {"id": "b", "text": "Carry out an insulation check.", "correct": false}, {"id": "c", "text": "Use a multimeter set to ohms to check the resistance.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Damaged chromate film should be repaired by using', '[{"id": "a", "text": "phosphoric acid 10% by weight in water.", "correct": false}, {"id": "b", "text": "selenious acid 10% by weight in water.", "correct": true}, {"id": "c", "text": "selenious acid 20% by weight in water.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inserting a helicoil insert, which way does the tang face?', '[{"id": "a", "text": "Away from the hole.", "correct": true}, {"id": "b", "text": "Towards the hole.", "correct": false}, {"id": "c", "text": "Towards the mandrel.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a patch repair you should use', '[{"id": "a", "text": "material one gauge thicker than the original structure.", "correct": false}, {"id": "b", "text": "the same rivet spacing as the original structure.", "correct": true}, {"id": "c", "text": "only aluminium alloy rivets.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What tap do you use when fitting a Helicoil?', '[{"id": "a", "text": "The same as the original thread size.", "correct": false}, {"id": "b", "text": "The next size up from the original tap size.", "correct": false}, {"id": "c", "text": "The tap supplied with the Helicoil kit.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting a thread insert', '[{"id": "a", "text": "the hole should be expanded using a tap supplied by the insert manufacturer.", "correct": true}, {"id": "b", "text": "the insert should be tapped in using a hammer.", "correct": false}, {"id": "c", "text": "a thread the next size up from the original should be tapped.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A stud broken off below the surface is removed by', '[{"id": "a", "text": "using a stud box.", "correct": false}, {"id": "b", "text": "a stud remover tool fitted into a drilled hole.", "correct": true}, {"id": "c", "text": "cutting a slot in it and removing with a screwdriver.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A thread insert is made from', '[{"id": "a", "text": "white metal.", "correct": false}, {"id": "b", "text": "aluminium alloy.", "correct": false}, {"id": "c", "text": "stainless steel.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a composite repair the vacuum should be', '[{"id": "a", "text": "above required level.", "correct": false}, {"id": "b", "text": "below required level.", "correct": false}, {"id": "c", "text": "at the required level.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If bridging strips or bonding cords are fractured, what action may be taken?', '[{"id": "a", "text": "The broken ends can be repaired with an “in-line” splice.", "correct": false}, {"id": "b", "text": "A new conductor should be fitted.", "correct": true}, {"id": "c", "text": "The broken ends can be soldered.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A UNF threaded wire thread insert may be identified', '[{"id": "a", "text": "by a black painted tang.", "correct": true}, {"id": "b", "text": "by a red painted tang.", "correct": false}, {"id": "c", "text": "by an unpainted tang.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Transducers used in ultrasonic testing exhibit which of he following effects?', '[{"id": "a", "text": "Hyper-acoustic", "correct": false}, {"id": "b", "text": "Ferromagnetic", "correct": false}, {"id": "c", "text": "Piezoelectric", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The eddy current method of N.D.T. uses', '[{"id": "a", "text": "AC or DC.", "correct": false}, {"id": "b", "text": "Direct current.", "correct": false}, {"id": "c", "text": "Alternating current.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To measure the thickness of a paint finish, what type of NDT inspection is used?', '[{"id": "a", "text": "A woodpecker", "correct": false}, {"id": "b", "text": "Ultrasonic", "correct": true}, {"id": "c", "text": "Radiographic", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a dye penetrant test, after the developer has been applied it should be inspected', '[{"id": "a", "text": "after 30 minutes.", "correct": false}, {"id": "b", "text": "as soon as the developer is dry and again after approximately 10 minutes.", "correct": true}, {"id": "c", "text": "after 1 hour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'During a colour contrast test the penetrant time should be', '[{"id": "a", "text": "longer for a small crack.", "correct": false}, {"id": "b", "text": "shorter for a small crack.", "correct": false}, {"id": "c", "text": "longer for a wide crack.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How should a dye penetrant field kit be stored?', '[{"id": "a", "text": "At a cold temperature in a darkened room.", "correct": false}, {"id": "b", "text": "In direct sunlight.", "correct": false}, {"id": "c", "text": "At room temperature away from direct sunlight.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a colour contrast test on a pressure vessel', '[{"id": "a", "text": "the dye should be applied to the outside and the developer to the inside.", "correct": false}, {"id": "b", "text": "the dye should be applied to the inside and the developer to the outside.", "correct": true}, {"id": "c", "text": "both the dye and the developer should be applied to the outside.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When leak testing with a colour contrast field kit, the soak time for a component less than 1/8 in. (3mm) thick would be', '[{"id": "a", "text": "at least twice the normal soak time.", "correct": true}, {"id": "b", "text": "at least 3 times the normal soak time.", "correct": false}, {"id": "c", "text": "at least the normal soak time.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a colour contrast dye penetrant kit, and a small crack is suspected in the material', '[{"id": "a", "text": "less developer should be used.", "correct": false}, {"id": "b", "text": "less inhibitor should be used.", "correct": false}, {"id": "c", "text": "a magnifying glass is recommended.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What NDT method would you use to detect delamination?', '[{"id": "a", "text": "Colour contrast dye penetrant.", "correct": false}, {"id": "b", "text": "Ultrasound.", "correct": true}, {"id": "c", "text": "Eddy current.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Magnetic particle testing detects faults', '[{"id": "a", "text": "transverse.", "correct": false}, {"id": "b", "text": "longitudinally.", "correct": false}, {"id": "c", "text": "longitudinal and transverse.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Dye penetrant in a cold climate', '[{"id": "a", "text": "takes longer to work.", "correct": true}, {"id": "b", "text": "is not affected.", "correct": false}, {"id": "c", "text": "works more quickly.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If after spraying the developer, red blotches appear, the part', '[{"id": "a", "text": "has sub-surface defects.", "correct": false}, {"id": "b", "text": "was not cleaned properly.", "correct": false}, {"id": "c", "text": "is porous.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the purpose of the developer in a dye penetrant inspection?', '[{"id": "a", "text": "It acts a s a blotter to draw out the penetrant that has seeped into the crack.", "correct": true}, {"id": "b", "text": "It is drawn to the crack by electrostatic attraction.", "correct": false}, {"id": "c", "text": "It seeps into the crack and makes it show up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The main advantage of dye penetrant inspection is', '[{"id": "a", "text": "the part to be inspected does not require cleaning.", "correct": false}, {"id": "b", "text": "the defect must be opened to the surface.", "correct": true}, {"id": "c", "text": "the penetrant solution works on any non-porous material.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To detect a minute crack using dye penetrant inspection usually requires', '[{"id": "a", "text": "the surface to be highly polished.", "correct": false}, {"id": "b", "text": "a longer than normal penetrating time.", "correct": true}, {"id": "c", "text": "that the developer be applied to a flat surface.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking an item with the magnetic particle inspection method, circular and longitudinal magnetization should be used to', '[{"id": "a", "text": "evenly magnetize the entire part.", "correct": false}, {"id": "b", "text": "ensure uniform current flow.", "correct": false}, {"id": "c", "text": "reveal all possible defects.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type crack can be detected by magnetic particle inspection using either circular or longitudinal magnetisation?', '[{"id": "a", "text": "transverse.", "correct": false}, {"id": "b", "text": "longitudinal.", "correct": false}, {"id": "c", "text": "45°.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Surface cracks in aluminium castings and forgings may usually be detected by', '[{"id": "a", "text": "submerging the part in a solution of hydrochloric acid and rinsing with clear water.", "correct": false}, {"id": "b", "text": "gamma ray inspection.", "correct": false}, {"id": "c", "text": "the use of dye penetrants and suitable developers.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of these metals is inspected using the magnetic particle inspection method?', '[{"id": "a", "text": "Magnesium alloys.", "correct": false}, {"id": "b", "text": "Aluminium alloys.", "correct": false}, {"id": "c", "text": "Iron alloys.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'One way a part may be demagnetized after magnetic particle inspection is by', '[{"id": "a", "text": "slowly moving the part out of an AC magnetic field of sufficient strength.", "correct": true}, {"id": "b", "text": "slowly moving the part into an AC magnetic field of sufficient strength.", "correct": false}, {"id": "c", "text": "subjecting the part to high voltage, low amperage AC.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The testing medium that is generally used in magnetic particle inspection utilises a ferromagnetic material that has', '[{"id": "a", "text": "low permeability and high retentivity.", "correct": false}, {"id": "b", "text": "high permeability and low retentivity.", "correct": true}, {"id": "c", "text": "high permeability and high retentivity.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What non-destructive testing method requires little or no part preparation, is used to detect surface or near-surface defects in most metals, and may also be used to separate metals or alloys and their heat-treat conditions?', '[{"id": "a", "text": "Eddy current inspection.", "correct": true}, {"id": "b", "text": "Magnetic particle inspection.", "correct": false}, {"id": "c", "text": "Ultrasonic inspection.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Gamma Ray Testing of combustion chambers will show up', '[{"id": "a", "text": "black on lighter background.", "correct": false}, {"id": "b", "text": "grey on white background.", "correct": true}, {"id": "c", "text": "light grey on black background.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of these non-destructive testing methods is suitable for the inspection of most metals, plastics and ceramics for surface and subsurface defects?', '[{"id": "a", "text": "Eddy current inspection.", "correct": false}, {"id": "b", "text": "Magnetic particle inspection.", "correct": false}, {"id": "c", "text": "Ultrasonic inspection.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Ultrasonic flaw detectors use', '[{"id": "a", "text": "high frequency sound waves.", "correct": true}, {"id": "b", "text": "a magnetic field.", "correct": false}, {"id": "c", "text": "x-rays.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Defects are indicated in the dye penetrant crack detection test by', '[{"id": "a", "text": "red lines on a white background.", "correct": true}, {"id": "b", "text": "yellowish green marks.", "correct": false}, {"id": "c", "text": "green lines and dots.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'NDT using colour dye process at temperatures below 15°C will', '[{"id": "a", "text": "not be affected by the temperature.", "correct": false}, {"id": "b", "text": "retard the penetrant action of the dye and penetration time is extended.", "correct": true}, {"id": "c", "text": "mean choosing alternative NDT method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using dye penetrant NDT on a tank, the dye penetrant should be applied', '[{"id": "a", "text": "on the outside with developer on the outside.", "correct": false}, {"id": "b", "text": "on the inside, with developer on the outside.", "correct": true}, {"id": "c", "text": "on the inside with the developer on the inside.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In order for dye penetrant inspection to be effective, the material being checked must', '[{"id": "a", "text": "be non-magnetic.", "correct": false}, {"id": "b", "text": "be magnetic.", "correct": false}, {"id": "c", "text": "have surface cracks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following metals can be inspected using the magnetic particle inspection method?', '[{"id": "a", "text": "Aluminium alloys.", "correct": false}, {"id": "b", "text": "Iron alloys.", "correct": true}, {"id": "c", "text": "Magnesium alloys.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After completion of electromagnetic crack detection, the test piece must be', '[{"id": "a", "text": "allowed to cool to room temperature as slowly as possible.", "correct": false}, {"id": "b", "text": "de-magnetised before returning to service.", "correct": true}, {"id": "c", "text": "allowed to lose any residual magnetism over as long a period possible.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following N.D.T. techniques cannot be used on a component manufactured from austenitic stainless steel?', '[{"id": "a", "text": "Magnetic - particle.", "correct": true}, {"id": "b", "text": "Penetrant dye.", "correct": false}, {"id": "c", "text": "Hot oil and chalk.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Fluorescent penetrant processes for the detection of cracks or material defects are used with', '[{"id": "a", "text": "a tungsten light source.", "correct": false}, {"id": "b", "text": "an infra-red light source.", "correct": false}, {"id": "c", "text": "an ultra-violet radiation source.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is an isotope the power source of?', '[{"id": "a", "text": "X-Rays", "correct": false}, {"id": "b", "text": "Ultra Violet Rays", "correct": false}, {"id": "c", "text": "Gamma Rays", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Under magnetic particle inspection, a part will be identified as having a fatigue crack under which condition?', '[{"id": "a", "text": "The discontinuity pattern is straight.", "correct": false}, {"id": "b", "text": "The discontinuity is found in a highly stressed area of the part.", "correct": true}, {"id": "c", "text": "The discontinuity is found in a non-stressed area of the part.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inspecting a component which is being subjected to the hot fluid chalk process, the examination for defects should be carried out', '[{"id": "a", "text": "whilst the item is still quite hot.", "correct": false}, {"id": "b", "text": "immediately on removal of the item from the chalk cabinet.", "correct": false}, {"id": "c", "text": "when the item is quite cool.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Circular magnetization of a part can be used to detect defects', '[{"id": "a", "text": "perpendicular to the concentric circles of magnetisation.", "correct": false}, {"id": "b", "text": "parallel to the long axis of the part.", "correct": false}, {"id": "c", "text": "perpendicular to the long axis of the part.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An indication of porosity when using a penetrant dye crack detection method is', '[{"id": "a", "text": "areas where dye is not showing.", "correct": false}, {"id": "b", "text": "an area of scattered dots of dye.", "correct": true}, {"id": "c", "text": "closely spaced dots of dye formed in a line.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a test for adequate demagnetization of a component after a magnetic particle test, the test compass should not deflect', '[{"id": "a", "text": "more than 1° when standing due east of the component.", "correct": true}, {"id": "b", "text": "more than 1° when standing due south of the component.", "correct": false}, {"id": "c", "text": "more than 1° when standing north-east of the component.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If on application of developer it all turns to a pinkish hue, what has happened?', '[{"id": "a", "text": "Thin porosity.", "correct": false}, {"id": "b", "text": "The hue has pinked.", "correct": false}, {"id": "c", "text": "Incorrect cleaning.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If dye penetrant inspection indications are not sharp and clear, the most probable cause is that the part', '[{"id": "a", "text": "is not damaged.", "correct": false}, {"id": "b", "text": "was not correctly degaussed before the developer was applied.", "correct": false}, {"id": "c", "text": "was not thoroughly cleaned before developer was applied.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The pattern for an inclusion is a magnetic particle build-up forming', '[{"id": "a", "text": "a single line.", "correct": true}, {"id": "b", "text": "parallel lines.", "correct": false}, {"id": "c", "text": "a fern-like pattern.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a penetrant dye crack test, before the dye is applied the surface being tested should be', '[{"id": "a", "text": "etch primed.", "correct": false}, {"id": "b", "text": "thoroughly degreased.", "correct": true}, {"id": "c", "text": "painted with developer fluid.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out a dye penetrant inspection, what time should elapse after applying the developer before inspecting the component?', '[{"id": "a", "text": "Initial inspection after 30 seconds followed by a 2nd inspection after 10 minutes.", "correct": true}, {"id": "b", "text": "After 15 minutes.", "correct": false}, {"id": "c", "text": "After 10 minutes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When should the developer be applied to the component?', '[{"id": "a", "text": "After excess penetrant has been removed and the area completely dried.", "correct": true}, {"id": "b", "text": "Before applying penetrant.", "correct": false}, {"id": "c", "text": "Before the penetrant dries.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To check the structure of a wing', '[{"id": "a", "text": "ultrasound NDT is used.", "correct": false}, {"id": "b", "text": "high voltage X-rays are used.", "correct": true}, {"id": "c", "text": "low voltage X-rays are used.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following NDT methods requires that the orientation (or direction) of the defect be known before the test can commence?', '[{"id": "a", "text": "Ultrasonic and Dye Penetrant.", "correct": false}, {"id": "b", "text": "Magnetic Particle and Ultrasonic.", "correct": true}, {"id": "c", "text": "X-Ray and Magnetic Particle.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following defects could not be detected by Eddy Current NDT inspection?', '[{"id": "a", "text": "A crack in a glass fibre reinforced plastic cowl.", "correct": true}, {"id": "b", "text": "A crack in a magnesium alloy wheel casting.", "correct": false}, {"id": "c", "text": "Heat damage of a Haynes Alloy turbine blade.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following methods could be used to detect the presence of tiny drops of Mercury in a large area of aircraft hull structure after an accident with a mercury thermometer?', '[{"id": "a", "text": "X-Ray", "correct": true}, {"id": "b", "text": "Magnetic Particle", "correct": false}, {"id": "c", "text": "Ultrasonic", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following NDT methods requires that the surface of the test piece is cleaned down to bare metal?', '[{"id": "a", "text": "Eddy Current.", "correct": false}, {"id": "b", "text": "Magnetic Particle.", "correct": false}, {"id": "c", "text": "Dye-penetrant.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the colour contrast NDT', '[{"id": "a", "text": "the surface paint should be removed.", "correct": true}, {"id": "b", "text": "the surface should be lightly scuffed.", "correct": false}, {"id": "c", "text": "the surface should be bead blasted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using dye penetrant field kit, removal of excess penetrant is done by applying the solvent by', '[{"id": "a", "text": "spraying once direct on the part.", "correct": false}, {"id": "b", "text": "spraying twice direct on the part.", "correct": false}, {"id": "c", "text": "using a lint free cloth.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Liquid penetrant tests can be used to detect', '[{"id": "a", "text": "internal porosity in castings.", "correct": false}, {"id": "b", "text": "corrosion wall thinning in pipes and tubes.", "correct": false}, {"id": "c", "text": "fatigue cracks in magnesium alloy parts.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Water-washable liquid penetrants differ from Post-emulsification penetrants in that they', '[{"id": "a", "text": "do not need an emulsifier added.", "correct": true}, {"id": "b", "text": "need not be removed from surfaces prior to development.", "correct": false}, {"id": "c", "text": "can only be used on aluminium alloys.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using a post-emulsification penetrant, the timing is most critical during', '[{"id": "a", "text": "penetrant removal.", "correct": false}, {"id": "b", "text": "emulsification.", "correct": true}, {"id": "c", "text": "penetration.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A liquid penetrant test cannot', '[{"id": "a", "text": "be used on porous materials.", "correct": true}, {"id": "b", "text": "locate sub-surface discontinuities.", "correct": false}, {"id": "c", "text": "be used on non-metallic surfaces.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hot air drying of articles during liquid penetrant testing is carried out at a temperature of', '[{"id": "a", "text": "75°F.", "correct": false}, {"id": "b", "text": "250°F.", "correct": false}, {"id": "c", "text": "130°F.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To check the structure of a wing, which NDT is used?', '[{"id": "a", "text": "Radiographic", "correct": true}, {"id": "b", "text": "Dye penetrant", "correct": false}, {"id": "c", "text": "Magnetic Flaw", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Magnetic Flux detection will show defects which are', '[{"id": "a", "text": "transverse to the flux direction only.", "correct": true}, {"id": "b", "text": "longitudinal to the flux direction only.", "correct": false}, {"id": "c", "text": "longitudinal and transverse to the flux direction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hairline crack would show up on a dye penetrant inspection as', '[{"id": "a", "text": "a continuous line of small dots.", "correct": false}, {"id": "b", "text": "a thin broken line or chain.", "correct": true}, {"id": "c", "text": "a group of dots spread over a wide area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When carrying out an ultrasonic inspection, what is the gel used for?', '[{"id": "a", "text": "To create a good sonic coupling between the the probe and the test piece.", "correct": true}, {"id": "b", "text": "To reduce the friction between the probe and the test piece.", "correct": false}, {"id": "c", "text": "To prevent the test piece from becoming scratched by the probe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Fluorescent dye penetrant is suited for what materials?', '[{"id": "a", "text": "Non magnetic non-ferrous materials.", "correct": true}, {"id": "b", "text": "Ferrous magnetic materials.", "correct": false}, {"id": "c", "text": "Plastics and non magnetic materials.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In film radiography, image quality indicators (IQI) are usually placed', '[{"id": "a", "text": "between the intensifying screen and the film.", "correct": false}, {"id": "b", "text": "on the film side of the object.", "correct": false}, {"id": "c", "text": "on the source side of the test object.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type crack will probably cause the most build-up in the magnetic particle indicating medium?', '[{"id": "a", "text": "Grinding", "correct": false}, {"id": "b", "text": "Shrink", "correct": false}, {"id": "c", "text": "Fatigue", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using dye penetrant NDT on a tank, the penetrant should be applied', '[{"id": "a", "text": "on the inside, with developer on the inside.", "correct": false}, {"id": "b", "text": "on the outside, with developer on the outside.", "correct": false}, {"id": "c", "text": "on the inside, with developer on the outside.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To detect a fault with magnetic particle flaw detection, the test requires', '[{"id": "a", "text": "two passes in any direction.", "correct": false}, {"id": "b", "text": "one pass in any direction.", "correct": false}, {"id": "c", "text": "two passes at 90 degrees to each other.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The substance used in ultrasound inspection is', '[{"id": "a", "text": "a couplant to allow sound waves to travel.", "correct": true}, {"id": "b", "text": "a cleaning agent to keep the components clean.", "correct": false}, {"id": "c", "text": "a developer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Dye penetrant defects are marked using', '[{"id": "a", "text": "crayon, unless used in a highly stresses area.", "correct": true}, {"id": "b", "text": "pencil.", "correct": false}, {"id": "c", "text": "chalk.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following NDT techniques cannot be used on a component manufactured from austenitic stainless steel?', '[{"id": "a", "text": "Penetrant dye.", "correct": false}, {"id": "b", "text": "Magnetic particle.", "correct": true}, {"id": "c", "text": "Hot oil and chalk.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The dye penetrant field test kit consists of cans of', '[{"id": "a", "text": "penetrant, cleaner, developer and a brush.", "correct": false}, {"id": "b", "text": "spray penetrant, spray cleaner and spray developer.", "correct": false}, {"id": "c", "text": "penetrant, cleaner and developer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The liquid applied to a component being checked by magnetic particle inspection is for', '[{"id": "a", "text": "acting as a transmission medium for the test.", "correct": true}, {"id": "b", "text": "to prevent corrosion occurring from contact with the probe.", "correct": false}, {"id": "c", "text": "to prevent scratching of the surface by the probe.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which is the preferred method of test for aluminium alloy alloy?', '[{"id": "a", "text": "Electroflux", "correct": false}, {"id": "b", "text": "Magnaflux", "correct": false}, {"id": "c", "text": "Ultrasonic", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A composite flap panel has corrosion. What NDT method will you use to detect?', '[{"id": "a", "text": "Low voltage x-ray.", "correct": false}, {"id": "b", "text": "Coin tap test.", "correct": true}, {"id": "c", "text": "High voltage x-ray.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The eddy current method of flaw detection can detect', '[{"id": "a", "text": "sub surface flaws only.", "correct": false}, {"id": "b", "text": "surface flaws and those just beneath the surface.", "correct": true}, {"id": "c", "text": "surface flaws only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'With dye penetrant how is the developer applied?', '[{"id": "a", "text": "Using a tank.", "correct": false}, {"id": "b", "text": "As an even layer of chalk applied over the area.", "correct": false}, {"id": "c", "text": "At a distance of 10 to 12 inches with several passes.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the dye penetrant method crack detection, the indications on a short, deep crack are', '[{"id": "a", "text": "single dots.", "correct": false}, {"id": "b", "text": "circles.", "correct": false}, {"id": "c", "text": "long chain.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A deep internal crack in a structural steel member is detected by', '[{"id": "a", "text": "x-ray or ultrasonic process.", "correct": true}, {"id": "b", "text": "fluorescent penetrant method.", "correct": false}, {"id": "c", "text": "magnetic flaw method.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The ultrasonic method of crack detection can be used on', '[{"id": "a", "text": "surface and subsurface defects on all metals.", "correct": false}, {"id": "b", "text": "surface and subsurface defects on ferrous metals only.", "correct": false}, {"id": "c", "text": "subsurface defects on all metals.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Porosity in cast materials', '[{"id": "a", "text": "only occurs on the surface.", "correct": false}, {"id": "b", "text": "is only detectable on the surface.", "correct": false}, {"id": "c", "text": "is detectable as a surface or sub surface defect.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the fluorescent ink flaw detection method, the component should be inspected using an', '[{"id": "a", "text": "ultraviolet lamp.", "correct": true}, {"id": "b", "text": "infrared lamp.", "correct": false}, {"id": "c", "text": "ordinary lamp and special glasses.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the dye penetrant method of crack detection, it should not normally be used at temperatures', '[{"id": "a", "text": "above 20°C.", "correct": false}, {"id": "b", "text": "below 0°C.", "correct": true}, {"id": "c", "text": "above 15°C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When using the dye penetrant method, the part should be kept wet with the penetrant for', '[{"id": "a", "text": "5 minutes.", "correct": false}, {"id": "b", "text": "15 minutes.", "correct": true}, {"id": "c", "text": "up to one hour.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What NDT would you carry out on aluminium alloy?', '[{"id": "a", "text": "Electroflux", "correct": false}, {"id": "b", "text": "Magnetic flaw", "correct": false}, {"id": "c", "text": "Ultrasonic", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Where would you disconnect a chain?', '[{"id": "a", "text": "At a bolted joint.", "correct": false}, {"id": "b", "text": "At an riveted joint.", "correct": false}, {"id": "c", "text": "At a spring clip joint.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many times can a locking plate be used?', '[{"id": "a", "text": "3 times, then discarded.", "correct": false}, {"id": "b", "text": "Indefinitely providing it is a good fit around the component to be locked.", "correct": true}, {"id": "c", "text": "Once, then discarded.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hi-lock collar should be', '[{"id": "a", "text": "not lubed or washed because they are lubed at manufacture.", "correct": true}, {"id": "b", "text": "washed in solvent before fitting.", "correct": false}, {"id": "c", "text": "lubricated before fitting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When drilling out a rivet, use a drill', '[{"id": "a", "text": "larger than the hole.", "correct": false}, {"id": "b", "text": "same size as the hole.", "correct": false}, {"id": "c", "text": "smaller than the hole.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When riveting two dissimilar sheets of metal together the joint should be protected with', '[{"id": "a", "text": "jointing compound.", "correct": true}, {"id": "b", "text": "paint.", "correct": false}, {"id": "c", "text": "grease.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum temperature for Nyloc nuts is', '[{"id": "a", "text": "120°C.", "correct": true}, {"id": "b", "text": "100°C.", "correct": false}, {"id": "c", "text": "160°C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What type of rivet would you use when there is access to only one side of the work?', '[{"id": "a", "text": "Blind", "correct": true}, {"id": "b", "text": "Pop", "correct": false}, {"id": "c", "text": "Hilok", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Torque loading is carried out to provide', '[{"id": "a", "text": "as tight a joint as possible.", "correct": false}, {"id": "b", "text": "sufficient clamping without over-stressing.", "correct": true}, {"id": "c", "text": "flexibility.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is generally the best procedure to use when removing a solid shank rivet?', '[{"id": "a", "text": "Drill through the manufactured head and shank with a drill one size smaller than the rivet and remove the rivet with a", "correct": false}, {"id": "b", "text": "Drill through the manufactured head and shank with a shank size drill and remove the rivet with a punch.", "correct": false}, {"id": "c", "text": "Drill to the base of the manufactured rivet head with a drill one size smaller than the rivet shank and remove", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What action is taken with a common circlip removed from a component?', '[{"id": "a", "text": "It is replaced with a new item on assembly.", "correct": true}, {"id": "b", "text": "It is checked for springiness.", "correct": false}, {"id": "c", "text": "It is examined for distortion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The maximum bolt diameter for which a 1/16 split pin may be used is', '[{"id": "a", "text": "7/16.", "correct": false}, {"id": "b", "text": "1/4.", "correct": false}, {"id": "c", "text": "3/8.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is a shouldered stud used?', '[{"id": "a", "text": "To provide a rigid assembly.", "correct": true}, {"id": "b", "text": "To decrease weight without loss of strength.", "correct": false}, {"id": "c", "text": "As a replacement for a damaged stud.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A thread insert is removed by', '[{"id": "a", "text": "once fitted, a thread insert must not be removed.", "correct": false}, {"id": "b", "text": "using a drill the major diameter of the thread insert.", "correct": false}, {"id": "c", "text": "a special drill provided by the thread insert manufacturer.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting Rivnuts into position, how are they secured and prevented from rotating?', '[{"id": "a", "text": "Locknut at the rear.", "correct": false}, {"id": "b", "text": "A locating key.", "correct": true}, {"id": "c", "text": "Peened.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Hi-loks are installed with the', '[{"id": "a", "text": "thread and shank not lubricated.", "correct": false}, {"id": "b", "text": "shank lubricated when fitting.", "correct": false}, {"id": "c", "text": "thread lubricated when fitting.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A jury strut is one giving', '[{"id": "a", "text": "a temporary support.", "correct": true}, {"id": "b", "text": "a part of the structure that takes only tensile loads.", "correct": false}, {"id": "c", "text": "additional support to a stressed area.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which type of repair has to be used where the damage is large and lost strength of the area has to be restored?', '[{"id": "a", "text": "Patch repair to the punctured skin.", "correct": false}, {"id": "b", "text": "Filling plate and patch.", "correct": false}, {"id": "c", "text": "Insert and butt strap.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following actions would be taken to fit a locking device to a nut or bolt, if the correct torque has been reached but the locking device will not fit?', '[{"id": "a", "text": "Tighten further until device fits.", "correct": false}, {"id": "b", "text": "File the base of the nut.", "correct": false}, {"id": "c", "text": "Change the nut or bolt for one that will achieve the desired condition.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In the Push-pull tube linkage used in aircraft flying control systems, how is the length of the tube adjusted?', '[{"id": "a", "text": "Fit anew push-pull tube.", "correct": false}, {"id": "b", "text": "By adjusting end fittings at each end of the tube.", "correct": true}, {"id": "c", "text": "It is fixed and does not require adjusting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Spotfacing is done to', '[{"id": "a", "text": "provide a flat area on a rough surface.", "correct": true}, {"id": "b", "text": "compensate for height in lieu of a spring washer.", "correct": false}, {"id": "c", "text": "provide a good surface for welding.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting a hydraulic component, the hydraulic seal should be lubricated with', '[{"id": "a", "text": "a specified hydraulic oil.", "correct": false}, {"id": "b", "text": "grease.", "correct": false}, {"id": "c", "text": "the same fluid that is used in the hydraulic system (e.g. skydrol).", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A gap in a firewall can be plugged by', '[{"id": "a", "text": "an aluminium plate.", "correct": false}, {"id": "b", "text": "a fireproof bung or bush.", "correct": true}, {"id": "c", "text": "a plastic bung.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In a critically bolted joint', '[{"id": "a", "text": "a PLI washer can be used more than once only with self locking nuts.", "correct": false}, {"id": "b", "text": "a PLI washer can be affected by thread lubricant.", "correct": false}, {"id": "c", "text": "a PLI washer can only be used once.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following jointing compounds should not be used in the vicinity of a joint where the temperature may exceed 200°C?', '[{"id": "a", "text": "DTD 900", "correct": false}, {"id": "b", "text": "DTD 200", "correct": false}, {"id": "c", "text": "DTD 369", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Why is jointing compound applied to the surfaces of material being joined together prior to riveting?', '[{"id": "a", "text": "To act as a sealant and prevent filiform corrosion.", "correct": false}, {"id": "b", "text": "To inhibit electrolytic action.", "correct": true}, {"id": "c", "text": "To prevent swarf damage.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A metallic stiff nut', '[{"id": "a", "text": "cannot be torque loaded.", "correct": false}, {"id": "b", "text": "cannot be used in areas in excess of 250°C.", "correct": true}, {"id": "c", "text": "is pre lubricated and does not need lubricating.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you prevent earth loops forming on screened cables?', '[{"id": "a", "text": "Do not earth the screen.", "correct": false}, {"id": "b", "text": "Earth both ends of the screen.", "correct": false}, {"id": "c", "text": "Earth one end of the screen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When fitting a shackle pin, fit with', '[{"id": "a", "text": "head uppermost.", "correct": true}, {"id": "b", "text": "0.020.", "correct": false}, {"id": "c", "text": "a shake-proof washer under the head.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The threads on a stud', '[{"id": "a", "text": "are of opposite hand at each end of the plain of portion.", "correct": false}, {"id": "b", "text": "are of the same hand at each end of the plain portion.", "correct": true}, {"id": "c", "text": "are continuous throughout its length and there is no plain portion.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The angle between starts on a double start thread is', '[{"id": "a", "text": "180 degrees.", "correct": true}, {"id": "b", "text": "120 degrees.", "correct": false}, {"id": "c", "text": "90 degrees.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What does 18N and contiguous circles on the head of a bolt indicate?', '[{"id": "a", "text": "1.8 inch threaded portion and plain shank 1/2 inch UNF.", "correct": true}, {"id": "b", "text": "1.8 inch nominal length 1/2 inch BSF.", "correct": false}, {"id": "c", "text": "1.8 inch plain shank 1/2 inch UNF.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A UNF bolt is indicated by', '[{"id": "a", "text": "a triangle on the head.", "correct": false}, {"id": "b", "text": "2-3 rings on the head.", "correct": true}, {"id": "c", "text": "green dye.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Immediately after carrying out an insulation check, which of the following applies?', '[{"id": "a", "text": "A continuity check must be carried out before switching on the circuit for the first time.", "correct": false}, {"id": "b", "text": "The readings observed and the atmospheric conditions at the time should be noted and compared to previous", "correct": true}, {"id": "c", "text": "The observed readings should be noted and an independent check carried out by another engineer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An Insulation test is carried out on a group of cables and a low reading obtained. What action would you take?', '[{"id": "a", "text": "A low reading would be expected because the cables are in parallel.", "correct": false}, {"id": "b", "text": "Change or renew all the cables involved in the test.", "correct": false}, {"id": "c", "text": "Break the circuit down and carry out further checks.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'BITE systems to be used on the ground only are deactivated by', '[{"id": "a", "text": "on take off.", "correct": false}, {"id": "b", "text": "the parking break.", "correct": false}, {"id": "c", "text": "by the undercarriage retraction.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After the normal function test of an individual circuit has been completed and the circuit switched off', '[{"id": "a", "text": "a second function test must be carried out to verify the first.", "correct": false}, {"id": "b", "text": "the fuse should be removed and the circuit again switched on to check the isolation of the circuit concerned.", "correct": true}, {"id": "c", "text": "a duplicate check must be carried out in accordance with AWN 3.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A millivolt drop check is to be carried out on a heavy duty relay. The Millivoltmeter would be connected to the relay', '[{"id": "a", "text": "when contacts closed and power is on.", "correct": true}, {"id": "b", "text": "when contacts open and power off.", "correct": false}, {"id": "c", "text": "when contacts are open and power is on.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Electrical cables installed on aircraft. What is used to indicate a fault?', '[{"id": "a", "text": "Bonding test", "correct": false}, {"id": "b", "text": "Continuity test", "correct": true}, {"id": "c", "text": "Resistance test", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When checking resistance of a cable to the starter motor what test is carried out?', '[{"id": "a", "text": "Millivolt drop test.", "correct": true}, {"id": "b", "text": "Safety Ohmmeter.", "correct": false}, {"id": "c", "text": "Time Domain Reflectometer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When inspecting an aircraft after a lightning strike, you should observe', '[{"id": "a", "text": "entry damage.", "correct": false}, {"id": "b", "text": "all signs of burning.", "correct": false}, {"id": "c", "text": "entry and exit damage.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'To ensure protection against HIRF affecting audio and navigation aids', '[{"id": "a", "text": "ensure that all audio and navigation equipment is adequately screened.", "correct": true}, {"id": "b", "text": "inspect and check all bonding leads to ensure their serviceability and replace if defective.", "correct": false}, {"id": "c", "text": "ensure that the correct number of static wicks are fitted.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following is a preventive process against HIRF?', '[{"id": "a", "text": "Monitoring HIRF on the communication system.", "correct": false}, {"id": "b", "text": "Visual inspections.", "correct": false}, {"id": "c", "text": "Periodically checking aircraft bonding.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you prevent aquaplaning during landing?', '[{"id": "a", "text": "Reduce flare.", "correct": true}, {"id": "b", "text": "Use reverse thrust.", "correct": false}, {"id": "c", "text": "Put flaps up.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Skin wrinkling on the lower surface of a wing is caused by', '[{"id": "a", "text": "hogging.", "correct": false}, {"id": "b", "text": "tension.", "correct": false}, {"id": "c", "text": "sagging.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a report of flight through heavy turbulence, you would', '[{"id": "a", "text": "check the aircraft symmetry.", "correct": true}, {"id": "b", "text": "carry out a major overhaul.", "correct": false}, {"id": "c", "text": "not carry out any checks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a heavy landing you should check', '[{"id": "a", "text": "engine compressor shaft alignment.", "correct": false}, {"id": "b", "text": "engine thrust alignment.", "correct": false}, {"id": "c", "text": "engine module alignment.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A lightning strike on an aircraft would show', '[{"id": "a", "text": "the entry and exit point.", "correct": true}, {"id": "b", "text": "the entry point only.", "correct": false}, {"id": "c", "text": "the exit point only.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When an engine is not in direct electrical contact with its mounting, how should it be bonded?', '[{"id": "a", "text": "With at least one primary conductor.", "correct": false}, {"id": "b", "text": "With at least two primary conductors on one side of the engine.", "correct": false}, {"id": "c", "text": "With at least two primary conductors, one each side of the engine.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'HIRF interference occurs when', '[{"id": "a", "text": "in use on mid frequencies.", "correct": false}, {"id": "b", "text": "in use on low frequencies.", "correct": false}, {"id": "c", "text": "in use on all frequencies.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Non metallic parts of the aircraft', '[{"id": "a", "text": "do not require to be bonded because they are non conductive.", "correct": false}, {"id": "b", "text": "must be bonded by bonding leads.", "correct": true}, {"id": "c", "text": "must be bonded by application of conductive paint.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Whenever possible a functional test should be carried out on an aircraft using which power supply?', '[{"id": "a", "text": "The aircraft battery.", "correct": false}, {"id": "b", "text": "The aircraft generators.", "correct": false}, {"id": "c", "text": "An external supply.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How many primary bonding conductors are required on an engine?', '[{"id": "a", "text": "1 only", "correct": false}, {"id": "b", "text": "2 on one side", "correct": false}, {"id": "c", "text": "1 on each side", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the primary purpose of bonding of metallic parts of an aircraft?', '[{"id": "a", "text": "To provide a return path for electrical two-wire system.", "correct": false}, {"id": "b", "text": "To prevent high potential differences between metallic parts from building up.", "correct": true}, {"id": "c", "text": "To prevent lightening strikes.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'In order to maintain HIRF protection, bonding checks between airframe and electrical components carrying voltages greater than 50V RMS or dc should not exceed', '[{"id": "a", "text": "0.05 ohm.", "correct": true}, {"id": "b", "text": "1 ohm.", "correct": false}, {"id": "c", "text": "1 Mohm.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Ribbon cables affected by mutual impedance and current loop leakage should be protected by', '[{"id": "a", "text": "earthing each alternate conductor to separate points.", "correct": true}, {"id": "b", "text": "connecting all conductors to a common earth.", "correct": false}, {"id": "c", "text": "shielding each individual conductor.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft with under-wing mounted engines has a heavy landing, where would you expect to see wrinkling of the skins?', '[{"id": "a", "text": "Bottom skin caused by engine inertia.", "correct": true}, {"id": "b", "text": "Top skin only.", "correct": false}, {"id": "c", "text": "On the top and bottom skins.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following could be a primary cause of HIRF protection failure?', '[{"id": "a", "text": "Corrosion on bonding leads.", "correct": false}, {"id": "b", "text": "Broken or missing static wicks.", "correct": true}, {"id": "c", "text": "Unserviceable radio filters.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the reason for a primary bonding connection’s large cross-sectional area?', '[{"id": "a", "text": "To carry the static discharge current to the conducting nose wheel.", "correct": false}, {"id": "b", "text": "To carry lightening discharge current should the need arise.", "correct": true}, {"id": "c", "text": "To maintain the airframe at the same potential throughout.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When an aircraft has been struck by lightning', '[{"id": "a", "text": "control surface bearings and hinges should be checked for stiffness in operation.", "correct": true}, {"id": "b", "text": "control surface freedom of movement need not be checked provided skin punctures are less than 3/16 inch diameter.", "correct": false}, {"id": "c", "text": "control surface freedom of movement need not be checked providing the bonding is undamaged.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On an aircraft which has had a heavy landing, on the lower wing you may see', '[{"id": "a", "text": "sagging.", "correct": false}, {"id": "b", "text": "hogging.", "correct": false}, {"id": "c", "text": "wrinkling.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a reported lightning strike', '[{"id": "a", "text": "the flight controls should be checked for full and free movement before the next flight.", "correct": true}, {"id": "b", "text": "the flight controls need to be checked for full and free movement only if a bonding lead to one of the control surfaces is", "correct": false}, {"id": "c", "text": "the aircraft and its systems must have a major overhaul before the next flight.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Mandatory Warning Plaques and symbols', '[{"id": "a", "text": "must be displayed on all flights.", "correct": true}, {"id": "b", "text": "must be displayed in the cabin only if they are legible.", "correct": false}, {"id": "c", "text": "need not be displayed if they are incorporated in the flight manual.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Following a major defect the C of A', '[{"id": "a", "text": "is not affected, however may run out on a time basis.", "correct": false}, {"id": "b", "text": "will be invalidated and needs renewing.", "correct": false}, {"id": "c", "text": "Nothing will happen.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When storing parts you should use', '[{"id": "a", "text": "monitor the temperature.", "correct": false}, {"id": "b", "text": "silica gel.", "correct": true}, {"id": "c", "text": "place in a sealed container.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'ATA specification 100 is', '[{"id": "a", "text": "the procedures which must be complied with before an aircraft can be given a Certificate of Airworthiness in the", "correct": false}, {"id": "b", "text": "the International standardization of maintenance manuals, illustrated parts catalogues, overhaul and repair", "correct": true}, {"id": "c", "text": "the American FAA specification controlling the manufacture of aluminium and its alloys.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An aircraft should carry at least the following number of spare fuses:', '[{"id": "a", "text": "10.", "correct": false}, {"id": "b", "text": "3.", "correct": false}, {"id": "c", "text": "3. 3 or 10%, whichever is greater.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Maintenance Schedules are issued', '[{"id": "a", "text": "in a folder with the operators name on the cover.", "correct": false}, {"id": "b", "text": "with an approval certificate by the CAA.", "correct": false}, {"id": "c", "text": "by the operator with CAA approval.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'After a mandatory inspection has been carried out by a Licensed Engineer, what is issued', '[{"id": "a", "text": "a Certificate of Maintenance Review.", "correct": false}, {"id": "b", "text": "Certificate of Release to Service.", "correct": true}, {"id": "c", "text": "a Flight Release Certificate.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A hard time engine inspection involves', '[{"id": "a", "text": "replacement with a new or overhauled component.", "correct": true}, {"id": "b", "text": "an in-situ function test.", "correct": false}, {"id": "c", "text": "removal of an engine component, its inspection and refitting.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Who approves Maintenance Manuals?', '[{"id": "a", "text": "The CAA.", "correct": true}, {"id": "b", "text": "The Department of Trade and Industry.", "correct": false}, {"id": "c", "text": "The Board of Trade.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Certificate of Release to Service must be issued after', '[{"id": "a", "text": "a repair has been carried out in accordance with an approved repair scheme.", "correct": true}, {"id": "b", "text": "a re-fuel has been done.", "correct": false}, {"id": "c", "text": "engine runs.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the operator varies the content of the maintenance schedule, what action must be taken?', '[{"id": "a", "text": "Amend the Maintenance Schedule and seek the CAA approval.", "correct": true}, {"id": "b", "text": "Await CAA approval before amending the Maintenance Schedule.", "correct": false}, {"id": "c", "text": "Amend the Maintenance Schedule.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When is an EASA Permit to Fly conditions required?', '[{"id": "a", "text": "To allow an unregistered aircraft to fly for air test.", "correct": false}, {"id": "b", "text": "To allow an aircraft to fly on air test to check out a modification.", "correct": true}, {"id": "c", "text": "After a Certificate of Maintenance Review has been signed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When there is an overlap of responsibility, how is the CRS signed?', '[{"id": "a", "text": "Appropriate Type Rated Licensed Aircraft Engineers must each certify the parts appropriate to their license", "correct": true}, {"id": "b", "text": "Only one appropriate Type Rated Licensed Aircraft Engineer may sign the CRS as he assumes responsibility for the", "correct": false}, {"id": "c", "text": "An appropriate Type Rated Licensed Aircraft Engineer and an ATPL holder sign the CRS when the aircraft is away from", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Information contained in the ANO is', '[{"id": "a", "text": "of a legal nature in all sections and is therefore mandatory.", "correct": false}, {"id": "b", "text": "of a mandatory nature where safety is concerned", "correct": true}, {"id": "c", "text": "written in compliance of the Civil Aviation Act of 1943 ratifying the ICAO Convention.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Air Navigation General Regulations are to be found in', '[{"id": "a", "text": "Airworthiness Requirements CAP 455.", "correct": false}, {"id": "b", "text": "British Civil Airworthiness Requirements Section A.", "correct": false}, {"id": "c", "text": "CAA Printed Manual CAP 393.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The information in the ANO is given in the form of', '[{"id": "a", "text": "Articles of Law, some of which are further clarified by Schedules.", "correct": true}, {"id": "b", "text": "Chapters, each one dealing with a different aspect of Civil Aviation, these chapters being backed up by the schedules.", "correct": false}, {"id": "c", "text": "Regulations, each one covering a different aspect of Civil Aviation and as such is mandatory.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'British Civil Airworthiness Requirements', '[{"id": "a", "text": "form the Technical requirements for the design and operation of aircraft and their equipment.", "correct": true}, {"id": "b", "text": "interpret the ANO and form the Technical requirements for the design.", "correct": false}, {"id": "c", "text": "are printed by the CAA and are of an advisory nature.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A CMR is raised after', '[{"id": "a", "text": "defect rectification.", "correct": false}, {"id": "b", "text": "scheduled servicing at specified intervals.", "correct": true}, {"id": "c", "text": "major overhaul.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Compliance with the ANO is restricted to', '[{"id": "a", "text": "aircraft and their equipment which are on the UK Civil Register only.", "correct": true}, {"id": "b", "text": "aircraft and their equipment which are on the UK & Commonwealth Civil Registers.", "correct": false}, {"id": "c", "text": "All civil aircraft and their equipment on the international Civil Register.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Certificate of Release to service states that', '[{"id": "a", "text": "a task has been carried out in accordance with the ANO.", "correct": false}, {"id": "b", "text": "an operator has satisfied the CAA of his competence.", "correct": false}, {"id": "c", "text": "the aircraft has been maintained to an approved schedule.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Technical and Administrative information is officially circulated to L.A.M.E.S. in', '[{"id": "a", "text": "B.C.A.R.s.", "correct": false}, {"id": "b", "text": "A.W.N.s.", "correct": true}, {"id": "c", "text": "CAIP.s.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Which of the following NDT methods can be carried out and certified by a mechanic not approved specifically for NDT inspections?', '[{"id": "a", "text": "Ultrasonic", "correct": false}, {"id": "b", "text": "Magnetic Particle", "correct": false}, {"id": "c", "text": "Neither of proposed.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'B.C.A.R’s', '[{"id": "a", "text": "contain minimum requirements to be met.", "correct": true}, {"id": "b", "text": "are issued by Ministry of Trade and Industry.", "correct": false}, {"id": "c", "text": "detail mandatory requirements for aircraft design and construction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The purpose of the CRS is', '[{"id": "a", "text": "to ensure that the log book entry is complete.", "correct": false}, {"id": "b", "text": "to turn a log book or job card entry into a legal document and to ensure that the signatory takes full", "correct": true}, {"id": "c", "text": "to comply with article 15 of the ANO which states that an aircraft must not fly unless it is properly equipped for the", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Duplicate inspections are', '[{"id": "a", "text": "inspections which have to be duplicated but which can finally be certified by one LAE or approved signatory.", "correct": false}, {"id": "b", "text": "inspections certified by one approved signatory or LAE and then certified by a second approved signatory or", "correct": true}, {"id": "c", "text": "inspections signed by a mechanic and countersigned by an approved signatory or licensed engineer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'The technical laws relating to Civil Aviation are contained in', '[{"id": "a", "text": "the Civil Aircraft Inspection Procedures.", "correct": false}, {"id": "b", "text": "the Air Navigation Order.", "correct": true}, {"id": "c", "text": "the Civil Aviation Act 1971.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Civil aircraft manufactured in the UK are constructed from parts that have been', '[{"id": "a", "text": "manufactured to approved drawings.", "correct": true}, {"id": "b", "text": "manufactured by British Aerospace.", "correct": false}, {"id": "c", "text": "tested to destruction.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Design drawings of aircraft components are produced by organisations approved by', '[{"id": "a", "text": "C.A.A. in accordance with BCAR.", "correct": true}, {"id": "b", "text": "British Standards Institute.", "correct": false}, {"id": "c", "text": "S.B.A.C.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Civil Aircraft Airworthiness Information Procedures', '[{"id": "a", "text": "contain information of a mandatory nature.", "correct": false}, {"id": "b", "text": "contain approved inspection schedules.", "correct": false}, {"id": "c", "text": "are a guide to the general maintenance of aircraft.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'British Civil Airworthiness Requirements', '[{"id": "a", "text": "specify the minimum qualifications for aircrew and engineers.", "correct": false}, {"id": "b", "text": "list the minimum design requirements for aircraft.", "correct": true}, {"id": "c", "text": "give General technical information.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What work has to be recorded and signed for?', '[{"id": "a", "text": "Only work which entails a duplicate inspection.", "correct": false}, {"id": "b", "text": "Only work involving replacements.", "correct": false}, {"id": "c", "text": "All work carried out.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Are CAAIP. mandatory?', '[{"id": "a", "text": "Only selected parts which are in B.C.A.R.", "correct": false}, {"id": "b", "text": "Yes, but only for six months at a time.", "correct": false}, {"id": "c", "text": "No, nothing in CAAIPs is mandatory.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'With a serviceable chain not required for use, how should you store it?', '[{"id": "a", "text": "Lay the chain flat in full length , lubricate and wrap in brown paper to exclude all dirt and moisture.", "correct": true}, {"id": "b", "text": "Clean, lubricate, wrap the chain in grease proof paper and suspend.", "correct": false}, {"id": "c", "text": "Carefully coil, lubricate, lay flat and wrap in grease proof paper.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the licensed engineer responsible for when fitting a new component to an aircraft?', '[{"id": "a", "text": "That the paperwork is signed by an approved signatory.", "correct": false}, {"id": "b", "text": "That is has a green serviceable tag.", "correct": false}, {"id": "c", "text": "The correct part number, the modification state and the serviceability of the component.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an aircraft exceeded the RVSM, when shall the crew report the incident in the appropriate channels?', '[{"id": "a", "text": "48 hrs", "correct": false}, {"id": "b", "text": "24 hrs", "correct": true}, {"id": "c", "text": "72 hrs", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If the aircraft is away from base who may certify the second part of the duplicate inspection?', '[{"id": "a", "text": "a pilot with a licence for the aircraft type.", "correct": true}, {"id": "b", "text": "a pilot with a licence for any similar aircraft type.", "correct": false}, {"id": "c", "text": "any licensed engineer.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Block cumulative maintenance means that', '[{"id": "a", "text": "all the checks require the same man hour input except for the major inspections.", "correct": false}, {"id": "b", "text": "each check usually involves an increased aircraft down time.", "correct": true}, {"id": "c", "text": "all the maintenance is carried out in blocks.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A separate modification record book is required for', '[{"id": "a", "text": "passenger aircraft exceeding 2730 kgs MTWA.", "correct": false}, {"id": "b", "text": "all aircraft.", "correct": true}, {"id": "c", "text": "passenger aircraft exceeding 3600 kgs MTWA.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Sector record pages from the Tech Logs, must be', '[{"id": "a", "text": "at least duplicated.", "correct": false}, {"id": "b", "text": "retained for two years from the date of issue.", "correct": false}, {"id": "c", "text": "retained for four years from the last effective date.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Minimum equipment to be carried is listed in', '[{"id": "a", "text": "JAR 145.", "correct": false}, {"id": "b", "text": "JAR OPS.", "correct": true}, {"id": "c", "text": "JAR 25.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What should be checked before a licensed engineer signs a CRS?', '[{"id": "a", "text": "That he/she has worked for 6 months on the aircraft type within the previous 2 years.", "correct": false}, {"id": "b", "text": "That he/she has worked for 4 months on the aircraft type within the previous 2 years.", "correct": true}, {"id": "c", "text": "That he/she has had continuation training within the previous 2 years.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Rubber components should be stored', '[{"id": "a", "text": "in a cool dark area.", "correct": true}, {"id": "b", "text": "in warm and humid conditions.", "correct": false}, {"id": "c", "text": "in a well lit room.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Storage of components to prevent corrosion is helped', '[{"id": "a", "text": "by using silica gel.", "correct": true}, {"id": "b", "text": "by wrapping in grease proof paper.", "correct": false}, {"id": "c", "text": "by placing them in a plastic box.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Dye penetrant kits should be stored', '[{"id": "a", "text": "out of sunlight in a dry place.", "correct": true}, {"id": "b", "text": "in direct sunlight to keep it dry.", "correct": false}, {"id": "c", "text": "in a dark damp cupboard.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When receiving new parts it is the responsibility of the engineer to check', '[{"id": "a", "text": "it has a green serviceable label attached.", "correct": true}, {"id": "b", "text": "it is of the correct modification state and is serviceable.", "correct": false}, {"id": "c", "text": "it was designed to acceptable standards.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'For airworthiness purposes, aircraft structural parts are graded as', '[{"id": "a", "text": "primary, secondary and tertiary.", "correct": true}, {"id": "b", "text": "class A, B and C.", "correct": false}, {"id": "c", "text": "1, 2 and 3.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'If an unauthorized repair is carried out', '[{"id": "a", "text": "the aircraft can fly with a Certificate of Fitness for Flight.", "correct": false}, {"id": "b", "text": "the Cof A is invalidated until an authorized repair has been done.", "correct": true}, {"id": "c", "text": "the Cof A is not invalidated providing a CRS is issued.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A C.of A. for export', '[{"id": "a", "text": "does not give authority by it self for the aircraft to fly.", "correct": true}, {"id": "b", "text": "gives authority for the aircraft to fly.", "correct": false}, {"id": "c", "text": "is required before aircraft registration in a foriegn country.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A fitness for flight is issued for an aircraft after a major modification by', '[{"id": "a", "text": "the pilot, type rated on that particular aircraft.", "correct": false}, {"id": "b", "text": "a appropriate licensed aircraft engineer.", "correct": false}, {"id": "c", "text": "a CAA surveyor or person approved within the CAA.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'An unauthorised repair has been carried out', '[{"id": "a", "text": "sign a CRS for the repair.", "correct": false}, {"id": "b", "text": "apply for it as a modification.", "correct": true}, {"id": "c", "text": "carryout an approved repair.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Part-66 licensed engineer, when signing a CRS for a non-Part-145 company would need to have', '[{"id": "a", "text": "maintenance experience for 6 months within the last 24 months.", "correct": false}, {"id": "b", "text": "an aircraft type refresher in the last 24 months.", "correct": false}, {"id": "c", "text": "maintenance experience for 4 months within the last 24 months.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A National UK licensed engineer, when signing a CRS would need to have', '[{"id": "a", "text": "an aircraft type refresher in the last 24 months.", "correct": false}, {"id": "b", "text": "maintenance experience for 4 months within the last 24 months.", "correct": true}, {"id": "c", "text": "maintenance experience for 6 months within the last 24 months.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Vital point inspections', '[{"id": "a", "text": "are points which require special certifying LAEs.", "correct": false}, {"id": "b", "text": "are components which involve duplicate inspections.", "correct": true}, {"id": "c", "text": "are lifed components.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'On a pre flight check you notice an instrument glass is cracked. You should', '[{"id": "a", "text": "enter into technical log.", "correct": true}, {"id": "b", "text": "check MEL.", "correct": false}, {"id": "c", "text": "tell oncoming captain.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'A Category-A licenced engineer can sign a CRS for what?', '[{"id": "a", "text": "A task he has been locally trained for.", "correct": true}, {"id": "b", "text": "An aircraft that he has sufficient type ratings for.", "correct": false}, {"id": "c", "text": "A task that someone else has completed.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'When removing a piece of equipment from an aircraft that supports the aircraft, what should you do?', '[{"id": "a", "text": "Go ahead and remove the part.", "correct": false}, {"id": "b", "text": "Wait for the new part to arrive before replacing.", "correct": false}, {"id": "c", "text": "Fit a jury strut in place of the removed part.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'How do you prime a dead weight tester?', '[{"id": "a", "text": "Wind handle fully out and pour fluid in the reservoir.", "correct": true}, {"id": "b", "text": "Remove the weights and pour fluid into the hole.", "correct": false}, {"id": "c", "text": "Wind handle fully in and pour fluid in the reservoir.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the problem with using a megger on a piece of equipment containing capacitors?', '[{"id": "a", "text": "Fluctuating readings will occur while the capacitors charge up.", "correct": true}, {"id": "b", "text": "Feedback from the capacitors will blow the megger up.", "correct": false}, {"id": "c", "text": "Impedance in the capacitors will give a false high reading.", "correct": false}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'Water marks on bearings are indications of', '[{"id": "a", "text": "bearing insufficiently lubricated.", "correct": false}, {"id": "b", "text": "intergranular corrosion.", "correct": false}, {"id": "c", "text": "bearing been run dry.", "correct": true}]'::jsonb, '{B1,B2}'),
    ((SELECT id FROM easa_subjects WHERE code = 'M07.9'), 'What is the allowable reaction on a rivet?', '[{"id": "a", "text": "2D", "correct": false}, {"id": "b", "text": "1D", "correct": true}, {"id": "c", "text": "1.5D", "correct": false}]'::jsonb, '{B1,B2}');
